// Content for Find Your Feet (node g52, ages 18–22, Chapter 6) — NEW v2 build to GDD 52 (mechanic-embodying),
// completing the College wellbeing cluster (g48, g49, g52) (Thread C · Feelings & Life Skills). Reworks the old
// ModesEngine build onto the shared v2 engine. "Spoiler: no one has it figured out." 84 researched, India-grounded
// scenarios across comparison-trap → not-all-sorted → bounce-from-setbacks → worth-beyond-cv → your-path →
// tools-and-help, each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort / reflect /
// role-play / match / spot) — no binary "tap the right card". Lead: branch (your move), strike-rewrite (bust the
// myth), sort. Five themes: the comparison trap (UN&RE), you don't need it all sorted, bounce from setbacks, your
// path (worth beyond CV), tools & crisis routing. Reframes the comparison spiral, the pressure to have life
// figured out, the placement/exam cooker and fear of failure: no one has it sorted, setbacks are information not
// verdicts, failure is a comma not a full stop, your worth is not your CV. WELLBEING-SENSITIVE: healthy coping
// only, never reinforces hopelessness or 'you've failed', worth-beyond-CV throughout, crisis routing with warmth
// (Tele-MANAS 14416, a counsellor); NOT careers-counselling or therapy, signposts both.
// India: placement seasons, competitive exams (JEE/NEET/UPSC), the 'settled job' ideal, family expectations and
// intense peer comparison, validated then gently loosened. Builds on g42 (Life Ready) & g39 (Bounce); pairs g48
// and g49. gameId "find-your-feet".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"ff-001","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Everyone else has it figured out; I'm the only one behind.\"","myth":{"un":"Everyone else has it figured out; I'm the only one behind.","re":"No one has it figured out; you're comparing your behind-the-scenes to their highlight reel.","why":"People post wins, not the doubts and rejections."},"relearn":"No one has it figured out; you're comparing your insides to others' highlight reels.","persona":"Deepak","source":"the comparison myth"},
  {"id":"ff-002","cat":"comparison-trap","type":"sort","hook":"Sort: the real picture, or the highlight reel?","items":[{"id":"a","text":"The offer letter posted online"},{"id":"b","text":"The 30 rejections not posted"},{"id":"c","text":"The 'living my best life' caption"},{"id":"d","text":"The quiet 3am worry behind it"},{"id":"e","text":"The smiling first-day photo"},{"id":"f","text":"The fear that it won't work out"}],"bins":[{"id":"reel","label":"Highlight reel","valence":"uhoh"},{"id":"real","label":"The real picture","valence":"pos"}],"key":{"a":"reel","b":"real","c":"reel","d":"real","e":"reel","f":"real"},"relearn":"Offers and captions are the highlight reel; the rejections and worry behind them are the real picture.","persona":"any","source":"behind the reel"},
  {"id":"ff-003","cat":"comparison-trap","type":"branch","hook":"Scrolling everyone's placement and success posts is spiking your anxiety.","options":[{"text":"Step back from the feed and refocus on your own path","consequence":"You protect your headspace.","outcome":"refocused","best":true},{"text":"Keep scrolling and comparing","consequence":"Stepping back from the success feed protects you; endless comparison just feeds the anxiety."}],"debrief":"Curated success feeds fuel comparison anxiety; stepping back and refocusing on your own path helps.","relearn":"Step back from success feeds; refocus on your own path.","persona":"any","source":"feed breaks"},
  {"id":"ff-004","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Comparing myself to others pushes me to do better.\"","myth":{"un":"Comparison pushes me to do better.","re":"Comparison mostly fuels anxiety and shame; your own values-based steps drive you better.","why":"Inadequacy is a poor long-term motivator."},"relearn":"Comparison mostly fuels anxiety; your own values-based steps motivate you better.","persona":"any","source":"comparison vs motivation"},
  {"id":"ff-005","cat":"comparison-trap","type":"spot","hook":"Spot the two comparison-thief thoughts to catch (the rest hold your own path).","scene":[{"id":"a","text":"\"I'll never measure up to them\"","trick":true},{"id":"b","text":"\"My path is my own\"","trick":false},{"id":"c","text":"\"Their highlight reel isn't my reality\"","trick":false},{"id":"d","text":"\"If they're winning, I'm losing\"","trick":true},{"id":"e","text":"\"I can be glad for them and steady in myself\"","trick":false}],"why":"'Never measure up' and 'if they win, I lose' are the comparison thief; owning your path and naming highlight reels isn't.","relearn":"Comparison is the thief of joy, and never a fair fight against an edit.","persona":"any","source":"the thief"},
  {"id":"ff-006","cat":"comparison-trap","type":"sort","hook":"Sort: eases comparison anxiety, or feeds it?","items":[{"id":"a","text":"Curating who you follow"},{"id":"b","text":"Stalking peers' achievements"},{"id":"c","text":"Talking honestly with friends"},{"id":"d","text":"Measuring yourself by likes"},{"id":"e","text":"Taking breaks from the feed"},{"id":"f","text":"Refreshing the placement list all day"}],"bins":[{"id":"eases","label":"Eases it","valence":"pos"},{"id":"feeds","label":"Feeds it","valence":"neg"}],"key":{"a":"eases","b":"feeds","c":"eases","d":"feeds","e":"eases","f":"feeds"},"relearn":"Curating your feed, honest talk and breaks ease comparison; stalking achievements and like-counting feed it.","persona":"any","source":"managing comparison"},
  {"id":"ff-007","cat":"comparison-trap","type":"role-play","hook":"A friend shares big career news and you feel a pang of comparison.","relearn":"Be warm at a friend's success; their win isn't your loss.","persona":"any","source":"celebrating others","setup":"Lead with warmth anyway. Say:","yourLine":[{"text":"\"That's brilliant, I'm genuinely happy for you!\"","best":true},{"text":"Let the envy sour your response"}]},
  {"id":"ff-008","cat":"comparison-trap","type":"spot","hook":"Spot the two comparison-trap thoughts to catch (the rest are truer reads).","scene":[{"id":"a","text":"\"They're all ahead of me\"","trick":true},{"id":"b","text":"\"Everyone's timeline is different\"","trick":false},{"id":"c","text":"\"I must be failing if they're winning\"","trick":true},{"id":"d","text":"\"Their win takes nothing from me\"","trick":false},{"id":"e","text":"\"I'm comparing my insides to their highlights\"","trick":false}],"why":"'They're all ahead' and 'I'm failing if they win' are comparison traps; different timelines and 'win takes nothing' aren't.","relearn":"'Everyone's ahead' and 'their win means my failure' are comparison traps.","persona":"any","source":"spotting the trap"},
  {"id":"ff-009","cat":"comparison-trap","type":"strike-rewrite","hook":"\"If I haven't succeeded by a certain age, I've failed at life.\"","myth":{"un":"If I haven't succeeded by a certain age, I've failed at life.","re":"There's no universal timeline; everyone's path unfolds differently and at its own pace.","why":"Life isn't a race with one finish line."},"relearn":"There's no universal timeline; paths unfold differently and at their own pace.","persona":"any","source":"no timeline"},
  {"id":"ff-010","cat":"comparison-trap","type":"role-play","hook":"A parent keeps comparing you to a cousin who 'has it sorted'.","relearn":"Hold your own path; a relative's success isn't your yardstick.","persona":"Aarti","source":"family comparison","setup":"Hold your path gently. Say:","yourLine":[{"text":"\"We're on different paths, and I'm doing okay on mine.\"","best":true},{"text":"Take it as proof you're behind"}]},
  {"id":"ff-011","cat":"comparison-trap","type":"sort","hook":"Sort: a fair comparison, or an unfair one?","items":[{"id":"a","text":"You now vs you last year"},{"id":"b","text":"Your start vs their finish"},{"id":"c","text":"Your progress vs your goals"},{"id":"d","text":"Your reality vs their highlights"},{"id":"e","text":"Your effort vs your own last attempt"},{"id":"f","text":"Your day one vs their year five"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Measuring against your past self and your goals is fair; against others' finish or highlights isn't.","persona":"any","source":"fair measures"},
  {"id":"ff-012","cat":"comparison-trap","type":"branch","hook":"You realise your feed is mostly people who make you feel behind.","options":[{"text":"Curate it toward what inspires, not what shames","consequence":"You change your daily inputs.","outcome":"curated","best":true},{"text":"Keep consuming what makes you feel worse","consequence":"Curating your feed toward inspiring, not shaming, content changes how you feel daily."}],"debrief":"Your feed shapes your mood; curating it away from shame-triggers is real self-care.","relearn":"Curate your feed toward what inspires, away from what shames you.","persona":"any","source":"curating inputs"},
  {"id":"ff-013","cat":"comparison-trap","type":"strike-rewrite","hook":"\"The people who seem to have it all together are never anxious.\"","relearn":"The people you envy are often quietly envying someone too.","persona":"any","source":"everyone compares","myth":{"un":"The people who seem to have it all together are never anxious.","re":"The people you envy are often quietly envying someone too; almost everyone feels behind sometimes.","why":"Outer confidence hides inner doubt."}},
  {"id":"ff-014","cat":"comparison-trap","type":"role-play","hook":"A friend is crushed comparing themselves to everyone's success posts.","setup":"Reframe it for them. Say:","yourLine":[{"text":"\"That's their highlight reel, not their whole story. You're not behind, just on your own path.\"","best":true},{"text":"\"Yeah, you're kind of falling behind.\""}],"relearn":"Remind a friend that success posts are highlight reels, not the whole story.","persona":"any","source":"supporting a friend"},
  {"id":"ff-015","cat":"comparison-trap","type":"sort","hook":"Sort: a kind, true thought, or a comparison distortion?","items":[{"id":"a","text":"\"I'm making my own progress\""},{"id":"b","text":"\"Everyone's better than me\""},{"id":"c","text":"\"Their path isn't mine\""},{"id":"d","text":"\"I'm hopelessly behind\""},{"id":"e","text":"\"Not knowing yet is okay\""},{"id":"f","text":"\"If they win, I lose\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"distortion","label":"Distortion","valence":"neg"}],"key":{"a":"kind","b":"distortion","c":"kind","d":"distortion","e":"kind","f":"distortion"},"relearn":"'My own progress' and 'their path isn't mine' are true; 'everyone's better' and 'hopelessly behind' are distortions.","persona":"any","source":"self-talk"},
  {"id":"ff-016","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"I need my whole life and career planned out right now.\"","myth":{"un":"I need my whole life planned out now.","re":"Uncertainty at this age is normal; small next steps beat a perfect master plan.","why":"No one can plan a whole life in advance."},"relearn":"Uncertainty is normal; small next steps beat a perfect master plan.","persona":"any","source":"no master plan"},
  {"id":"ff-017","cat":"not-all-sorted","type":"reflect","hook":"Lensy: the honest headline, no one really has it all figured out, even the confident ones. Believe it?","prompt":"What do you think?","options":["Yes","No one's sorted","A relief"],"affirm":"It's genuinely true: almost everyone is figuring it out as they go, including the confident ones.","relearn":"No one really has it all figured out, even the confident ones.","persona":"any","source":"the headline"},
  {"id":"ff-018","cat":"not-all-sorted","type":"branch","hook":"You feel panicked because you don't know exactly what you want to do.","options":[{"text":"Accept that not knowing yet is okay and explore","consequence":"You replace panic with curiosity.","outcome":"exploring","best":true},{"text":"Force a decision just to escape the discomfort","consequence":"Allowing yourself not to know yet, and exploring, beats forcing a decision to escape discomfort."}],"debrief":"Not knowing yet is a normal, workable place to be; exploration is part of the process.","relearn":"It's okay not to know yet; let yourself explore.","persona":"Deepak","source":"not knowing yet"},
  {"id":"ff-019","cat":"not-all-sorted","type":"match","hook":"Match the realistic truth to the pressure it answers.","relearn":"Changing direction and pivoting are realistic; 'first job decides all' and 'sorted now' are unfair pressure.","persona":"any","source":"realistic stage","pairs":[{"left":"I can change direction later","right":"\"My first job decides all\""},{"left":"Most people pivot","right":"\"I must be certain now\""},{"left":"It's okay not to know yet","right":"\"Everyone else is sure\""},{"left":"Small steps beat a master plan","right":"\"I need the whole thing planned\""},{"left":"I'm early, not late","right":"\"I'm running out of time\""}]},
  {"id":"ff-020","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Changing my mind about my path means I've wasted time.\"","myth":{"un":"Changing my path means I wasted time.","re":"Exploring and pivoting is how most people find a fit; nothing learned is wasted.","why":"Detours often teach the most."},"relearn":"Changing your path isn't wasted time; exploring is how a fit is found.","persona":"any","source":"pivoting"},
  {"id":"ff-021","cat":"not-all-sorted","type":"role-play","hook":"Someone asks 'so what's your plan?' and you don't have a neat answer.","relearn":"'I'm exploring' is a valid answer; you don't need a neat master plan.","persona":"any","source":"the plan question","setup":"Answer honestly. Say:","yourLine":[{"text":"\"I'm still exploring, honestly, and I'm okay with that.\"","best":true},{"text":"Panic and fake a master plan"}]},
  {"id":"ff-022","cat":"not-all-sorted","type":"reflect","hook":"Lensy: a career is a long, winding road, not a single leap you must nail at 21. Easier breathing?","prompt":"What do you think?","options":["Yes","A long road","Less pressure"],"affirm":"A working life is decades long and winding; you don't have to nail it all at twenty-one.","relearn":"A career is a long, winding road, not one leap you must nail at 21.","persona":"any","source":"the long road"},
  {"id":"ff-023","cat":"not-all-sorted","type":"match","hook":"Match the healthy response to uncertainty to the anxious one it replaces.","relearn":"Trying things and asking around is a healthy response to uncertainty; freezing or panic-applying isn't.","persona":"any","source":"responding to uncertainty","pairs":[{"left":"Try things to learn fits","right":"Freezing in indecision"},{"left":"Ask about others' paths","right":"Panic-applying everywhere"},{"left":"Take a next step","right":"Waiting for total certainty"},{"left":"Sleep, then decide","right":"Choosing in a 2am panic"},{"left":"Talk it through with a mentor","right":"Spiralling about it alone"}]},
  {"id":"ff-024","cat":"not-all-sorted","type":"branch","hook":"You feel behind because you haven't 'specialised' like some peers.","options":[{"text":"Value being a generalist and a late bloomer too","consequence":"You drop a false hierarchy.","outcome":"valued","best":true},{"text":"Assume early specialists always win","consequence":"Generalists and late bloomers thrive too; early specialisation isn't the only winning path."}],"debrief":"There's no single right speed or shape to a career; generalists and late bloomers do just fine.","relearn":"Generalists and late bloomers thrive too; there's no one right path-shape.","persona":"any","source":"many shapes"},
  {"id":"ff-025","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"If I don't get the 'right' first job, my whole future is set.\"","myth":{"un":"My first job sets my whole future.","re":"Your first job is a starting point, not a life sentence; careers shift constantly.","why":"Almost no one ends where they began."},"relearn":"Your first job is a starting point, not a life sentence.","persona":"any","source":"first job"},
  {"id":"ff-026","cat":"not-all-sorted","type":"reflect","hook":"Lensy: it's okay for your path to look different from the one your family imagined. Permission?","prompt":"What do you think?","options":["Yes","My own path","That helps"],"affirm":"Your path can differ from what others imagined and still be a good, valid one.","relearn":"It's okay for your path to differ from the one others imagined.","persona":"Zoya","source":"your own path"},
  {"id":"ff-027","cat":"not-all-sorted","type":"branch","hook":"The pressure to 'have it sorted' is making you anxious and stuck.","options":[{"text":"Trade the master plan for one small next step","consequence":"You unstick yourself with action.","outcome":"unstuck","best":true},{"text":"Wait until you can see the whole path","consequence":"One small next step beats waiting to see the whole path; that's how you get unstuck."}],"debrief":"You don't need the whole map; a single next step is enough to start moving.","relearn":"Trade the master plan for one small next step.","persona":"any","source":"next step"},
  {"id":"ff-028","cat":"not-all-sorted","type":"match","hook":"Match the uncertainty truth to its reassurance.","relearn":"Most not knowing yet and figuring it out as you go is true; 'failing' and 'everyone's certain' are false.","persona":"any","source":"uncertainty facts","pairs":[{"left":"Most don't know yet either","right":"You're not alone"},{"left":"Figure it out as you go","right":"No master plan needed"},{"left":"Not knowing isn't failing","right":"It's a beginning"},{"left":"Confident faces hide doubt too","right":"It's not just you"},{"left":"Curiosity can guide you","right":"A compass without a fixed plan"}]},
  {"id":"ff-029","cat":"not-all-sorted","type":"reflect","hook":"Lensy: 'I don't know yet' is the start of finding out, not a failure. Reframe it that way?","prompt":"What do you think?","options":["Yes","Start of finding out","Not failure"],"affirm":"'I don't know yet' is simply where finding out begins; it's a beginning, not a verdict.","relearn":"'I don't know yet' is the start of finding out, not a failure.","persona":"any","source":"reframe"},
  {"id":"ff-030","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"A bad result or rejection means I'm a failure.\"","myth":{"un":"A bad result or rejection means I'm a failure.","re":"Setbacks are information, not verdicts; they tell you something to adjust, not who you are.","why":"One outcome doesn't define you."},"relearn":"Setbacks are information, not verdicts on who you are.","persona":"any","source":"information not verdict"},
  {"id":"ff-031","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"If I fail this exam, my career is over.\"","myth":{"un":"If I fail this exam, my career is over.","re":"Exam failure rarely ends a career; it's a comma, not a full stop, and often redirects you to a better fit.","why":"There are many routes onward."},"relearn":"Exam failure is a comma, not a full stop; it often redirects to a better fit.","persona":"Deepak","source":"exam failure"},
  {"id":"ff-032","cat":"bounce-from-setbacks","type":"branch","hook":"You got rejected from something you really wanted.","options":[{"text":"Feel it, then ask what it teaches and try again","consequence":"You turn the setback into a step.","outcome":"resilient","best":true},{"text":"Take it as proof you're not good enough","consequence":"Feeling it, then asking what it teaches and trying again, beats reading a rejection as proof of your worth."}],"debrief":"Rejection stings, but treating it as feedback to learn from is what builds resilience.","relearn":"After a rejection, feel it, learn from it, and try again.","persona":"any","source":"after rejection"},
  {"id":"ff-033","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: a growth-mindset response, or a fixed one?","items":[{"id":"a","text":"\"I'll try a different approach\""},{"id":"b","text":"\"I'm just not capable\""},{"id":"c","text":"\"What can I learn here?\""},{"id":"d","text":"\"There's no point trying\""},{"id":"e","text":"\"This is hard, but I can improve\""},{"id":"f","text":"\"Some people are born for this; I'm not\""}],"bins":[{"id":"growth","label":"Growth","valence":"pos"},{"id":"fixed","label":"Fixed","valence":"neg"}],"key":{"a":"growth","b":"fixed","c":"growth","d":"fixed","e":"growth","f":"fixed"},"relearn":"'Try a different approach', 'what can I learn' and 'I can improve' are growth; 'not capable', 'no point' and 'not born for this' are fixed.","persona":"any","source":"growth mindset"},
  {"id":"ff-034","cat":"bounce-from-setbacks","type":"branch","hook":"A placement season goes badly and you feel crushed.","options":[{"text":"Lean on support and keep options open; this isn't the end","consequence":"You stay afloat and keep moving.","outcome":"afloat","best":true},{"text":"Conclude your future is ruined","consequence":"Leaning on support and keeping options open helps; a hard placement season isn't the end of your future."}],"debrief":"A rough placement season is painful but not final; support and open options carry you onward.","relearn":"A bad placement season isn't the end; lean on support and keep options open.","persona":"any","source":"placement cooker"},
  {"id":"ff-035","cat":"bounce-from-setbacks","type":"role-play","hook":"A friend just failed something big and is spiralling.","setup":"Steady them with care. Say:","yourLine":[{"text":"\"This is a setback, not the end of your story, and it doesn't define you. I'm here.\"","best":true},{"text":"\"Yeah, that's pretty bad for you.\""}],"relearn":"Remind a struggling friend a setback isn't the end of their story.","persona":"any","source":"supporting a friend"},
  {"id":"ff-036","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"Successful people don't fail.\"","myth":{"un":"Successful people don't fail.","re":"Almost everyone successful has a trail of failures behind them; it's part of the path.","why":"You only see their wins, not the falls."},"relearn":"Successful people fail plenty; the failures just aren't the part you see.","persona":"any","source":"failure is normal"},
  {"id":"ff-037","cat":"bounce-from-setbacks","type":"branch","hook":"You're so afraid of failing that you avoid trying at all.","options":[{"text":"Take a small risk; trying and learning beats not trying","consequence":"You break the avoidance.","outcome":"brave","best":true},{"text":"Avoid it to stay 'safe'","consequence":"Trying and possibly learning beats avoiding; fear of failure shouldn't stop you starting."}],"debrief":"Avoiding all risk to dodge failure is its own kind of loss; small brave attempts grow you.","relearn":"Take small risks; trying and learning beats never trying.","persona":"any","source":"fear of failure"},
  {"id":"ff-038","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: helps you bounce back, or keeps you down?","items":[{"id":"a","text":"Treating failure as feedback"},{"id":"b","text":"Globalising it to 'I'm a failure'"},{"id":"c","text":"Asking for support"},{"id":"d","text":"Isolating in shame"},{"id":"e","text":"Planning one small next step"},{"id":"f","text":"Replaying the mistake at 3am"}],"bins":[{"id":"bounce","label":"Helps you bounce","valence":"pos"},{"id":"down","label":"Keeps you down","valence":"neg"}],"key":{"a":"bounce","b":"down","c":"bounce","d":"down","e":"bounce","f":"down"},"relearn":"Treating failure as feedback, seeking support and planning a small step help you bounce; globalising, isolating and replaying it keep you down.","persona":"any","source":"bouncing back"},
  {"id":"ff-039","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two lines that are fear talking, not the truth.","scene":[{"id":"a","text":"\"This taught me what to change\"","trick":false},{"id":"b","text":"\"I'm fundamentally not good enough\"","trick":true},{"id":"c","text":"\"A different route might suit me better\"","trick":false},{"id":"d","text":"\"One result has decided who I am\"","trick":true},{"id":"e","text":"\"I can adjust and try again\"","trick":false}],"why":"'Not good enough' and 'one result decided who I am' are fear talking; the others ask what to change and adjust.","relearn":"A resilient reframe asks what a setback teaches, not whether you're good enough.","persona":"any","source":"reframing"},
  {"id":"ff-040","cat":"bounce-from-setbacks","type":"branch","hook":"You did worse than expected and your inner voice is brutal.","options":[{"text":"Speak to yourself as you would a struggling friend","consequence":"You recover with self-compassion.","outcome":"kind","best":true},{"text":"Pile on the self-criticism","consequence":"Self-compassion, talking to yourself like a friend, helps you recover; brutal self-criticism doesn't."}],"debrief":"Self-compassion after a setback aids recovery far more than harsh self-criticism.","relearn":"After a setback, talk to yourself like a struggling friend, not a critic.","persona":"any","source":"self-compassion"},
  {"id":"ff-041","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: every setback carries a lesson, and bouncing back is a skill you can build. Believe it?","prompt":"What do you think?","options":["Yes","Bouncing is a skill","I can build it"],"affirm":"Resilience is learnable; each setback you move through makes the next one more survivable.","relearn":"Setbacks carry lessons, and bouncing back is a skill you can build.","persona":"any","source":"resilience is learnable"},
  {"id":"ff-042","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two lines that are fear talking, not setback-truth.","relearn":"'A detour, not a dead end' and 'I can recover' are true; 'ruined' and 'judged forever' are fear talking.","persona":"any","source":"truth vs fear","scene":[{"id":"a","text":"\"This is a detour, not a dead end\"","trick":false},{"id":"b","text":"\"My life is ruined\"","trick":true},{"id":"c","text":"\"I can recover from this\"","trick":false},{"id":"d","text":"\"Everyone will judge me forever\"","trick":true},{"id":"e","text":"\"This stings now, but it passes\"","trick":false}],"why":"'Ruined' and 'judged forever' are fear talking; a detour, recovering and 'it passes' are true."},
  {"id":"ff-043","cat":"bounce-from-setbacks","type":"branch","hook":"After a failure, you want to just give up on the goal entirely.","options":[{"text":"Rest, then decide from a calmer place","consequence":"You avoid a panic-decision.","outcome":"calm","best":true},{"text":"Quit everything in the heat of it","consequence":"Resting and deciding from a calmer place beats quitting everything in the raw heat of a failure."}],"debrief":"Big decisions made in the immediate sting of failure are rarely your best; rest first.","relearn":"After a failure, rest before deciding; don't quit in the heat of it.","persona":"any","source":"don't decide raw"},
  {"id":"ff-044","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"Needing more time or another attempt is shameful.\"","myth":{"un":"Needing more time or another attempt is shameful.","re":"Many paths involve a second attempt or a longer route; that's effort, not shame.","why":"Persistence is something to respect."},"relearn":"Needing more time or another attempt is persistence, not shame.","persona":"any","source":"second attempts"},
  {"id":"ff-045","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: the dip you're in now is a chapter, not the whole book. Hold onto that?","prompt":"What do you think?","options":["Yes","Just a chapter","It passes"],"affirm":"This hard chapter is part of a much longer story; it passes, and the book goes on.","relearn":"A setback is a chapter, not the whole book.","persona":"any","source":"a chapter"},
  {"id":"ff-046","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"My worth is my marks, package or job title.\"","myth":{"un":"My worth is my marks, package or job title.","re":"Your worth isn't your CV; you are far more than your achievements and status.","why":"A person's value was never a number."},"relearn":"Your worth isn't your CV; you're far more than your achievements and status.","persona":"any","source":"worth beyond CV"},
  {"id":"ff-047","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"A mark sheet is a verdict on who I am.\"","myth":{"un":"A mark sheet is a verdict on who I am.","re":"A result measures one test on one day, not your identity, character or potential.","why":"You are not a number on a page."},"relearn":"A mark sheet measures one test, not your identity or potential.","persona":"Deepak","source":"not a verdict"},
  {"id":"ff-048","cat":"worth-beyond-cv","type":"sort","hook":"Sort: part of your real worth, or just a status marker?","items":[{"id":"a","text":"Your kindness and character"},{"id":"b","text":"Your salary package"},{"id":"c","text":"How you treat people"},{"id":"d","text":"Your college's 'tier'"},{"id":"e","text":"The way you keep promises"},{"id":"f","text":"A title that sounds impressive"}],"bins":[{"id":"worth","label":"Real worth","valence":"pos"},{"id":"status","label":"Status marker","valence":"neg"}],"key":{"a":"worth","b":"status","c":"worth","d":"status","e":"worth","f":"status"},"relearn":"Kindness, character, how you treat people and keeping promises are real worth; package, college 'tier' and impressive titles are status markers.","persona":"any","source":"real worth"},
  {"id":"ff-049","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two lines that value your CV over who you are.","scene":[{"id":"a","text":"\"I love who you are\"","trick":false},{"id":"b","text":"\"Your rank and package are what count\"","trick":true},{"id":"c","text":"\"How you treat me is what I notice\"","trick":false},{"id":"d","text":"\"Without the big job, what's there to value\"","trick":true},{"id":"e","text":"\"You matter to me, results or not\"","trick":false}],"why":"The caught lines value a rank, package and job over the person; the people who matter value who you are.","relearn":"The people who love you value who you are and how you treat them, not your CV.","persona":"any","source":"who matters"},
  {"id":"ff-050","cat":"worth-beyond-cv","type":"branch","hook":"You tie your whole mood to your latest result or offer.","options":[{"text":"Anchor your worth in who you are, off the scoreboard","consequence":"Your mood steadies.","outcome":"anchored","best":true},{"text":"Keep riding every high and low","consequence":"Anchoring worth in who you are, not the scoreboard, steadies you off the result-driven rollercoaster."}],"debrief":"Detaching worth from results gets you off an exhausting emotional rollercoaster.","relearn":"Anchor your worth in who you are, not your latest result.","persona":"any","source":"off the scoreboard"},
  {"id":"ff-051","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a healthy source of self-worth, or a fragile one?","items":[{"id":"a","text":"Your values and relationships"},{"id":"b","text":"Beating everyone else"},{"id":"c","text":"Growth and effort"},{"id":"d","text":"External rank alone"},{"id":"e","text":"Self-respect that stays put"},{"id":"f","text":"Constant approval from others"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"fragile","label":"Fragile","valence":"neg"}],"key":{"a":"healthy","b":"fragile","c":"healthy","d":"fragile","e":"healthy","f":"fragile"},"relearn":"Values, relationships, growth, effort and steady self-respect are healthy self-worth; beating others, rank alone and chasing approval are fragile.","persona":"any","source":"sources of worth"},
  {"id":"ff-052","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"A 'settled' high-status job is the only real success.\"","myth":{"un":"A settled high-status job is the only real success.","re":"Success can be a life that fits your values, not just a prestigious title.","why":"Prestige and fulfilment aren't the same."},"relearn":"Success can be a life that fits your values, not just a prestigious title.","persona":"Aarti","source":"redefining success"},
  {"id":"ff-053","cat":"worth-beyond-cv","type":"branch","hook":"You're tempted to chase a prestigious path you don't actually want, for the status.","options":[{"text":"Weigh what fits you, not just what impresses others","consequence":"You choose from your own values.","outcome":"aligned","best":true},{"text":"Chase the status regardless of fit","consequence":"Weighing what fits you, not just what impresses, leads to a path you can actually live with."}],"debrief":"A prestigious path that doesn't fit you can cost more than it's worth; fit matters.","relearn":"Choose for fit and values, not just status that impresses others.","persona":"any","source":"fit over status"},
  {"id":"ff-054","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: you were a whole, worthy person long before any job or result. Still are. Feel it?","prompt":"What do you think?","options":["Yes","Whole already","Worthy"],"affirm":"Your worth came before any achievement and stays whatever happens with your career.","relearn":"You're a whole, worthy person independent of any job or result.","persona":"any","source":"inherent worth"},
  {"id":"ff-055","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two beliefs that make worth something you have to achieve.","scene":[{"id":"a","text":"\"My worth is steady, whatever my results\"","trick":false},{"id":"b","text":"\"I'm only worth as much as I achieve\"","trick":true},{"id":"c","text":"\"I matter beyond my output\"","trick":false},{"id":"d","text":"\"Stop achieving and I stop mattering\"","trick":true},{"id":"e","text":"\"I'm enough as I am, off the scoreboard\"","trick":false}],"why":"The caught beliefs make worth conditional on achievement; steady worth is unconditional, not earned by output.","relearn":"Your worth is steady and beyond your output, not earned by achievement alone.","persona":"any","source":"healthy beliefs"},
  {"id":"ff-056","cat":"worth-beyond-cv","type":"role-play","hook":"A friend defines their entire value by a job rejection.","setup":"Separate the two for them. Say:","yourLine":[{"text":"\"One rejection isn't a measure of your worth, you're so much more than a job outcome.\"","best":true},{"text":"\"Yeah, that does say a lot about you.\""}],"relearn":"Help a friend separate a job outcome from their worth.","persona":"any","source":"supporting a friend"},
  {"id":"ff-057","cat":"worth-beyond-cv","type":"sort","hook":"Sort: defines a good life, or just looks good to others?","items":[{"id":"a","text":"Meaning and relationships"},{"id":"b","text":"An impressive-sounding title"},{"id":"c","text":"Living by your values"},{"id":"d","text":"Status others envy"},{"id":"e","text":"Work that feels worthwhile to you"},{"id":"f","text":"A designation to drop in conversation"}],"bins":[{"id":"good","label":"A good life","valence":"pos"},{"id":"looks","label":"Just looks good","valence":"neg"}],"key":{"a":"good","b":"looks","c":"good","d":"looks","e":"good","f":"looks"},"relearn":"Meaning, relationships, living your values and worthwhile work make a good life; impressive titles, envy and droppable designations just look good.","persona":"any","source":"a good life"},
  {"id":"ff-058","cat":"worth-beyond-cv","type":"role-play","hook":"A relative ties their pride in you to your achievements.","relearn":"Keep your worth steady, even when others tie pride to results.","persona":"Aarti","source":"steady worth","setup":"Name your steady worth. Say:","yourLine":[{"text":"\"I'm working hard, and my worth isn't only my results, I hope you can see me too.\"","best":true},{"text":"Accept your worth rises and falls with results"}]},
  {"id":"ff-059","cat":"worth-beyond-cv","type":"match","hook":"Match the worth-truth to the fear it answers.","pairs":[{"left":"I'm more than my CV","right":"\"I'm only my achievements\""},{"left":"A result isn't a verdict","right":"\"This defines me\""},{"left":"Fit beats status","right":"\"I must impress everyone\""},{"left":"Worth is steady, not earned","right":"\"I have to keep proving I matter\""},{"left":"My people value who I am","right":"\"They only care about my rank\""}],"relearn":"You're more than your CV, a result isn't a verdict, fit beats status, worth is steady, and your people value who you are.","persona":"any","source":"consolidation"},
  {"id":"ff-060","cat":"your-path","type":"branch","hook":"The future feels huge and you don't know where to start.","options":[{"text":"Pick one small, values-based next step and take it","consequence":"You turn anxiety into motion.","outcome":"moving","best":true},{"text":"Wait until the whole path is clear","consequence":"One small values-based step turns anxiety into motion; you don't need the whole path first."}],"debrief":"You don't need the full map; a single values-based next step gets you moving.","relearn":"Turn future-anxiety into one small, values-based next step.","persona":"any","source":"next step"},
  {"id":"ff-061","cat":"your-path","type":"strike-rewrite","hook":"\"There's only one right path, the 'settled job'.\"","myth":{"un":"There's only one right path.","re":"There are many paths; the right one is the one that genuinely fits you.","why":"Different lives suit different people."},"relearn":"There are many paths; the right one is the one that fits you.","persona":"any","source":"many paths"},
  {"id":"ff-062","cat":"your-path","type":"sort","hook":"Sort: a values-based next step, or just chasing approval?","items":[{"id":"a","text":"Trying work that matches your interests"},{"id":"b","text":"Picking what impresses relatives"},{"id":"c","text":"Building a skill you care about"},{"id":"d","text":"Following the crowd's idea of success"},{"id":"e","text":"Choosing work that fits how you want to live"},{"id":"f","text":"Doing it only to silence questions"}],"bins":[{"id":"values","label":"Values-based","valence":"pos"},{"id":"approval","label":"Approval-chasing","valence":"uhoh"}],"key":{"a":"values","b":"approval","c":"values","d":"approval","e":"values","f":"approval"},"relearn":"Interests, skills you care about and life-fit are values-based; impressing relatives or the crowd chases approval.","persona":"any","source":"values vs approval"},
  {"id":"ff-063","cat":"your-path","type":"branch","hook":"You have no network or connections, unlike some peers.","options":[{"text":"Build skills, reach out, and use what is open to you","consequence":"You make progress without inherited advantage.","outcome":"resourceful","best":true},{"text":"Give up because the game feels rigged","consequence":"Building skills and reaching out opens doors even without a network; that beats giving up."}],"debrief":"No network is a real disadvantage, but skills and persistence still open doors.","relearn":"Without a network, build skills and reach out; doors still open.","persona":"Meena","source":"without networks"},
  {"id":"ff-064","cat":"your-path","type":"reflect","hook":"Lensy: agency means turning anxiety about the future into action on it. Ready to?","prompt":"What do you think?","options":["Yes","Anxiety into action","Take agency"],"affirm":"Turning worry into a next step is exactly how anxiety becomes agency over your future.","relearn":"Agency means turning future-anxiety into action.","persona":"any","source":"agency"},
  {"id":"ff-065","cat":"your-path","type":"match","hook":"Match the move to what it builds toward your path.","pairs":[{"left":"A small next step","right":"Momentum"},{"left":"A skill you care about","right":"Real options"},{"left":"Reaching out to someone","right":"A way in"},{"left":"Knowing your own values","right":"A clear compass"},{"left":"Reviewing what's working","right":"A path that self-corrects"}],"relearn":"Small steps, skills, outreach, values and review each build toward a path that's yours.","persona":"any","source":"building blocks"},
  {"id":"ff-066","cat":"your-path","type":"branch","hook":"You're choosing between a path that fits you and one that just sounds impressive.","options":[{"text":"Lean toward fit; you'll sustain what suits you","consequence":"You choose for the long run.","outcome":"sustainable","best":true},{"text":"Pick the impressive one despite the misfit","consequence":"Leaning toward fit beats impressive-but-wrong; you sustain a path that actually suits you."}],"debrief":"A path that fits you is one you can sustain; impressive-but-wrong tends to burn out.","relearn":"Lean toward fit over mere prestige; you'll sustain what suits you.","persona":"any","source":"fit"},
  {"id":"ff-067","cat":"your-path","type":"sort","hook":"Sort: helps you find a path that's yours, or someone else's?","items":[{"id":"a","text":"Noticing what you enjoy and value"},{"id":"b","text":"Copying a peer's choices"},{"id":"c","text":"Experimenting and reflecting"},{"id":"d","text":"Doing only what's expected"},{"id":"e","text":"Choosing by your own definition of success"},{"id":"f","text":"Chasing whatever impresses others"}],"bins":[{"id":"yours","label":"Yours","valence":"pos"},{"id":"theirs","label":"Someone else's","valence":"uhoh"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"Noticing what you value and experimenting finds your path; copying peers or impressing others finds someone else's.","persona":"any","source":"finding yours"},
  {"id":"ff-068","cat":"your-path","type":"role-play","hook":"You want to ask someone in a field you're curious about for advice.","setup":"Reach out simply. Say:","yourLine":[{"text":"\"I'm exploring this field and would love to hear how you got started, if you have a few minutes.\"","best":true},{"text":"Assume no one would want to help you"}],"relearn":"A simple, curious outreach can open a door, even without a network.","persona":"Deepak","source":"reaching out"},
  {"id":"ff-069","cat":"your-path","type":"branch","hook":"You feel paralysed trying to make the 'perfect' choice.","options":[{"text":"Make a good-enough choice and adjust as you learn","consequence":"You move instead of freezing.","outcome":"moving","best":true},{"text":"Wait for certainty before any move","consequence":"A good-enough choice you adjust beats waiting for a perfect certainty that never comes."}],"debrief":"There's rarely a perfect choice; a good-enough one you refine as you go beats paralysis.","relearn":"Make a good-enough choice and adjust as you learn; don't wait for perfect.","persona":"any","source":"good enough"},
  {"id":"ff-070","cat":"your-path","type":"reflect","hook":"Lensy: success on your own terms beats someone else's idea of it. Define it for yourself?","prompt":"What do you think?","options":["Yes","On my terms","My definition"],"affirm":"Defining success by your own values, not borrowed ones, is what makes it worth reaching.","relearn":"Define success on your own terms, not someone else's idea of it.","persona":"any","source":"your terms"},
  {"id":"ff-071","cat":"your-path","type":"sort","hook":"Sort: a sign you're on a path that fits, or a misfit?","items":[{"id":"a","text":"It aligns with your values"},{"id":"b","text":"You dread it daily"},{"id":"c","text":"You're growing and curious"},{"id":"d","text":"You're only in it to impress"},{"id":"e","text":"You lose track of time in it"},{"id":"f","text":"It clashes with how you want to live"}],"bins":[{"id":"fit","label":"Fits","valence":"pos"},{"id":"misfit","label":"Misfit","valence":"neg"}],"key":{"a":"fit","b":"misfit","c":"fit","d":"misfit","e":"fit","f":"misfit"},"relearn":"Value-alignment, growth, curiosity and losing track of time signal a fit; daily dread, impressing-only or clashing with your life signal a misfit.","persona":"any","source":"fit signals"},
  {"id":"ff-072","cat":"your-path","type":"branch","hook":"You want to start building toward your future today.","options":[{"text":"Take one concrete action and let it lead to the next","consequence":"You begin, and momentum grows.","outcome":"begun","best":true},{"text":"Keep planning without ever starting","consequence":"One concrete action that leads to the next beats endless planning; momentum comes from starting."}],"debrief":"Momentum compounds; one concrete action today makes the next one easier.","relearn":"Take one concrete action today; momentum grows from starting.","persona":"any","source":"momentum"},
  {"id":"ff-073","cat":"your-path","type":"reflect","hook":"Lensy: you have more agency over your future than the anxiety lets you feel. Own a little of it?","prompt":"What do you think?","options":["Yes","I have agency","More than I feel"],"affirm":"You hold real agency over your next steps; the anxiety just hides it from view.","relearn":"You have more agency over your future than anxiety lets you feel.","persona":"any","source":"agency"},
  {"id":"ff-074","cat":"tools-and-help","type":"match","hook":"Match the tool to the moment.","pairs":[{"left":"The 'next step' tool","right":"When you're stuck and spiralling"},{"left":"A breathing space","right":"When anxiety spikes"},{"left":"A mentor or counsellor","right":"When you need real guidance"},{"left":"Tele-MANAS 14416","right":"When the distress turns heavy"},{"left":"A trusted friend","right":"When you just need to be heard"}],"relearn":"A next-step tool for stuck, a breathing space for spikes, a mentor for guidance, a helpline when it's heavy.","persona":"any","source":"the tools"},
  {"id":"ff-075","cat":"tools-and-help","type":"sort","hook":"Sort: a healthy way to handle career stress, or not?","items":[{"id":"a","text":"Breaking it into next steps"},{"id":"b","text":"Catastrophising the future"},{"id":"c","text":"Talking to a mentor"},{"id":"d","text":"Numbing it and avoiding"},{"id":"e","text":"Taking a breathing space"},{"id":"f","text":"Spiralling alone at 3am"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"},"relearn":"Next steps, a mentor and a breather are healthy; catastrophising, numbing and 3am spirals aren't.","persona":"any","source":"handling stress"},
  {"id":"ff-076","cat":"tools-and-help","type":"branch","hook":"The career anxiety has tipped into heavy, constant distress.","options":[{"text":"Reach for real support, Tele-MANAS 14416 or a counsellor","consequence":"You get help for the distress underneath.","outcome":"supported","best":true},{"text":"Push through alone no matter how heavy","consequence":"Heavy distress deserves support (Tele-MANAS 14416, a counsellor); don't carry it alone."}],"debrief":"When anxiety turns heavy and constant, you're not alone; it can get better.","relearn":"If anxiety turns heavy, reach for support (Tele-MANAS 14416).","persona":"Mehta","source":"crisis routing"},
  {"id":"ff-077","cat":"tools-and-help","type":"match","hook":"Match the need to where help lives (India).","pairs":[{"left":"Heavy distress or hopelessness","right":"Tele-MANAS 14416"},{"left":"Danger to life, right now","right":"Emergency 112"},{"left":"Career direction","right":"A mentor or careers service"},{"left":"A panic spike right now","right":"A breathing space"},{"left":"Just needing to be heard","right":"A trusted person"}],"relearn":"Tele-MANAS 14416 for distress, 112 for danger, a mentor or careers service for direction.","persona":"any","source":"help routes"},
  {"id":"ff-078","cat":"tools-and-help","type":"sort","hook":"Sort: a reliable source of career guidance, or not?","items":[{"id":"a","text":"A mentor or careers service"},{"id":"b","text":"A viral 'get rich' reel"},{"id":"c","text":"People doing the work"},{"id":"d","text":"Anxiety-driven 3am spirals"},{"id":"e","text":"A counsellor who knows the field"},{"id":"f","text":"An anonymous hype account"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"relearn":"Mentors, counsellors and people doing the work are reliable; viral reels, 3am spirals and hype accounts aren't.","persona":"any","source":"reliable guidance"},
  {"id":"ff-079","cat":"tools-and-help","type":"role-play","hook":"A friend is drowning in future-anxiety and shame.","relearn":"Remind an anxious friend no one has it sorted, and offer support.","persona":"any","source":"supporting a friend","setup":"Lighten it and point to help. Say:","yourLine":[{"text":"\"No one has it figured out, you're not behind, want to find some support together?\"","best":true},{"text":"\"Just try harder.\""}]},
  {"id":"ff-080","cat":"tools-and-help","type":"reflect","hook":"Lensy: quiet the comparison, loosen the pressure, take small steps, you can find your feet. Feel it?","prompt":"What do you think?","options":["Yes","I can find my feet","Step by step"],"affirm":"Quieting comparison, loosening pressure and taking small steps is exactly how you find your feet.","relearn":"Quiet comparison, loosen the pressure and take small steps to find your feet.","persona":"any","source":"finding your feet"},
  {"id":"ff-081","cat":"tools-and-help","type":"spot","hook":"Spot the two messages that deepen career anxiety instead of easing it.","scene":[{"id":"a","text":"\"No one has it figured out\"","trick":false},{"id":"b","text":"\"You're already too far behind\"","trick":true},{"id":"c","text":"\"Small steps count\"","trick":false},{"id":"d","text":"\"It's too late to change course now\"","trick":true},{"id":"e","text":"\"You don't have to do this alone\"","trick":false}],"why":"'Too far behind' and 'too late to change' deepen the anxiety; the others genuinely help.","relearn":"'No one has it figured out' and 'small steps count' help; 'too far behind' and 'too late' deepen anxiety.","persona":"any","source":"helpful messages"},
  {"id":"ff-082","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Asking for help with career stress means I'm weak.\"","myth":{"un":"Asking for help with career stress means I'm weak.","re":"Career distress is real and common; reaching out to a mentor, counsellor or helpline is smart, not weak.","why":"Support is how people navigate hard stretches."},"relearn":"Reaching out for help with career stress is smart, not weak.","persona":"Rohan","source":"help is smart"},
  {"id":"ff-083","cat":"tools-and-help","type":"match","hook":"Match the long-term habit to what it does for anxiety.","relearn":"Keep future-anxiety manageable with regular small steps, self-check-ins and staying connected.","persona":"any","source":"long-term habit","pairs":[{"left":"Regular small steps","right":"Keeps anxiety workable"},{"left":"Self-check-ins","right":"Catch spirals early"},{"left":"Staying connected","right":"Shares the load"},{"left":"A wind-down routine","right":"Quiets the 3am loop"},{"left":"One mentor on call","right":"A reality check when needed"}]},
  {"id":"ff-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: which 'find your feet' truth will you carry?","prompt":"Pick one.","options":["No one has it figured out","Setbacks aren't verdicts","Worth isn't my CV","Small steps count"],"affirm":"Carry that one, and the future feels less like a threat and more like something you can meet.","relearn":"No one has it figured out, setbacks aren't verdicts, worth isn't your CV, and small steps count.","persona":"any","source":"carry forward"},
  {"id":"ff-900","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"A backlog this semester means I've ruined my whole degree.\"","myth":{"un":"A backlog this semester means I've ruined my whole degree.","re":"A backlog is one subject to clear, not a verdict on your degree; supplementary exams exist for exactly this.","why":"It's a setback to clear, not a full stop."},"relearn":"A backlog is one subject to clear, not your whole degree decided.","persona":"any","source":"backlog"},
  {"id":"ff-901","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I didn't crack JEE, so I'm a write-off.\"","myth":{"un":"I didn't crack JEE, so I'm a write-off.","re":"One entrance result is one day's test, not your ceiling; countless people build strong lives on other routes.","why":"An exam measures a test, not your potential."},"relearn":"Not cracking one entrance exam is a redirect, not a write-off.","persona":"Deepak","source":"entrance exam"},
  {"id":"ff-902","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"My startup idea flopped, so I'm just not cut out for this.\"","myth":{"un":"My startup idea flopped, so I'm just not cut out for this.","re":"A first idea failing is data about that idea, not proof about you; many founders fail before something clicks.","why":"You learned things a win never teaches."},"relearn":"A flopped first attempt is feedback on the idea, not a verdict on you.","persona":"any","source":"idea flopped"},
  {"id":"ff-903","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I dropped a year, so I'm permanently behind everyone.\"","myth":{"un":"I dropped a year, so I'm permanently behind everyone.","re":"A drop year is a different pace, not a lost race; there's no fixed timeline you're failing against.","why":"Timelines differ for everyone."},"relearn":"A drop year is a different pace, not a permanent loss.","persona":"any","source":"drop year"},
  {"id":"ff-904","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I should have bounced back by now; still hurting means I'm weak.\"","myth":{"un":"I should have bounced back by now; still hurting means I'm weak.","re":"Recovery isn't a deadline; feeling it for a while is part of healing, not weakness.","why":"Resilience includes letting it hurt first."},"relearn":"Taking time to feel a setback is part of recovery, not weakness.","persona":"any","source":"recovery timeline"},
  {"id":"ff-905","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"If I really had talent, I wouldn't have struggled like this.\"","myth":{"un":"If I really had talent, I wouldn't have struggled like this.","re":"Struggle is how skill is built, not proof it's missing; even strong people hit walls and work through them.","why":"Difficulty isn't a verdict on ability."},"relearn":"Struggling with something hard builds skill; it doesn't prove you lack it.","persona":"any","source":"struggle vs talent"},
  {"id":"ff-906","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"Failing in front of everyone means I can never show my face.\"","myth":{"un":"Failing in front of everyone means I can never show my face.","re":"People remember a public stumble far less than you fear; most are too busy with their own worries.","why":"The spotlight feels bigger than it is."},"relearn":"A public setback fades fast for everyone but you; you can show up again.","persona":"any","source":"public failure"},
  {"id":"ff-907","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I have to get it right the first time or not bother.\"","myth":{"un":"I have to get it right the first time or not bother.","re":"Almost nothing worthwhile is got right first try; iterating is the normal way things actually work.","why":"First drafts are meant to be rough."},"relearn":"Getting it wrong first and iterating is the normal route, not a failure.","persona":"any","source":"first-try pressure"},
  {"id":"ff-908","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"Getting laid off in my first job means I'm unhireable.\"","myth":{"un":"Getting laid off in my first job means I'm unhireable.","re":"Layoffs are usually about budgets and timing, not your worth; plenty of strong people get caught in them.","why":"A layoff isn't a performance verdict."},"relearn":"A layoff is rarely about you; it doesn't make you unhireable.","persona":"Meena","source":"layoff"},
  {"id":"ff-909","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I switched my branch, so I clearly couldn't handle the first one.\"","myth":{"un":"I switched my branch, so I clearly couldn't handle the first one.","re":"Switching toward a better fit is a smart pivot, not a defeat; choosing what suits you is strength.","why":"Pivots are legitimate routes, not retreats."},"relearn":"Switching to a better-fit branch is a pivot, not proof you couldn't cope.","persona":"any","source":"branch switch"},
  {"id":"ff-910","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"Everyone in my batch got placed except me, so something's wrong with me.\"","myth":{"un":"Everyone in my batch got placed except me, so something's wrong with me.","re":"Placement timing varies hugely; many strong people land roles off-campus or months later.","why":"A slower start isn't a flaw in you."},"relearn":"Getting placed later than your batch is timing, not something wrong with you.","persona":"Deepak","source":"placement timing"},
  {"id":"ff-911","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I bombed the interview, so I should give up on that field.\"","myth":{"un":"I bombed the interview, so I should give up on that field.","re":"One rough interview is a skill you can practise, not a closed door; the next one can go differently.","why":"Interviewing improves with reps."},"relearn":"A bad interview is a skill to practise, not a reason to quit the field.","persona":"any","source":"interview flop"},
  {"id":"ff-912","cat":"bounce-from-setbacks","type":"strike-rewrite","hook":"\"I failed once, so I'll obviously fail every time I try again.\"","myth":{"un":"I failed once, so I'll obviously fail every time I try again.","re":"A past result doesn't decide the next one; you carry what you learned into the next attempt.","why":"Each attempt starts fresh, wiser."},"relearn":"One failure doesn't predict the next; you go in having learned.","persona":"any","source":"one failure"},
  {"id":"ff-913","cat":"bounce-from-setbacks","type":"branch","hook":"Your results are out and far below what you hoped.","options":[{"text":"Sit with it today, look at options tomorrow","consequence":"You let it land without making it permanent.","outcome":"steady","best":true},{"text":"Decide tonight you're done with the field","consequence":"Weighing options when calmer beats a permanent call made in the first sting."}],"debrief":"Disappointment is real; don't let the raw first hour write the verdict.","relearn":"Feel a bad result first; weigh next steps once the sting settles.","persona":"any","source":"results day"},
  {"id":"ff-914","cat":"bounce-from-setbacks","type":"branch","hook":"You missed the cutoff for the course you wanted by a few marks.","options":[{"text":"Look at next-best fits and a reattempt","consequence":"You keep moving with real options.","outcome":"open","best":true},{"text":"Decide only that one course could ever work","consequence":"Exploring close-fit options and a reattempt keeps doors open instead of shutting them."}],"debrief":"A near-miss is painful, but rarely the only door; nearby fits often work out.","relearn":"Missing one cutoff leaves real options; explore close fits and reattempts.","persona":"any","source":"missed cutoff"},
  {"id":"ff-915","cat":"bounce-from-setbacks","type":"branch","hook":"A scholarship you counted on got rejected.","options":[{"text":"Ask what was missing and apply to two more","consequence":"You turn one no into a better application.","outcome":"resourceful","best":true},{"text":"Take it as a sign you don't deserve funding","consequence":"Using the rejection as feedback and reapplying works; 'I don't deserve it' just stops you."}],"debrief":"Funding is competitive; one no is feedback for the next, not a judgement on you.","relearn":"A scholarship no is feedback to refine and reapply, not a verdict on your worth.","persona":"Deepak","source":"scholarship reject"},
  {"id":"ff-916","cat":"bounce-from-setbacks","type":"branch","hook":"You made a visible mistake on a team project and feel like quitting.","options":[{"text":"Own it, fix what you can, and keep contributing","consequence":"You rebuild trust by showing up.","outcome":"accountable","best":true},{"text":"Withdraw quietly so no one sees you again","consequence":"Owning the slip and helping fix it rebuilds standing; disappearing leaves the mistake as the last thing they saw."}],"debrief":"A mistake handled openly is forgotten fast; teammates remember how you recovered.","relearn":"After a visible mistake, own it and keep contributing rather than withdraw.","persona":"any","source":"team mistake"},
  {"id":"ff-917","cat":"bounce-from-setbacks","type":"branch","hook":"You've been rejected from several jobs in a row.","options":[{"text":"Spot a pattern, tweak your approach, keep applying","consequence":"You convert a streak into a strategy.","outcome":"adaptive","best":true},{"text":"Conclude you're simply not employable","consequence":"Looking for a fixable pattern and adjusting keeps you in the game; 'not employable' is a story, not a finding."}],"debrief":"A rejection streak usually points to something adjustable, not to your worth.","relearn":"A run of rejections is a signal to adjust your approach, not proof you're unemployable.","persona":"Meena","source":"rejection streak"},
  {"id":"ff-918","cat":"bounce-from-setbacks","type":"branch","hook":"Family is disappointed about your low marks; the room feels heavy.","options":[{"text":"Acknowledge the dip and share a small plan","consequence":"You shift the room from blame to next steps.","outcome":"grounded","best":true},{"text":"Absorb it as proof you've let everyone down","consequence":"Naming the dip and a small plan steadies things; 'I've failed everyone' deepens the spiral."}],"debrief":"Family worry is real, but a calm next step does more than a verdict on yourself.","relearn":"After a dip, name a small plan rather than absorb it as proof you've failed.","persona":"Aarti","source":"family disappointment"},
  {"id":"ff-919","cat":"bounce-from-setbacks","type":"branch","hook":"You froze and went blank during a big presentation.","options":[{"text":"Note what triggered it and rehearse for next time","consequence":"You make the freeze something you can train.","outcome":"prepared","best":true},{"text":"Vow to never speak in front of people again","consequence":"Treating the freeze as a skill helps; swearing off speaking lets one moment shrink your life."}],"debrief":"Freezing under pressure is common and trainable, not a verdict on speaking.","relearn":"A presentation freeze is something to prepare for, not a reason to stop speaking up.","persona":"any","source":"presentation freeze"},
  {"id":"ff-920","cat":"bounce-from-setbacks","type":"branch","hook":"You failed your driving test and feel humiliated.","options":[{"text":"Book a couple more lessons and rebook the test","consequence":"You treat it as practice, not a verdict.","outcome":"practical","best":true},{"text":"Decide you're just bad at everything you try","consequence":"More practice and a rebook fixes a driving test; 'bad at everything' globalises one small fail into your whole self."}],"debrief":"Small fails feel huge in the moment; most just need a bit more practice.","relearn":"Failing a small test means practise and retry, not 'I'm bad at everything'.","persona":"any","source":"driving test"},
  {"id":"ff-921","cat":"bounce-from-setbacks","type":"branch","hook":"A senior gave you harsh feedback and you want to shut down.","options":[{"text":"Take the useful part, leave the tone, and adjust","consequence":"You grow from it without absorbing the sting.","outcome":"resilient","best":true},{"text":"Decide you're hopeless and stop trying","consequence":"Keeping the useful part and letting the tone go helps you improve; 'I'm hopeless' just ends the learning."}],"debrief":"Harsh feedback often hides a useful signal; take the lesson, drop the delivery.","relearn":"Harsh feedback has a usable part; keep that and adjust rather than shut down.","persona":"Rohan","source":"harsh feedback"},
  {"id":"ff-922","cat":"bounce-from-setbacks","type":"branch","hook":"You failed a paper you actually studied hard for.","options":[{"text":"Review how you studied and adjust the method","consequence":"You learn that effort plus the right method beats effort alone.","outcome":"smart","best":true},{"text":"Decide studying is pointless since it failed","consequence":"Adjusting your method fixes it; 'studying is pointless' drops the one thing you can change."}],"debrief":"When effort doesn't land, the method is often what to tweak, not your worth.","relearn":"If hard study didn't pay off, examine the method rather than give up on studying.","persona":"any","source":"studied but failed"},
  {"id":"ff-923","cat":"bounce-from-setbacks","type":"branch","hook":"You're tempted to hide your reattempt year from everyone.","options":[{"text":"Tell a trusted person; carrying it alone is heavier","consequence":"You feel lighter and supported.","outcome":"connected","best":true},{"text":"Keep it secret and brace for being found out","consequence":"Telling one trusted person eases the load; secrecy adds shame to a normal reattempt."}],"debrief":"Reattempts are common and nothing to hide; sharing usually meets understanding.","relearn":"A reattempt is normal; sharing it with someone you trust beats carrying it in secret.","persona":"any","source":"hiding a reattempt"},
  {"id":"ff-924","cat":"bounce-from-setbacks","type":"branch","hook":"After one rejection you're about to delete the whole application draft.","options":[{"text":"Save it; the next round can reuse most of it","consequence":"You keep your work and momentum.","outcome":"efficient","best":true},{"text":"Delete everything in frustration","consequence":"Saving the draft lets you reuse it; deleting it means starting the next from zero."}],"debrief":"Frustration tempts you to torch your work; most of it is reusable next time.","relearn":"After a rejection, keep your work; the next attempt builds on it, not from scratch.","persona":"any","source":"deleting work"},
  {"id":"ff-925","cat":"bounce-from-setbacks","type":"branch","hook":"You compare your failure to a friend's smooth run and feel worthless.","options":[{"text":"Remind yourself you see their edit, not the full story","consequence":"You loosen the unfair comparison.","outcome":"clear","best":true},{"text":"Take their smooth run as proof you're the failure","consequence":"Remembering you only see their highlights eases it; their edit isn't proof of your failure."}],"debrief":"You're comparing your raw moment to their edited one; not a fair scoreboard.","relearn":"A setback compared to someone's highlight reel isn't a fair measure of you.","persona":"any","source":"comparing setbacks"},
  {"id":"ff-926","cat":"bounce-from-setbacks","type":"branch","hook":"A long-term goal fell through and you feel directionless.","options":[{"text":"Name one tiny next step you can take this week","consequence":"You replace the void with a small handle.","outcome":"moving","best":true},{"text":"Wait to feel motivated again before doing anything","consequence":"One tiny step restarts momentum; waiting for motivation after a loss can take a long time."}],"debrief":"After a goal collapses, a small concrete step does more than waiting to feel ready.","relearn":"When a goal falls through, one small next step beats waiting for motivation.","persona":"any","source":"goal fell through"},
  {"id":"ff-927","cat":"bounce-from-setbacks","type":"branch","hook":"You keep replaying one mistake from months ago.","options":[{"text":"Write down the lesson, then let the loop close","consequence":"You extract the value and free the rumination.","outcome":"settled","best":true},{"text":"Keep mentally rerunning it to punish yourself","consequence":"Capturing the lesson closes the loop; replaying just punishes you after it's learned."}],"debrief":"Rumination keeps the pain without the learning; capture the lesson and let it rest.","relearn":"Once a mistake's lesson is learned, replaying it only punishes; let the loop close.","persona":"any","source":"rumination"},
  {"id":"ff-928","cat":"bounce-from-setbacks","type":"branch","hook":"A bad result has left a hopelessness that isn't lifting.","options":[{"text":"Reach out to a counsellor or Tele-MANAS 14416","consequence":"You let support carry part of it.","outcome":"supported","best":true},{"text":"Tell yourself to just tough it out alone","consequence":"Reaching out when it stays heavy is smart; toughing it out alone lets the weight build."}],"debrief":"When a setback tips into constant heaviness, support is the strong move: Tele-MANAS 14416, or someone you trust.","relearn":"When hopelessness lingers, reaching out for support is strength, not weakness.","persona":"Mehta","source":"heavy distress"},
  {"id":"ff-929","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: setback as information, or setback as a verdict?","items":[{"id":"a","text":"\"This shows me what to study differently\""},{"id":"b","text":"\"This proves I'm not smart enough\""},{"id":"c","text":"\"I can ask where I went wrong\""},{"id":"d","text":"\"My future is decided now\""},{"id":"e","text":"\"This is one data point to adjust on\""},{"id":"f","text":"\"This is who I am, full stop\""}],"bins":[{"id":"info","label":"Information","valence":"pos"},{"id":"verdict","label":"Verdict","valence":"neg"}],"key":{"a":"info","b":"verdict","c":"info","d":"verdict","e":"info","f":"verdict"},"relearn":"Lines that ask what to adjust treat a setback as information; lines that decide who you are treat it as a verdict.","persona":"any","source":"info vs verdict"},
  {"id":"ff-930","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: a healthy way to cope with a setback, or an unhealthy one?","items":[{"id":"a","text":"Talking it through with a friend"},{"id":"b","text":"Numbing it by doomscrolling all night"},{"id":"c","text":"Breaking the comeback into small steps"},{"id":"d","text":"Pretending you don't care at all"},{"id":"e","text":"Resting, then planning calmly"},{"id":"f","text":"Avoiding anything linked to it forever"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"unhealthy","label":"Unhealthy","valence":"neg"}],"key":{"a":"healthy","b":"unhealthy","c":"healthy","d":"unhealthy","e":"healthy","f":"unhealthy"},"relearn":"Talking it out, small steps and resting then planning are healthy; numbing, pretending and avoiding forever are not.","persona":"any","source":"coping styles"},
  {"id":"ff-931","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: a real next step after a setback, or a trap that keeps you stuck?","items":[{"id":"a","text":"Booking one practice session"},{"id":"b","text":"Waiting to feel fully ready"},{"id":"c","text":"Asking a mentor for one tip"},{"id":"d","text":"Comparing yourself to toppers online"},{"id":"e","text":"Listing what you'd change next time"},{"id":"f","text":"Deciding the goal is hopeless"}],"bins":[{"id":"step","label":"Real next step","valence":"pos"},{"id":"trap","label":"Stuck-trap","valence":"neg"}],"key":{"a":"step","b":"trap","c":"step","d":"trap","e":"step","f":"trap"},"relearn":"Booking practice, asking for a tip and listing changes move you; waiting to feel ready, comparing and 'it's hopeless' keep you stuck.","persona":"any","source":"next step vs trap"},
  {"id":"ff-932","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: a kind thing to tell yourself after a setback, or a harsh one?","items":[{"id":"a","text":"\"That was hard; I'm allowed to feel it\""},{"id":"b","text":"\"I always ruin everything\""},{"id":"c","text":"\"I can try again when I'm steadier\""},{"id":"d","text":"\"I'm an embarrassment to my family\""},{"id":"e","text":"\"One bad day isn't the whole me\""},{"id":"f","text":"\"I deserve to feel this awful\""}],"bins":[{"id":"kind","label":"Kind to self","valence":"pos"},{"id":"harsh","label":"Harsh to self","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Allowing the feeling, planning a retry and 'one bad day isn't all of me' are kind; 'always ruin everything' and 'I deserve this' are harsh.","persona":"any","source":"self-talk"},
  {"id":"ff-933","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: a fact about failure that's true, or a myth?","items":[{"id":"a","text":"Most successful people failed first"},{"id":"b","text":"One failure decides your whole life"},{"id":"c","text":"Resilience can be learned"},{"id":"d","text":"Strong people never struggle"},{"id":"e","text":"Pivots are a normal route"},{"id":"f","text":"Needing a second attempt is shameful"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"That most succeeders failed first, resilience is learnable and pivots are normal is true; the rest are myths.","persona":"any","source":"failure facts"},
  {"id":"ff-934","cat":"bounce-from-setbacks","type":"sort","hook":"Sort: which line keeps a door open, and which slams it shut?","items":[{"id":"a","text":"\"I can reapply next cycle\""},{"id":"b","text":"\"I'll never get another chance\""},{"id":"c","text":"\"There are other routes to this\""},{"id":"d","text":"\"It's this or nothing\""},{"id":"e","text":"\"I can ask for guidance\""},{"id":"f","text":"\"No point asking anyone\""}],"bins":[{"id":"open","label":"Keeps door open","valence":"pos"},{"id":"shut","label":"Slams it shut","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"'I can reapply', 'other routes exist' and 'I can ask' keep doors open; 'never another chance', 'this or nothing' and 'no point asking' slam them shut.","persona":"any","source":"open vs shut"},
  {"id":"ff-935","cat":"bounce-from-setbacks","type":"role-play","hook":"A classmate just got a low result and is crying.","setup":"Steady them with care. Say:","yourLine":[{"text":"\"This is one result, not the whole of you. Want to figure out a next step together?\"","best":true},{"text":"\"You really should have studied more, na.\""}],"relearn":"Remind someone a single result isn't the whole of them, and offer to look at a next step.","persona":"any","source":"comforting a classmate"},
  {"id":"ff-936","cat":"bounce-from-setbacks","type":"role-play","hook":"Your inner critic is loud after you messed up at work.","setup":"Answer it as you would a struggling friend. Say:","yourLine":[{"text":"\"You made a mistake; you're not a mistake. Let's fix what we can and move on.\"","best":true},{"text":"\"You're useless and everyone can see it.\""}],"relearn":"Speak to yourself after a slip the way you'd steady a friend, not a critic.","persona":"Rohan","source":"inner critic"},
  {"id":"ff-937","cat":"bounce-from-setbacks","type":"role-play","hook":"A relative says your reattempt year means you've fallen behind.","setup":"Hold your ground gently. Say:","yourLine":[{"text":"\"I see it differently — this is me taking another route, and that's okay.\"","best":true},{"text":"\"Yeah, you're right, I've messed up my life.\""}],"relearn":"You can gently hold that a reattempt is a route, not falling behind.","persona":"Aarti","source":"relative's comment"},
  {"id":"ff-938","cat":"bounce-from-setbacks","type":"role-play","hook":"A junior is too scared of failing to even try.","setup":"Encourage them. Say:","yourLine":[{"text":"\"Trying and learning beats not trying. Even if it doesn't work, you'll know more than today.\"","best":true},{"text":"\"Yeah, maybe don't risk it, just in case.\""}],"relearn":"Encourage someone that trying and learning beats avoiding the risk entirely.","persona":"any","source":"encouraging a junior"},
  {"id":"ff-939","cat":"bounce-from-setbacks","type":"role-play","hook":"A friend says they're 'done' after one rejection.","setup":"Reframe it warmly without dismissing the hurt. Say:","yourLine":[{"text":"\"It's okay that it hurts. One no isn't the end — let's just look at the next one.\"","best":true},{"text":"\"Don't be dramatic, it's just one rejection.\""}],"relearn":"Validate the hurt first, then reframe one rejection as not the end.","persona":"any","source":"friend says done"},
  {"id":"ff-940","cat":"bounce-from-setbacks","type":"role-play","hook":"You bumped into a peer right after a public flop.","setup":"Practise meeting it with a steady face. Say:","yourLine":[{"text":"\"Yeah, that didn't go how I wanted — I'm figuring out what's next.\"","best":true},{"text":"\"I'm such a joke, everyone must be laughing at me.\""}],"relearn":"You can name a flop plainly and point to a next step, without collapsing into shame.","persona":"any","source":"after a public flop"},
  {"id":"ff-941","cat":"bounce-from-setbacks","type":"role-play","hook":"A teammate is spiralling after their part of a project failed.","setup":"Pull them out of the spiral. Say:","yourLine":[{"text":"\"This part flopped, not you. Let's see what it taught us and patch it together.\"","best":true},{"text":"\"Well, you did kind of sink the whole thing.\""}],"relearn":"Separate a failed task from the person, and offer to learn from it together.","persona":"any","source":"teammate spiralling"},
  {"id":"ff-942","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two lines that pile shame on instead of helping you bounce back.","scene":[{"id":"a","text":"\"Let's see what I can adjust next time\"","trick":false},{"id":"b","text":"\"I always ruin everything I touch\"","trick":true},{"id":"c","text":"\"It's okay to feel low about this\"","trick":false},{"id":"d","text":"\"Everyone was right to doubt me\"","trick":true},{"id":"e","text":"\"I can ask someone for a hand\"","trick":false}],"why":"'I always ruin everything' and 'everyone was right to doubt me' globalise and shame; the others adjust and ask for help.","relearn":"A bounce-back response adjusts and asks for help, not globalise a slip into shame.","persona":"any","source":"shame vs bounce"},
  {"id":"ff-943","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two responses to a rejection that keep you stuck.","scene":[{"id":"a","text":"\"I'll ask for feedback and reapply\"","trick":false},{"id":"b","text":"\"I'll never put myself out there again\"","trick":true},{"id":"c","text":"\"This stings, but it's survivable\"","trick":false},{"id":"d","text":"\"This proves I'm just not good enough\"","trick":true},{"id":"e","text":"\"Let me try a slightly different angle\"","trick":false}],"why":"'Never again' and 'not good enough' keep you stuck; the others ask for feedback, call it survivable and try a new angle.","relearn":"A healthy reaction to rejection asks for feedback and retries, not quits.","persona":"any","source":"stuck after rejection"},
  {"id":"ff-944","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two 'comfort' lines that actually dismiss the person.","scene":[{"id":"a","text":"\"That sounds really hard; I'm here\"","trick":false},{"id":"b","text":"\"Just stay positive, it's nothing\"","trick":true},{"id":"c","text":"\"Want to figure out a next step together?\"","trick":false},{"id":"d","text":"\"Others have it way worse than you\"","trick":true},{"id":"e","text":"\"It's okay to feel low right now\"","trick":false}],"why":"'Just stay positive' and 'others have it worse' dismiss the feeling; the others validate it and offer support.","relearn":"Real comfort validates the feeling and offers support, not dismisses it.","persona":"any","source":"fake comfort"},
  {"id":"ff-945","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two beliefs about failure that simply aren't true.","scene":[{"id":"a","text":"\"Resilience is a skill I can build\"","trick":false},{"id":"b","text":"\"You either have grit or you don't\"","trick":true},{"id":"c","text":"\"Most people pivot at some point\"","trick":false},{"id":"d","text":"\"One failure marks you for life\"","trick":true},{"id":"e","text":"\"Setbacks can redirect me to a better fit\"","trick":false}],"why":"'You either have grit or you don't' and 'one failure marks you for life' are myths; the others are true.","relearn":"Resilience is learnable and pivots are normal; one failure doesn't mark you for life.","persona":"any","source":"failure myths"},
  {"id":"ff-946","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two lines that turn a setback into a permanent verdict.","scene":[{"id":"a","text":"\"This tells me what to change\"","trick":false},{"id":"b","text":"\"This is just who I am now\"","trick":true},{"id":"c","text":"\"I can recover from this\"","trick":false},{"id":"d","text":"\"There's no coming back from this\"","trick":true},{"id":"e","text":"\"This is one chapter, not the book\"","trick":false}],"why":"'Just who I am now' and 'no coming back' make a setback permanent; the others treat it as changeable and recoverable.","relearn":"A setback is information you can act on, not a permanent verdict on who you are.","persona":"any","source":"permanent verdict"},
  {"id":"ff-947","cat":"bounce-from-setbacks","type":"spot","hook":"Spot the two reactions to a bad result that aren't healthy coping.","scene":[{"id":"a","text":"\"I'll talk to someone I trust\"","trick":false},{"id":"b","text":"\"I'll just numb out and avoid it all\"","trick":true},{"id":"c","text":"\"I'll rest, then make a small plan\"","trick":false},{"id":"d","text":"\"I'll catastrophise the whole future\"","trick":true},{"id":"e","text":"\"I'll treat this as feedback\"","trick":false}],"why":"Numbing/avoiding and catastrophising aren't healthy coping; the others talk it out, rest then plan, and take feedback.","relearn":"Healthy coping talks it out, rests and plans, and takes feedback, not numbs out.","persona":"any","source":"coping reactions"},
  {"id":"ff-948","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: a setback is information about what to adjust, not a verdict on who you are. Sit with that?","prompt":"What lands for you?","options":["It's information","Not a verdict","I can adjust"],"affirm":"A setback points at what to change next; it never gets to decide who you are.","relearn":"A setback is information to adjust on, not a verdict on who you are.","persona":"any","source":"info not verdict reflect"},
  {"id":"ff-949","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: failure is a comma in your story, not a full stop. How does that sit?","prompt":"What do you think?","options":["A comma","The story goes on","I can keep writing"],"affirm":"A setback punctuates the sentence; the story keeps going and you keep writing it.","relearn":"Failure is a comma in your story, not a full stop.","persona":"any","source":"comma reflect"},
  {"id":"ff-950","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: almost everyone you admire has a trail of failures you never see. Believe it?","prompt":"What comes up?","options":["Everyone fails","I only see wins","I'm not alone"],"affirm":"The people who look sorted fell plenty too; you just never saw that part.","relearn":"Almost everyone you admire failed along the way; you only see the wins.","persona":"any","source":"hidden failures reflect"},
  {"id":"ff-951","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: it's allowed to feel a setback fully before you bounce. Give yourself that?","prompt":"What feels true?","options":["I can feel it","Then I bounce","No rush"],"affirm":"Feeling it first isn't weakness; it's the part that lets the bounce actually hold.","relearn":"It's okay to feel a setback fully before bouncing back; there's no rush.","persona":"any","source":"feel it first reflect"},
  {"id":"ff-952","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: the version of you a year from now will have moved well past today's setback. Picture them?","prompt":"What do you notice?","options":["They moved on","It got smaller","I'll get there"],"affirm":"From a year out, today's setback is a small mark on a long road you kept walking.","relearn":"A year on, today's setback will look much smaller; you keep moving.","persona":"any","source":"future self reflect"},
  {"id":"ff-953","cat":"bounce-from-setbacks","type":"reflect","hook":"Lensy: a second attempt isn't a sign you failed — it's just persistence. Take that in?","prompt":"What lands?","options":["It's persistence","Not shame","Trying again counts"],"affirm":"Going again is effort and persistence, the very thing that gets people where they're going.","relearn":"A second attempt is persistence, not a sign you've failed.","persona":"any","source":"second attempt reflect"},
  {"id":"ff-954","cat":"bounce-from-setbacks","type":"match","hook":"Match each setback to the steadying truth that meets it.","relearn":"Each setback has a true, steadying response: failures redirect, are common, are survivable and don't define you.","persona":"any","source":"setback to truth","pairs":[{"left":"Didn't clear the entrance","right":"\"It often redirects to a better fit\""},{"left":"Got rejected from a job","right":"\"One no isn't a verdict on me\""},{"left":"Everyone got placed but me","right":"\"Timing varies; mine can come later\""},{"left":"Failed in front of people","right":"\"They forget faster than I fear\""},{"left":"Want to give up entirely","right":"\"One small step beats quitting raw\""}]},
  {"id":"ff-955","cat":"bounce-from-setbacks","type":"match","hook":"Match the unhelpful thought to its resilient reframe.","relearn":"Each catastrophic thought has a resilient reframe that treats the setback as workable, not final.","persona":"any","source":"thought to reframe","pairs":[{"left":"\"My life is ruined\"","right":"\"This is a detour, not a dead end\""},{"left":"\"I'm not good enough\"","right":"\"This shows me what to adjust\""},{"left":"\"It's over for me\"","right":"\"It's a comma, not a full stop\""},{"left":"\"I'll never recover\"","right":"\"I can recover from this\""},{"left":"\"I'm marked for life\"","right":"\"One result doesn't define me\""}]},
  {"id":"ff-956","cat":"bounce-from-setbacks","type":"match","hook":"Match each part of bouncing back to what it looks like in practice.","relearn":"Bouncing back means feeling it, learning from it, taking a step, leaning on support and being kind to yourself.","persona":"any","source":"bounce in practice","pairs":[{"left":"Feel it","right":"Let yourself be low for a bit"},{"left":"Learn from it","right":"Ask what you'd change next time"},{"left":"Take a step","right":"Book one small action this week"},{"left":"Lean on support","right":"Tell a friend or mentor"},{"left":"Be kind to yourself","right":"Talk to you like a friend"}]},
  {"id":"ff-957","cat":"bounce-from-setbacks","type":"match","hook":"Match each setback myth to the truth that corrects it.","relearn":"Common failure myths each have a correcting truth: failure is normal, learnable to recover from, and not a verdict.","persona":"any","source":"myth to truth","pairs":[{"left":"\"Successful people don't fail\"","right":"\"Most failed first\""},{"left":"\"Resilience is fixed\"","right":"\"Resilience is learnable\""},{"left":"\"One fail decides everything\"","right":"\"It's one data point\""},{"left":"\"Pivoting is quitting\"","right":"\"Pivots are normal routes\""},{"left":"\"Asking help is weak\"","right":"\"Reaching out is smart\""}]},
  {"id":"ff-958","cat":"bounce-from-setbacks","type":"match","hook":"Match each feeling after a setback to a healthy next move.","relearn":"Each tough feeling after a setback has a healthy next move, from resting to reaching for support.","persona":"any","source":"feeling to move","pairs":[{"left":"Crushed and raw","right":"Rest before deciding anything"},{"left":"Stuck and frozen","right":"Pick one tiny next step"},{"left":"Ashamed and hiding","right":"Tell one person you trust"},{"left":"Spiralling at 3am","right":"Reach out: Tele-MANAS 14416"},{"left":"Brutally self-critical","right":"Speak to yourself kindly"}]},
  {"id":"ff-959","cat":"bounce-from-setbacks","type":"match","hook":"Match each thing a setback can give you to what it teaches.","relearn":"A setback can teach direction, method, resilience, humility and what you actually value.","persona":"any","source":"what a setback teaches","pairs":[{"left":"A redirect","right":"Maybe a better-fit path"},{"left":"A method tweak","right":"How to prepare differently"},{"left":"Proof you endure","right":"You can get through hard things"},{"left":"A reality check","right":"What you truly care about"},{"left":"Empathy","right":"Kindness to others who struggle"}]},
  {"id":"ff-960","cat":"bounce-from-setbacks","type":"match","hook":"Match each persona's setback to the route that fits them.","relearn":"Different people meet a setback with different fitting next steps, from off-campus routes to gentle pushback.","persona":"any","source":"persona to route","pairs":[{"left":"Missed campus placement","right":"Apply off-campus and to startups"},{"left":"Family calls it a failure","right":"Gently hold it's another route"},{"left":"No network to lean on","right":"Find a mentor or campus service"},{"left":"Hopelessness won't lift","right":"Reach Tele-MANAS 14416"},{"left":"Afraid to try again","right":"Take one low-stakes attempt"}]},
  {"id":"ff-961","cat":"bounce-from-setbacks","type":"match","hook":"Match each unhelpful coping habit to a healthier swap.","relearn":"Each numbing or avoiding habit has a healthier swap that actually helps you recover.","persona":"any","source":"habit swap","pairs":[{"left":"Doomscrolling all night","right":"A short walk and early sleep"},{"left":"Bottling it all up","right":"Talking to someone you trust"},{"left":"Avoiding it forever","right":"One small step back toward it"},{"left":"Punishing replays","right":"Writing the lesson down once"},{"left":"Chasing 3am 'fix' reels","right":"Asking a real mentor"}]},
  {"id":"ff-990","cat":"comparison-trap","type":"strike-rewrite","hook":"\"My batchmate already has a job offer, so I've clearly fallen behind.\"","myth":{"un":"My batchmate has an offer, so I've fallen behind.","re":"One person's timeline isn't your deadline; your path runs at its own pace, not theirs.","why":"Different people land at different times; nobody's clock sets yours."},"relearn":"One person's offer isn't your deadline; your path runs at its own pace.","persona":"Deepak","source":"the offer clock"},
  {"id":"ff-991","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Everyone on LinkedIn is celebrating, so they must all be doing great.\"","myth":{"un":"Everyone on LinkedIn is doing great.","re":"LinkedIn shows posted wins, not the rejections, gaps and worry people leave off their feed.","why":"People share offers and promotions, not the silence between them."},"relearn":"LinkedIn shows posted wins, not the rejections and gaps people leave out.","persona":"any","source":"the linkedin reel"},
  {"id":"ff-992","cat":"comparison-trap","type":"strike-rewrite","hook":"\"My cousin cracked it in one attempt, so something must be wrong with me.\"","myth":{"un":"My cousin cracked it first try, so I'm flawed.","re":"You're comparing your full struggle to a single clean line from their story you never saw inside.","why":"You only saw their result, never the doubts behind it."},"relearn":"You're comparing your whole struggle to one clean line of someone else's story.","persona":"Aarti","source":"one-attempt myth"},
  {"id":"ff-993","cat":"comparison-trap","type":"strike-rewrite","hook":"\"If I keep watching toppers' day-in-my-life reels, I'll get motivated too.\"","myth":{"un":"Watching toppers' reels will motivate me.","re":"Those edited reels mostly leave you feeling behind; your own small next step actually moves you.","why":"Feeling inadequate drains energy; it rarely fuels real action."},"relearn":"Edited toppers' reels mostly leave you behind; your own next step moves you.","persona":"any","source":"the topper reel"},
  {"id":"ff-994","cat":"comparison-trap","type":"strike-rewrite","hook":"\"My whole batch seems sorted; I must be the only one quietly panicking.\"","myth":{"un":"I'm the only one quietly panicking.","re":"Most of your batch is feeling behind too; the calm faces are hiding the same worry you are.","why":"Outer confidence usually covers private doubt."},"relearn":"Most of your batch feels behind too; calm faces often hide the same worry.","persona":"any","source":"everyone panics"},
  {"id":"ff-995","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Their startup got funded and I'm nowhere, so my work doesn't count.\"","myth":{"un":"Their funding means my work doesn't count.","re":"Their win takes nothing from you; your progress is real whether or not anyone announced it.","why":"Someone else's headline isn't a verdict on your effort."},"relearn":"Their win takes nothing from you; your progress is real, announced or not.","persona":"Meena","source":"the funding post"},
  {"id":"ff-996","cat":"comparison-trap","type":"strike-rewrite","hook":"\"She's already engaged and settled; clearly I'm late at everything.\"","myth":{"un":"She's settled, so I'm late at everything.","re":"There's no shared schedule everyone's on; 'late' is measured against a standard you invented.","why":"Lives unfold on different timelines, not one fixed one."},"relearn":"There's no shared schedule; 'late' is measured against a standard you invented.","persona":"Zoya","source":"the settled standard"},
  {"id":"ff-997","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Checking who got placed every hour keeps me sharp and ready.\"","myth":{"un":"Refreshing the placement list keeps me sharp.","re":"Hourly checking mostly spikes anxiety; stepping back and doing your own prep helps far more.","why":"Constant comparison rattles you; focused work steadies you."},"relearn":"Hourly placement-checking spikes anxiety; your own prep helps far more.","persona":"Deepak","source":"the refresh habit"},
  {"id":"ff-998","cat":"comparison-trap","type":"strike-rewrite","hook":"\"He's posting from abroad while I'm stuck here, so he's just better than me.\"","myth":{"un":"He's abroad, so he's just better than me.","re":"A photo from abroad is one frame, not a ranking of two lives; his post says nothing about your worth.","why":"A travel photo is a moment, not a measure of a person."},"relearn":"A photo from abroad is one frame, not a ranking of two whole lives.","persona":"any","source":"the abroad photo"},
  {"id":"ff-999","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Everyone seems to know exactly what they want; I'm clearly behind for not knowing.\"","myth":{"un":"Everyone knows what they want, so I'm behind.","re":"Most confident-looking people are figuring it out as they go; not-knowing-yet is a normal place to stand.","why":"Certainty is often performed, not felt."},"relearn":"Most confident people are figuring it out too; not-knowing-yet is normal.","persona":"any","source":"the certain crowd"},
  {"id":"ff-1000","cat":"comparison-trap","type":"strike-rewrite","hook":"\"My friend's salary is double mine, so I clearly made the wrong choices.\"","myth":{"un":"Their bigger salary means I chose wrong.","re":"A number on one payslip can't judge a whole path; fit and what matters to you aren't on that figure.","why":"A pay figure measures one job, not your direction or worth."},"relearn":"A salary figure can't judge a whole path; fit isn't on a payslip.","persona":"any","source":"the salary compare"},
  {"id":"ff-1001","cat":"comparison-trap","type":"strike-rewrite","hook":"\"My roommate studies less and scores more, so I'm just not smart enough.\"","myth":{"un":"They study less and score more, so I'm not smart.","re":"You see their result, not their method, background or off-screen effort; this isn't a fair head-to-head.","why":"You compare your visible struggle to their visible outcome only."},"relearn":"You see their result, not their method; it's never a fair head-to-head.","persona":"any","source":"the roommate score"},
  {"id":"ff-1002","cat":"comparison-trap","type":"strike-rewrite","hook":"\"If I'm not as far along as my school friends, I've wasted these years.\"","myth":{"un":"Behind my school friends means I wasted these years.","re":"You've grown in ways no scoreboard shows; 'behind' assumes one finish line that doesn't exist.","why":"Growth isn't only the milestones others post."},"relearn":"You've grown in ways no scoreboard shows; there's no single finish line.","persona":"any","source":"the school-friends gap"},
  {"id":"ff-1003","cat":"comparison-trap","type":"strike-rewrite","hook":"\"Their highlight reel proves they never struggle the way I do.\"","myth":{"un":"Their highlight reel proves they never struggle.","re":"A highlight reel is the edit, not the footage; the cut-out doubts and bad days are there, just unposted.","why":"People share the best take, not the bloopers."},"relearn":"A highlight reel is the edit; the bad days are there, just unposted.","persona":"any","source":"the edit vs footage"},
  {"id":"ff-1004","cat":"comparison-trap","type":"sort","hook":"Sort: the edited highlight reel, or the unposted real picture?","items":[{"id":"a","text":"The convocation photo with the gold medal"},{"id":"b","text":"The four years of late-night doubt before it"},{"id":"c","text":"The 'dream job, blessed' caption"},{"id":"d","text":"The eleven rejection mails not screenshotted"},{"id":"e","text":"The smiling team announcement post"},{"id":"f","text":"The argument and burnout behind that launch"}],"bins":[{"id":"reel","label":"Highlight reel","valence":"uhoh"},{"id":"real","label":"The real picture","valence":"pos"}],"key":{"a":"reel","b":"real","c":"reel","d":"real","e":"reel","f":"real"},"relearn":"The medal and caption are the reel; the doubt and rejections are the real picture.","persona":"any","source":"reel vs real"},
  {"id":"ff-1005","cat":"comparison-trap","type":"sort","hook":"Sort: eases the comparison spiral, or feeds it?","items":[{"id":"a","text":"Muting accounts that make you feel small"},{"id":"b","text":"Refreshing a rival's profile daily"},{"id":"c","text":"Talking honestly with a friend who gets it"},{"id":"d","text":"Counting who posted an offer this week"},{"id":"e","text":"Tracking your own week-on-week progress"},{"id":"f","text":"Reading the comments to see who's ahead"}],"bins":[{"id":"eases","label":"Eases the spiral","valence":"pos"},{"id":"feeds","label":"Feeds the spiral","valence":"neg"}],"key":{"a":"eases","b":"feeds","c":"eases","d":"feeds","e":"eases","f":"feeds"},"relearn":"Muting triggers, honest talk and tracking your own progress ease the spiral; rival-stalking and offer-counting feed it.","persona":"any","source":"ease or feed"},
  {"id":"ff-1006","cat":"comparison-trap","type":"sort","hook":"Sort: a fair comparison, or a rigged one?","items":[{"id":"a","text":"You today vs you at the start of the year"},{"id":"b","text":"Your day one vs their year five"},{"id":"c","text":"Your effort vs the goals you set"},{"id":"d","text":"Your raw reality vs their posted highlights"},{"id":"e","text":"Your progress vs your own last attempt"},{"id":"f","text":"Your behind-the-scenes vs their final cut"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"rigged","label":"Rigged","valence":"neg"}],"key":{"a":"fair","b":"rigged","c":"fair","d":"rigged","e":"fair","f":"rigged"},"relearn":"Measuring against your past self and your goals is fair; against their year five or their final cut is rigged.","persona":"any","source":"fair or rigged"},
  {"id":"ff-1007","cat":"comparison-trap","type":"sort","hook":"Sort: a kind, true thought, or a comparison distortion?","items":[{"id":"a","text":"\"I'm moving at my own pace\""},{"id":"b","text":"\"Everyone my age is ahead of me\""},{"id":"c","text":"\"Their wins don't shrink mine\""},{"id":"d","text":"\"I'm hopelessly, permanently behind\""},{"id":"e","text":"\"Not knowing yet is okay\""},{"id":"f","text":"\"If they're winning, I'm failing\""}],"bins":[{"id":"true","label":"Kind & true","valence":"pos"},{"id":"distort","label":"Distortion","valence":"neg"}],"key":{"a":"true","b":"distort","c":"true","d":"distort","e":"true","f":"distort"},"relearn":"'My own pace' and 'their wins don't shrink mine' are true; 'everyone's ahead' and 'I'm failing' are distortions.","persona":"any","source":"true or distortion"},
  {"id":"ff-1008","cat":"comparison-trap","type":"sort","hook":"Sort: helps your headspace, or fuels the comparison ache?","items":[{"id":"a","text":"A scheduled break from the success feed"},{"id":"b","text":"Doom-scrolling placement posts at 2am"},{"id":"c","text":"Celebrating a friend's news genuinely"},{"id":"d","text":"Screenshotting others' offers to brood over"},{"id":"e","text":"Following people who share their struggles too"},{"id":"f","text":"Only following the curated-success accounts"}],"bins":[{"id":"helps","label":"Helps headspace","valence":"pos"},{"id":"fuels","label":"Fuels the ache","valence":"neg"}],"key":{"a":"helps","b":"fuels","c":"helps","d":"fuels","e":"helps","f":"fuels"},"relearn":"Feed breaks and real celebration help; 2am scrolling and brooding fuel the ache.","persona":"any","source":"help or fuel"},
  {"id":"ff-1009","cat":"comparison-trap","type":"sort","hook":"Sort: noticing to learn from, or measuring your worth against them?","items":[{"id":"a","text":"\"How did she structure her prep? I'll borrow that\""},{"id":"b","text":"\"His result means I'm worthless\""},{"id":"c","text":"\"I can ask her what resources helped\""},{"id":"d","text":"\"If I'm not first, I'm nothing\""},{"id":"e","text":"\"Their approach is interesting; let me try it\""},{"id":"f","text":"\"Every win of theirs is a loss for me\""}],"bins":[{"id":"learn","label":"Learn from","valence":"pos"},{"id":"measure","label":"Measure worth","valence":"neg"}],"key":{"a":"learn","b":"measure","c":"learn","d":"measure","e":"learn","f":"measure"},"relearn":"Borrowing someone's method is learning; making their result a verdict on your worth is the trap.","persona":"any","source":"learn or measure"},
  {"id":"ff-1010","cat":"comparison-trap","type":"sort","hook":"Sort: what a success post actually shows, or what it hides?","items":[{"id":"a","text":"The final offer letter"},{"id":"b","text":"The months of unanswered applications"},{"id":"c","text":"The polished 'so grateful' caption"},{"id":"d","text":"The interview they bombed last week"},{"id":"e","text":"The smiling first-day photo"},{"id":"f","text":"The fear it won't work out"}],"bins":[{"id":"shows","label":"What it shows","valence":"uhoh"},{"id":"hides","label":"What it hides","valence":"pos"}],"key":{"a":"shows","b":"hides","c":"shows","d":"hides","e":"shows","f":"hides"},"relearn":"A success post shows the offer, the caption and the photo; it hides the rejections, the bombed interview and the fear.","persona":"any","source":"shows or hides"},
  {"id":"ff-1011","cat":"comparison-trap","type":"sort","hook":"Sort: a steadying response to the comparison ache, or one that deepens it?","items":[{"id":"a","text":"Naming the feeling: 'this is comparison, not truth'"},{"id":"b","text":"Refreshing their profile to confirm you're behind"},{"id":"c","text":"Returning to your own next small step"},{"id":"d","text":"Replaying their win on a loop in your head"},{"id":"e","text":"Texting a friend who feels it too"},{"id":"f","text":"Deciding their success proves you've failed"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"deepen","label":"Deepens it","valence":"neg"}],"key":{"a":"steady","b":"deepen","c":"steady","d":"deepen","e":"steady","f":"deepen"},"relearn":"Naming the feeling steadies you; replaying their win deepens it.","persona":"any","source":"steady or deepen"},
  {"id":"ff-1012","cat":"comparison-trap","type":"sort","hook":"Sort: what social media usually posts, or what it usually leaves out?","items":[{"id":"a","text":"Graduation gowns and gold medals"},{"id":"b","text":"The backlog cleared on the third try"},{"id":"c","text":"Foreign-trip and new-car photos"},{"id":"d","text":"The therapy sessions and quiet panic"},{"id":"e","text":"The promotion announcement"},{"id":"f","text":"The year of feeling stuck before it"}],"bins":[{"id":"posts","label":"Usually posted","valence":"uhoh"},{"id":"omits","label":"Usually left out","valence":"pos"}],"key":{"a":"posts","b":"omits","c":"posts","d":"omits","e":"posts","f":"omits"},"relearn":"Feeds post gowns, trips and promotions; they leave out the backlogs, the panic and the stuck years.","persona":"any","source":"posts or omits"},
  {"id":"ff-1013","cat":"comparison-trap","type":"sort","hook":"Sort: fits the comparison trap, or breaks out of it?","items":[{"id":"a","text":"\"My only race is with who I was yesterday\""},{"id":"b","text":"\"I'm a failure next to my batch\""},{"id":"c","text":"\"I can be glad for them and proud of me\""},{"id":"d","text":"\"There's a queue and I'm at the back\""},{"id":"e","text":"\"My behind-the-scenes is allowed to be messy\""},{"id":"f","text":"\"If I'm not winning, I'm losing\""}],"bins":[{"id":"breaks","label":"Breaks out","valence":"pos"},{"id":"traps","label":"Stays trapped","valence":"neg"}],"key":{"a":"breaks","b":"traps","c":"breaks","d":"traps","e":"breaks","f":"traps"},"relearn":"'My race is with yesterday's me' and 'glad for them, proud of me' break out; 'failure next to my batch' stays trapped.","persona":"any","source":"break or trap"},
  {"id":"ff-1014","cat":"comparison-trap","type":"sort","hook":"Sort: a thought that costs you nothing, or one that quietly costs your peace?","items":[{"id":"a","text":"\"Her offer is great news, full stop\""},{"id":"b","text":"\"His win means I'm running out of time\""},{"id":"c","text":"\"I can clap for them without keeping score\""},{"id":"d","text":"\"Every post is proof I'm not enough\""},{"id":"e","text":"\"Their good day isn't my bad day\""},{"id":"f","text":"\"I should already be where they are\""}],"bins":[{"id":"free","label":"Costs nothing","valence":"pos"},{"id":"cost","label":"Costs your peace","valence":"neg"}],"key":{"a":"free","b":"cost","c":"free","d":"cost","e":"free","f":"cost"},"relearn":"Clapping for a win costs nothing; making every post proof you're behind costs your peace.","persona":"any","source":"costs nothing or peace"},
  {"id":"ff-1015","cat":"comparison-trap","type":"sort","hook":"Sort: a real reason to feel behind, or just the comparison trap talking?","items":[{"id":"a","text":"A goal you set yourself and missed"},{"id":"b","text":"A stranger online living a different life"},{"id":"c","text":"Feedback you actually got and can act on"},{"id":"d","text":"A relative's idea of when you should 'settle'"},{"id":"e","text":"A skill you genuinely want to build"},{"id":"f","text":"A topper's reel the algorithm showed you"}],"bins":[{"id":"real","label":"A real signal","valence":"pos"},{"id":"trap","label":"Just the trap","valence":"neg"}],"key":{"a":"real","b":"trap","c":"real","d":"trap","e":"real","f":"trap"},"relearn":"Your goals and skills are real signals; strangers and topper reels are just the trap.","persona":"any","source":"signal or trap"},
  {"id":"ff-1016","cat":"comparison-trap","type":"sort","hook":"Sort: a fact about you, or a story the feed is selling you?","items":[{"id":"a","text":"You showed up and did the work this week"},{"id":"b","text":"\"Everyone else has it together\""},{"id":"c","text":"You learned something hard recently"},{"id":"d","text":"\"You're the only one struggling\""},{"id":"e","text":"You have people who care about you"},{"id":"f","text":"\"You're already too far behind to catch up\""}],"bins":[{"id":"fact","label":"A real fact","valence":"pos"},{"id":"story","label":"A feed story","valence":"neg"}],"key":{"a":"fact","b":"story","c":"fact","d":"story","e":"fact","f":"story"},"relearn":"That you showed up, learned and are cared for are facts; 'everyone's sorted' and 'too far behind' are stories the feed sells.","persona":"any","source":"fact or story"},
  {"id":"ff-1017","cat":"comparison-trap","type":"sort","hook":"Sort: a healthy way to use someone's success, or the trap dressed as motivation?","items":[{"id":"a","text":"Asking them which resources actually helped"},{"id":"b","text":"Using their win to beat yourself up"},{"id":"c","text":"Taking one idea from their approach to try"},{"id":"d","text":"Refreshing their feed to feel worse on purpose"},{"id":"e","text":"Letting their progress show a path is possible"},{"id":"f","text":"Treating their result as your scorecard"}],"bins":[{"id":"healthy","label":"Healthy use","valence":"pos"},{"id":"trap","label":"Trap in disguise","valence":"neg"}],"key":{"a":"healthy","b":"trap","c":"healthy","d":"trap","e":"healthy","f":"trap"},"relearn":"Asking what helped is healthy; using a win against yourself isn't.","persona":"any","source":"healthy or trap"},
  {"id":"ff-1018","cat":"comparison-trap","type":"branch","hook":"Results are out. Half your group already posted offers; you got none yet.","options":[{"text":"Close the app, breathe, and message a friend who's in the same boat","consequence":"You step out of the spiral and feel less alone.","outcome":"grounded","best":true},{"text":"Scroll every offer post and tally how far behind you are","consequence":"Stepping back and a friend ease this; tallying offers tightens the knot."}],"debrief":"You're not the only one without news yet; stepping back eases the spike.","relearn":"When the feed spikes you, step back and reach someone who gets it.","persona":"Deepak","source":"results-day feed"},
  {"id":"ff-1019","cat":"comparison-trap","type":"branch","hook":"A close friend got into a programme you wanted. You feel a real pang of envy.","options":[{"text":"Send a genuine congrats, then sit with your own feelings separately","consequence":"You keep the friendship and let the envy pass.","outcome":"warm","best":true},{"text":"Go quiet and let the envy cool things between you","consequence":"Congratulating protects the friendship; going cold just adds loss to the ache."}],"debrief":"Their win isn't your loss; be glad for them and hold your own feelings.","relearn":"Celebrate a friend and feel your own pang; both can be true at once.","persona":"any","source":"the friend's good news"},
  {"id":"ff-1020","cat":"comparison-trap","type":"branch","hook":"You notice your feed is now mostly people whose lives make you feel small.","options":[{"text":"Curate it: mute the shame-triggers, follow people who keep it real","consequence":"Your daily inputs shift toward inspiring, not crushing.","outcome":"curated","best":true},{"text":"Keep the feed as is and brace for the daily sting","consequence":"Kinder accounts change each day; leaving it just keeps the sting."}],"debrief":"Your feed shapes your mood; curating away from shame-triggers is self-care.","relearn":"Curate your feed toward what steadies you, not what shames you.","persona":"any","source":"curating the feed"},
  {"id":"ff-1021","cat":"comparison-trap","type":"branch","hook":"A relative lists every 'settled' cousin and asks why you aren't there yet.","options":[{"text":"Hold your line warmly: 'We're on different paths; mine's moving at its own pace'","consequence":"You stay steady without rupture or self-doubt.","outcome":"steady","best":true},{"text":"Take it as proof you've fallen behind and spiral after","consequence":"Holding your pace grounds you; taking it as a verdict feeds the ache."}],"debrief":"A relative's timeline isn't yours; hold your path gently.","relearn":"Hold your pace warmly; a relative's timeline isn't a verdict on yours.","persona":"Aarti","source":"the settled cousins"},
  {"id":"ff-1022","cat":"comparison-trap","type":"branch","hook":"It's late; you've spent an hour comparing your year to everyone's reels.","options":[{"text":"Put the phone down; write one thing you actually did this year","consequence":"You reconnect with your real progress, not an edited feed.","outcome":"refocused","best":true},{"text":"Keep scrolling to confirm just how behind you are","consequence":"Naming one real thing refocuses you; scrolling deepens the hollow."}],"debrief":"Reels are edits; refocusing on your own real progress steadies you.","relearn":"When reels leave you hollow, name one real thing you did.","persona":"any","source":"the late-night reels"},
  {"id":"ff-1023","cat":"comparison-trap","type":"branch","hook":"You're about to text a friend, 'everyone's ahead and I'm panicking.'","options":[{"text":"Send it — let a friend who gets it remind you you're not alone","consequence":"Saying it out loud lightens it; you hear you're not the only one.","outcome":"connected","best":true},{"text":"Delete it and carry the whole weight quietly","consequence":"Naming it shares the load; carrying it alone lets it grow."}],"debrief":"Companionship reduces this; you're not the only one feeling behind.","relearn":"Saying 'I feel behind' shares the weight; you're not alone.","persona":"any","source":"the unsent text"},
  {"id":"ff-1024","cat":"comparison-trap","type":"branch","hook":"A reel promises 'cracked it at 22 — you're already too late.' Your stomach drops.","options":[{"text":"Recognise the fear-bait, unfollow, and step away","consequence":"You stop feeding on doom content built to rattle you.","outcome":"unhooked","best":true},{"text":"Believe it and let 'too late' settle in","consequence":"Spotting fear-bait protects you; believing 'too late' buys a false story."}],"debrief":"'You're too late' is fear-bait; there's no fixed deadline you're failing.","relearn":"'Too late' reels are fear-bait; no fixed deadline is failing you.","persona":"any","source":"the too-late reel"},
  {"id":"ff-1025","cat":"comparison-trap","type":"spot","hook":"Spot the two comparison-trap thoughts to catch (the rest are kinder, truer ones).","scene":[{"id":"a","text":"\"Everyone my age is miles ahead of me\"","trick":true},{"id":"b","text":"\"My path is moving at its own pace\"","trick":false},{"id":"c","text":"\"If they're succeeding, I must be failing\"","trick":true},{"id":"d","text":"\"Their highlight reel isn't my full story\"","trick":false},{"id":"e","text":"\"I can learn from them without ranking myself\"","trick":false}],"why":"'Everyone's ahead' and 'their success means my failure' are the traps; the rest hold your path.","relearn":"'Everyone's ahead' and 'their win is my failure' are traps, not truths.","persona":"any","source":"catch the trap"},
  {"id":"ff-1026","cat":"comparison-trap","type":"spot","hook":"Spot the two thoughts that turn a friend's win into your loss (catch those).","scene":[{"id":"a","text":"\"That's wonderful, I'm happy for them\"","trick":false},{"id":"b","text":"\"Their win means there's less left for me\"","trick":true},{"id":"c","text":"\"I can be glad and still hold my own pace\"","trick":false},{"id":"d","text":"\"If they're up, I must be down\"","trick":true},{"id":"e","text":"\"Their good day isn't a verdict on mine\"","trick":false}],"why":"'Less left for me' and 'if they're up I'm down' make it zero-sum; the rest cost you nothing.","relearn":"Treating a friend's win as your loss is the trap; their day isn't your bad one.","persona":"any","source":"zero-sum thinking"},
  {"id":"ff-1027","cat":"comparison-trap","type":"spot","hook":"Spot the two parts of a success post that are the edited highlight, not the full picture.","scene":[{"id":"a","text":"\"Thrilled to share my new role! Dream come true\"","trick":true},{"id":"b","text":"(unposted) 40 rejections before this one","trick":false},{"id":"c","text":"The perfectly-lit office photo","trick":true},{"id":"d","text":"(unposted) months of not hearing back","trick":false},{"id":"e","text":"(unposted) the quiet fear it won't last","trick":false}],"why":"The caption and photo are the edit; the rejections, silence and fear are the real picture left off.","relearn":"The caption and photo are the edit; rejections and fear are the real picture.","persona":"any","source":"edit vs picture"},
  {"id":"ff-1028","cat":"comparison-trap","type":"spot","hook":"Spot the two lines where the feed is selling you a false story (catch the lies).","scene":[{"id":"a","text":"\"Everyone but you has it figured out\"","trick":true},{"id":"b","text":"\"People post wins, not the worry behind them\"","trick":false},{"id":"c","text":"\"You're the only one this far behind\"","trick":true},{"id":"d","text":"\"Most people are also figuring it out as they go\"","trick":false},{"id":"e","text":"\"Confident faces often hide private doubt\"","trick":false}],"why":"'Everyone but you is sorted' and 'only you are behind' are the feed's false stories; rest are truer.","relearn":"'Only you are behind' is the feed's lie, not the truth.","persona":"any","source":"the feed's lies"},
  {"id":"ff-1029","cat":"comparison-trap","type":"spot","hook":"Spot the two 'motivation' lines that are really the comparison trap in disguise.","scene":[{"id":"a","text":"\"Borrow her study method, that's useful\"","trick":false},{"id":"b","text":"\"Not first like him means I'm worthless\"","trick":true},{"id":"c","text":"\"Their result means I should give up\"","trick":true},{"id":"d","text":"\"I can ask what resources helped them\"","trick":false},{"id":"e","text":"\"Their progress shows a path is possible\"","trick":false}],"why":"'Worthless if not first' and 'their result means give up' are the trap; the rest learn fairly.","relearn":"A result is never a verdict on your worth; that's the trap, not motivation.","persona":"any","source":"fake motivation"},
  {"id":"ff-1030","cat":"comparison-trap","type":"spot","hook":"Spot the two lines that measure your worth against someone's highlights (catch those).","scene":[{"id":"a","text":"\"Her package is bigger, so I'm lesser\"","trick":true},{"id":"b","text":"\"Fit matters to me more than her title\"","trick":false},{"id":"c","text":"\"His rank decides whether I matter\"","trick":true},{"id":"d","text":"\"A payslip can't measure my worth\"","trick":false},{"id":"e","text":"\"I get a different definition of doing well\"","trick":false}],"why":"Tying your worth to her package or his rank is the trap; the rest keep value off the scoreboard.","relearn":"Your worth isn't a package or rank; the scoreboard doesn't measure you.","persona":"any","source":"worth on the scoreboard"},
  {"id":"ff-1031","cat":"comparison-trap","type":"spot","hook":"Spot the two habits that feed the comparison spiral (catch the harmful ones).","scene":[{"id":"a","text":"Muting accounts that leave you feeling small","trick":false},{"id":"b","text":"Refreshing a rival's profile every hour","trick":true},{"id":"c","text":"Tracking your own week-on-week progress","trick":false},{"id":"d","text":"Screenshotting others' offers to brood on","trick":true},{"id":"e","text":"Following people who post their struggles too","trick":false}],"why":"Hourly refreshing and brooding over screenshotted offers feed the spiral; the others ease it.","relearn":"Refreshing rivals and brooding over offers feed the spiral; muting eases it.","persona":"any","source":"spiral habits"},
  {"id":"ff-1032","cat":"comparison-trap","type":"role-play","hook":"Your sibling keeps holding up a high-flying cousin and asking when you'll 'catch up.'","setup":"Lensy: Hold your own pace, kindly but clearly. Say:","yourLine":[{"text":"\"We're on different paths; I'm okay moving at mine, even if it looks slower.\"","best":true},{"text":"\"Yeah, I guess I'm just slower and behind at everything.\""}],"relearn":"Hold your own pace against a 'catch up' comparison; you don't have to accept it as a verdict.","persona":"any","source":"the catch-up sibling"},
  {"id":"ff-1033","cat":"comparison-trap","type":"role-play","hook":"A friend is crushed, scrolling everyone's placement posts and calling themselves a failure.","setup":"Lensy: Reframe it for them. Say:","yourLine":[{"text":"\"Those are highlight reels, not whole stories. You're not behind, you're on your own path.\"","best":true},{"text":"\"Honestly, yeah, looks like you've fallen behind everyone.\""}],"relearn":"Remind a friend that placement posts are highlight reels, not their whole story.","persona":"any","source":"comforting a friend"},
  {"id":"ff-1034","cat":"comparison-trap","type":"role-play","hook":"A batchmate shares big news and you feel the envy rise before you can think.","setup":"Lensy: Lead with warmth anyway. Say:","yourLine":[{"text":"\"That's genuinely brilliant — I'm really happy for you!\"","best":true},{"text":"Let the envy flatten your reply into a dry 'cool.'"}],"relearn":"Lead with warmth at someone's win; their good news isn't a verdict on you.","persona":"any","source":"swallowing envy"},
  {"id":"ff-1035","cat":"comparison-trap","type":"role-play","hook":"Your inner voice says, 'everyone's sorted and you're the only one floundering.'","setup":"Lensy: Answer that voice. Say:","yourLine":[{"text":"\"Most people are figuring it out too; I'm comparing my insides to their highlight reels.\"","best":true},{"text":"\"You're right, I'm the only one this lost.\""}],"relearn":"Answer the 'only you are floundering' voice: you're comparing your insides to their highlight reels.","persona":"any","source":"the inner critic"},
  {"id":"ff-1036","cat":"comparison-trap","type":"role-play","hook":"A junior asks you how you're 'so calm' when the whole batch is panicking.","setup":"Lensy: Be honest, not performative. Say:","yourLine":[{"text":"\"I'm not always calm — I just try not to measure myself against everyone's posts.\"","best":true},{"text":"\"Oh, I've got it all completely figured out, don't worry.\""}],"relearn":"You don't have to perform 'sorted'; honesty about the struggle loosens the comparison pressure for everyone.","persona":"any","source":"the calm act"},
  {"id":"ff-1037","cat":"comparison-trap","type":"role-play","hook":"A classmate brags about an offer and waits for you to feel small about your own search.","setup":"Lensy: Stay warm and unrattled. Say:","yourLine":[{"text":"\"That's great for you. I'm still on my search, and that's okay.\"","best":true},{"text":"\"Wow, so I'm clearly the loser here then.\""}],"relearn":"You can be glad for someone's offer and unbothered about your own timeline at the same time.","persona":"any","source":"the bragging classmate"},
  {"id":"ff-1038","cat":"comparison-trap","type":"role-play","hook":"You see a friend quietly comparing themselves to a viral 'I made it at 21' post.","setup":"Lensy: Step in gently. Say:","yourLine":[{"text":"\"That's one edited story, not a timeline you're failing. You're doing fine on yours.\"","best":true},{"text":"\"Yeah, people really do it younger than us, huh.\""}],"relearn":"A viral 'made it young' post is one edited story, not a timeline anyone is failing against.","persona":"any","source":"the viral post"},
  {"id":"ff-1039","cat":"comparison-trap","type":"role-play","hook":"Meena, working alone with no campus network, mutters that everyone else 'had a head start.'","setup":"Lensy: Meet her where she is, then loosen it. Say:","yourLine":[{"text":"\"Your start was harder, and you're still moving. That's strength, not being behind.\"","best":true},{"text":"\"Yeah, they had it easier, so you're basically out of the race.\""}],"relearn":"A harder start isn't being behind; steady movement from there is real strength, not a deficit.","persona":"Meena","source":"the head-start ache"},
  {"id":"ff-1040","cat":"comparison-trap","type":"role-play","hook":"A friend says, 'I can't even be happy for people anymore, I just feel behind.'","setup":"Lensy: Normalise it, then ease it. Say:","yourLine":[{"text":"\"That's the comparison trap, not you. Their wins can cost you nothing once you step back.\"","best":true},{"text":"\"Yeah, other people's wins really are bad news for us.\""}],"relearn":"Struggling to be happy for others is the comparison trap talking; their wins can cost you nothing.","persona":"any","source":"can't be happy"},
  {"id":"ff-1041","cat":"comparison-trap","type":"role-play","hook":"Rohan, mid-spiral over a friend's success, says reaching out would just make him look pathetic.","setup":"Lensy: Reframe reaching out as smart. Say:","yourLine":[{"text":"\"Telling a friend you feel behind isn't weak — it's how people get through this stretch.\"","best":true},{"text":"\"Yeah, better keep it to yourself so no one sees you struggle.\""}],"relearn":"Saying 'I feel behind' to a friend isn't weakness; sharing the load is how people get through this.","persona":"Rohan","source":"reaching out isn't weak"},
  {"id":"ff-1042","cat":"comparison-trap","type":"match","hook":"Match each comparison-trap thought to the kinder truth that loosens it.","pairs":[{"left":"\"Everyone's ahead of me\"","right":"Everyone's on a different timeline"},{"left":"\"Their reel = their whole life\"","right":"A reel is the edit; doubts are cut"},{"left":"\"Their win is my loss\"","right":"Celebrating others costs you nothing"},{"left":"\"I'm the only one struggling\"","right":"Almost everyone feels behind sometimes"},{"left":"\"Comparison will push me\"","right":"Your own small step moves you, not the sting"}],"relearn":"Each trap has a kinder truth; their wins cost you nothing.","persona":"any","source":"trap to truth"},
  {"id":"ff-1043","cat":"comparison-trap","type":"match","hook":"Match each thing you see online to what it usually leaves unposted.","pairs":[{"left":"The offer-letter screenshot","right":"The pile of rejections before it"},{"left":"The 'living the dream' caption","right":"The 3am worry behind it"},{"left":"The new-car photo","right":"The years of feeling stuck first"},{"left":"The topper's clean result","right":"The off-screen effort and luck"},{"left":"The confident first-day post","right":"The quiet fear it won't work out"}],"relearn":"Every posted win hides something: rejections, worry, stuck years, off-screen effort, or fear it won't last.","persona":"any","source":"posted vs unposted"},
  {"id":"ff-1044","cat":"comparison-trap","type":"match","hook":"Match each comparison habit to what it actually does to you.","pairs":[{"left":"Refreshing a rival's profile hourly","right":"Spikes anxiety, moves nothing forward"},{"left":"Muting accounts that sting","right":"Protects your daily headspace"},{"left":"Tracking your own progress","right":"Shows real, fair movement"},{"left":"Counting who got placed","right":"Feeds the 'I'm behind' story"},{"left":"Telling a friend you feel behind","right":"Shares the load, eases the ache"}],"relearn":"Stalking and counting feed the spiral; muting, self-tracking and reaching out ease it and move you forward.","persona":"any","source":"habit to effect"},
  {"id":"ff-1045","cat":"comparison-trap","type":"match","hook":"Match each person to the only fair thing to compare their progress against.","pairs":[{"left":"You, this year","right":"You, at the start of this year"},{"left":"Your effort","right":"The goals you actually set"},{"left":"Your attempt","right":"Your own last attempt"},{"left":"Your skills","right":"Where you began with them"},{"left":"Your path","right":"What genuinely fits you"}],"relearn":"The only fair comparison is you against your own past, your own goals, and what actually fits you.","persona":"any","source":"fair yardsticks"},
  {"id":"ff-1046","cat":"comparison-trap","type":"match","hook":"Match each comparison moment to a steadying next move.","pairs":[{"left":"Feed leaves you feeling small","right":"Mute the triggers, take a break"},{"left":"A friend's big news stings","right":"Congratulate, then sit with your own feeling"},{"left":"Spiralling at 2am","right":"Phone down, name one thing you did"},{"left":"A relative compares you to a cousin","right":"Hold your pace warmly, no rupture"},{"left":"It's all feeling too heavy","right":"Tell someone you trust; you're not alone"}],"relearn":"Each moment has a steady move: mute triggers, congratulate, name your wins, reach out.","persona":"any","source":"moment to move"},
  {"id":"ff-1047","cat":"comparison-trap","type":"match","hook":"Match each false comparison story to the fact that quietly disproves it.","pairs":[{"left":"\"Everyone but me is sorted\"","right":"Confident faces hide the same doubts"},{"left":"\"I'm the only one behind\"","right":"Most of your batch feels it too"},{"left":"\"Their success means I failed\"","right":"One person's win isn't a verdict on you"},{"left":"\"I'm out of time\"","right":"There's no fixed deadline you're failing"},{"left":"\"Their reel is their real life\"","right":"Reels are edits, not full footage"}],"relearn":"Each false story has a fact: doubts hide, no win is a verdict, reels are edits.","persona":"any","source":"story to fact"},
  {"id":"ff-1048","cat":"comparison-trap","type":"match","hook":"Match each way of looking at someone's success to what it leads to.","pairs":[{"left":"Asking what resources helped them","right":"You learn something useful"},{"left":"Borrowing one idea from their method","right":"You improve your own approach"},{"left":"Making their result your scorecard","right":"You feel smaller, learn nothing"},{"left":"Brooding over their post for hours","right":"You lose time and peace"},{"left":"Letting it show a path is possible","right":"You feel a little more hopeful"}],"relearn":"Curiosity about a method teaches you; a result as your scorecard shrinks you.","persona":"any","source":"looking to outcome"},
  {"id":"ff-1049","cat":"comparison-trap","type":"match","hook":"Match each persona's comparison ache to the truth that loosens it.","pairs":[{"left":"Deepak: no network, friends ahead","right":"A harder start isn't being behind"},{"left":"Aarti: cousins all 'settled'","right":"Your timeline isn't your relatives'"},{"left":"Zoya: family's path differs","right":"Your path is allowed to look different"},{"left":"Meena: alone, no safety net","right":"Steady movement from a hard start is strength"},{"left":"Rohan: 'asking help looks weak'","right":"Reaching out is smart, not weak"}],"relearn":"A hard start isn't being behind; your timeline is your own.","persona":"any","source":"persona to truth"},
  {"id":"ff-1050","cat":"comparison-trap","type":"reflect","hook":"Lensy: No right answer here — just notice yourself.","prompt":"When a friend's good news lands and you feel that pang, what do you usually do first?","options":["Congratulate them, then sit with my own feeling later","Go quiet for a bit while it passes","Notice the pang and remind myself their win isn't my loss","Talk to someone about how I'm feeling"],"affirm":"That pang is human; it doesn't make you a bad friend. Their win and your feelings both fit. 🌱","persona":"any","source":"the pang","relearn":"Feeling a pang doesn't make you a bad friend."},
  {"id":"ff-1051","cat":"comparison-trap","type":"reflect","hook":"Lensy: There's no wrong answer — just be honest with yourself.","prompt":"Which account or feed leaves you feeling most 'behind' lately?","options":["The placement and offer posts","The 'soft life / made it young' reels","Old school or college friends' updates","Honestly, almost all of it some days"],"affirm":"Noticing what stings is the first step to protecting your headspace. You're allowed to mute, unfollow, or step away. 🌱","persona":"any","source":"what stings","relearn":"Noticing which feeds sting is the first step to protecting your headspace."},
  {"id":"ff-1052","cat":"comparison-trap","type":"reflect","hook":"Lensy: Just notice — nothing to get right.","prompt":"What's one real thing you did this month that no feed would ever show?","options":["Kept showing up when it was hard","Learned or improved at something","Was there for someone I care about","Took care of myself on a rough day"],"affirm":"That counts, even unposted. Your behind-the-scenes is real progress, whether or not anyone claps for it. 🌱","persona":"any","source":"the unposted win","relearn":"Your unposted progress is real, whether or not a feed would ever show it."},
  {"id":"ff-1053","cat":"comparison-trap","type":"reflect","hook":"Lensy: No scoring here — just reflect.","prompt":"When the comparison spiral hits hardest, what's usually going on for you?","options":["I'm tired or running low","I just saw a wave of success posts","Something's uncertain about my own path","I've been comparing instead of resting"],"affirm":"The spiral often hits when you're depleted, not when you're failing. Steady yourself first; the feeling passes. 🌱","persona":"any","source":"when it hits","relearn":"The spiral often hits when you're depleted, not when you're failing."},
  {"id":"ff-1054","cat":"comparison-trap","type":"reflect","hook":"Lensy: There's no right pick — just what feels true for you.","prompt":"What would help most when you catch yourself measuring your life against a feed?","options":["Putting the phone down for a while","Texting a friend who feels it too","Coming back to my own next small step","Reminding myself it's an edited reel"],"affirm":"Any of these works; the trick is just stepping out of the scroll. You needn't earn a break. 🌱","persona":"any","source":"what helps you","relearn":"Stepping out of the scroll helps; you don't have to earn that break."},
  {"id":"ff-1055","cat":"comparison-trap","type":"reflect","hook":"Lensy: Just notice your own pattern — no wrong answer.","prompt":"Whose timeline do you most often measure yourself against?","options":["A specific friend or cousin","Strangers I see online","An imagined 'everyone else'","A version of where I 'should' be by now"],"affirm":"Often the yardstick is imagined or curated, not real. Naming it loosens its grip; your pace is allowed to be yours. 🌱","persona":"any","source":"whose timeline","relearn":"The yardstick is often imagined or curated; your pace is allowed to be yours."},
  {"id":"ff-1056","cat":"comparison-trap","type":"reflect","hook":"Lensy: No right answer — just sit with it.","prompt":"If you stopped comparing for a week, what might you have more room for?","options":["More energy for my own work","Genuine happiness for friends","Less anxiety scrolling at night","A clearer sense of what I actually want"],"affirm":"Comparison quietly takes up space; stepping back gives some of it back. You don't owe the feed your peace. 🌱","persona":"any","source":"more room","relearn":"Comparison quietly takes up space; stepping back gives some of it back."},
  {"id":"ff-1057","cat":"comparison-trap","type":"reflect","hook":"Lensy: Heavy stuff allowed here — no wrong answer.","prompt":"When the 'everyone's ahead' feeling gets really heavy, what do you reach for?","options":["A walk or a break from screens","A friend or someone I trust","Reminding myself it's the trap talking","I'm not sure I reach for anything yet"],"affirm":"If it ever turns into constant, heavy distress, support helps: Tele-MANAS 14416. You don't carry it alone. 🌱","persona":"any","source":"when it's heavy","relearn":"If 'everyone's ahead' turns into heavy distress, real support helps."},
  {"id":"ff-1080","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"By 22 you should know exactly what career you want.\"","myth":{"un":"By 22 I should know exactly what I want.","re":"Most people are still figuring it out well past 22; clarity comes from trying things, not a deadline.","why":"There's no age by which a direction must be locked."},"relearn":"There's no deadline by which your direction must be locked.","persona":"any","source":"no deadline"},
  {"id":"ff-1081","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"If I take a gap year I'll fall hopelessly behind everyone.\"","myth":{"un":"A gap year means I fall behind for good.","re":"A considered pause to explore or earn is a normal, valid step many people take and recover from easily.","why":"A career runs for decades; one year rarely changes the shape of it."},"relearn":"A considered gap is a valid step, not falling behind for good.","persona":"Meena","source":"gap year"},
  {"id":"ff-1082","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Everyone in my hostel has their five-year plan; I'm the only blank one.\"","myth":{"un":"Everyone else has a five-year plan and I'm blank.","re":"Most of those neat plans are half-bluff; almost everyone is improvising under a confident face.","why":"A tidy answer to 'what's your plan' is usually performance, not certainty."},"relearn":"Most confident-sounding plans are half-bluff; you're not the only blank one.","persona":"any","source":"the bluffed plan"},
  {"id":"ff-1083","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Not having a 'dream' by now means something's wrong with me.\"","myth":{"un":"No big dream by now means something's wrong with me.","re":"Plenty of content people never had one grand dream; interests that grow over time count just as much.","why":"A single burning passion is a story, not a requirement."},"relearn":"You don't need one grand dream; interests that grow over time count too.","persona":"any","source":"no one dream"},
  {"id":"ff-1084","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"If my degree isn't 'used' directly, the whole thing was a waste.\"","myth":{"un":"If I don't use my degree directly, it was wasted.","re":"Skills travel: many people thrive in fields unrelated to their degree, carrying what they learned.","why":"What you build — thinking, discipline, people skills — moves with you anywhere."},"relearn":"Skills travel; an unrelated path doesn't make your degree wasted.","persona":"Deepak","source":"degree not wasted"},
  {"id":"ff-1085","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Switching streams after first year means I clearly chose wrong.\"","myth":{"un":"Switching streams means I clearly chose wrong.","re":"Realising a fit isn't right and adjusting is good information used well, not a confession of failure.","why":"You can only learn a fit by trying it; changing course is that learning in action."},"relearn":"Adjusting course is good information used well, not proof you chose wrong.","persona":"any","source":"switching streams"},
  {"id":"ff-1086","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Successful people had it all mapped out from the start.\"","myth":{"un":"Successful people had it all mapped from the start.","re":"Look closely and most well-known careers were full of swerves, luck and side-doors, not a straight line.","why":"The clean origin story is told backwards, after the fact."},"relearn":"Most careers were full of swerves, not a straight line mapped from the start.","persona":"any","source":"told backwards"},
  {"id":"ff-1087","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"I have to pick the one perfect path or I'll regret it forever.\"","myth":{"un":"I must pick the one perfect path or regret it forever.","re":"There's rarely a single perfect path; several good ones exist, and you can adjust as you go.","why":"Most regret comes from never starting, not from picking one good-enough door."},"relearn":"There's rarely one perfect path; several good ones exist and you can adjust.","persona":"any","source":"no single perfect path"},
  {"id":"ff-1088","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Feeling lost at this age means I'm doing life wrong.\"","myth":{"un":"Feeling lost now means I'm doing life wrong.","re":"Feeling lost at this stage is so common it's almost a milestone; it usually means you're between, not broken.","why":"Big transitions feel disorienting for nearly everyone going through them."},"relearn":"Feeling lost now usually means you're between stages, not doing life wrong.","persona":"Ananya","source":"between stages"},
  {"id":"ff-1089","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"If I can't see the whole career, there's no point starting.\"","myth":{"un":"If I can't see the whole career, no point starting.","re":"You only ever see a few steps ahead; starting reveals the next bend that planning never could.","why":"The path shows itself by walking it, not by staring at a blank map."},"relearn":"You only see a few steps ahead; starting reveals the next bend.","persona":"any","source":"the next bend"},
  {"id":"ff-1090","cat":"not-all-sorted","type":"strike-rewrite","hook":"\"Being undecided means I'm lazy or not serious.\"","myth":{"un":"Being undecided means I'm lazy or not serious.","re":"Honest uncertainty is often the opposite of lazy — it's taking the choice seriously enough not to fake it.","why":"Refusing to bluff a plan is a form of care, not carelessness."},"relearn":"Honest uncertainty often means you're taking the choice seriously, not lazy.","persona":"any","source":"not lazy"},
  {"id":"ff-1091","cat":"not-all-sorted","type":"reflect","hook":"Lensy: the people who look most 'sorted' are often just better at hiding the same doubts you have. Sit with that?","prompt":"What do you think?","options":["Yes","They hide it too","That's a relief"],"affirm":"The confident face is mostly practice; behind it sits the same uncertainty almost everyone carries.","relearn":"The most 'sorted'-looking people are often just better at hiding the same doubts.","persona":"any","source":"the hidden doubt"},
  {"id":"ff-1092","cat":"not-all-sorted","type":"reflect","hook":"Lensy: you're allowed to say 'I'm still working it out' out loud — it's an honest answer, not a confession. Try it?","prompt":"How does that land?","options":["Honest","Freeing","I can say that"],"affirm":"'I'm still working it out' is a complete, respectable answer; you owe no one a finished plan.","relearn":"'I'm still working it out' is an honest answer, not a confession.","persona":"any","source":"saying it out loud"},
  {"id":"ff-1093","cat":"not-all-sorted","type":"reflect","hook":"Lensy: at 20 you have far more time than the panic suggests; you're early, not late. Does that loosen things?","prompt":"What do you feel?","options":["Earlier than I thought","Less rushed","More room"],"affirm":"You genuinely have decades ahead; the 'it's all slipping away' feeling is the panic talking, not the clock.","relearn":"At this age you're early, not late; you have far more time than panic suggests.","persona":"any","source":"more time than it feels"},
  {"id":"ff-1094","cat":"not-all-sorted","type":"reflect","hook":"Lensy: 'I don't know yet' and 'I'm not capable' are two very different sentences. Notice they aren't the same?","prompt":"What do you think?","options":["They're different","Not the same thing","Good to separate"],"affirm":"Not knowing your direction yet says nothing about your ability; one is a question, the other a false verdict.","relearn":"'I don't know yet' and 'I'm not capable' are two completely different sentences.","persona":"any","source":"two sentences"},
  {"id":"ff-1095","cat":"not-all-sorted","type":"reflect","hook":"Lensy: curiosity is a better compass right now than a fixed five-year plan. Could you follow what interests you?","prompt":"What do you think?","options":["Yes","Follow curiosity","Worth a try"],"affirm":"Curiosity points you toward fits a rigid plan can't predict; it's a fine way to navigate uncertainty.","relearn":"Curiosity is a better compass right now than a fixed five-year plan.","persona":"Zoya","source":"curiosity as compass"},
  {"id":"ff-1096","cat":"not-all-sorted","type":"reflect","hook":"Lensy: your timeline is yours — it doesn't have to match your cousin's, your batchmate's or your parents' idea. Okay?","prompt":"How does that sit?","options":["My timeline","That's allowed","Eases the pressure"],"affirm":"There's no shared clock everyone's racing on; your pace is allowed to be your own.","relearn":"Your timeline is yours; it doesn't have to match anyone else's.","persona":"Aarti","source":"your own timeline"},
  {"id":"ff-1097","cat":"not-all-sorted","type":"reflect","hook":"Lensy: 'figuring it out as you go' isn't a backup plan — it's how almost everyone actually does it. Believe it?","prompt":"What do you think?","options":["Yes","That's the norm","Reassuring"],"affirm":"Improvising forward, adjusting with each step, is the real method behind most lives, not a fallback.","relearn":"Figuring it out as you go isn't a backup plan; it's how almost everyone does it.","persona":"any","source":"the real method"},
  {"id":"ff-1098","cat":"not-all-sorted","type":"reflect","hook":"Lensy: you can hold a direction loosely and still take it seriously. A plan can flex without falling apart. Yes?","prompt":"What do you feel?","options":["Yes","Hold it loosely","That works"],"affirm":"A loose, revisable direction beats a rigid one you'd cling to even when it stops fitting.","relearn":"You can hold a direction loosely and still take it seriously.","persona":"any","source":"holding loosely"},
  {"id":"ff-1099","cat":"not-all-sorted","type":"reflect","hook":"Lensy: notice the question 'what if I never figure it out?' is fear talking, not fact. Can you let it pass?","prompt":"What do you think?","options":["It's fear, not fact","Let it pass","Okay"],"affirm":"That dread is a feeling, not a forecast; people who once felt exactly this found their footing anyway.","relearn":"'What if I never figure it out?' is fear talking, not fact.","persona":"any","source":"fear not fact"},
  {"id":"ff-1100","cat":"not-all-sorted","type":"reflect","hook":"Lensy: comparing your messy middle to someone's polished start is unfair to you. Drop that yardstick?","prompt":"How does that land?","options":["Unfair to me","Drop it","Yes"],"affirm":"You're seeing their edited surface and your raw inside; that was never a fair measurement.","relearn":"Comparing your messy middle to someone's polished start is unfair to you.","persona":"any","source":"unfair yardstick"},
  {"id":"ff-1101","cat":"not-all-sorted","type":"reflect","hook":"Lensy: it's okay if today's only clear answer is one small thing to try this week. Is that enough for now?","prompt":"What do you think?","options":["That's enough","One small thing","Yes"],"affirm":"One thing to try this week is a real answer; you don't have to resolve your whole life today.","relearn":"It's okay if today's only answer is one small thing to try this week.","persona":"Deepak","source":"enough for now"},
  {"id":"ff-1102","cat":"not-all-sorted","type":"reflect","hook":"Lensy: changing your mind as you learn more is a sign of growth, not flakiness. Can you reframe it that way?","prompt":"What do you feel?","options":["It's growth","Not flakiness","Reframed"],"affirm":"Updating your direction with new information is exactly what thoughtful people do; it isn't being unreliable.","relearn":"Changing your mind as you learn more is growth, not flakiness.","persona":"any","source":"growth not flakiness"},
  {"id":"ff-1103","cat":"not-all-sorted","type":"reflect","hook":"Lensy: you don't have to earn rest by first 'having it sorted'. Breathing space is allowed even mid-uncertainty. Okay?","prompt":"How does that sit?","options":["Rest is allowed","Even now","Okay"],"affirm":"Rest isn't a reward for certainty; you're allowed to pause and breathe while things are still unclear.","relearn":"You don't have to earn rest by first having it sorted.","persona":"any","source":"rest is allowed"},
  {"id":"ff-1104","cat":"not-all-sorted","type":"reflect","hook":"Lensy: 'undecided' is a starting point thousands stand on every year, then move from. You're in good company. Yes?","prompt":"What do you think?","options":["Good company","Not alone","Yes"],"affirm":"Standing at 'undecided' is crowded, not lonely; it's a common launchpad, not a dead end.","relearn":"'Undecided' is a starting point thousands stand on, then move from.","persona":"any","source":"good company"},
  {"id":"ff-1105","cat":"not-all-sorted","type":"reflect","hook":"Lensy: the goal isn't to remove all uncertainty — it's to act steadily despite it. Can you live with some unknown?","prompt":"What do you feel?","options":["I can","Act despite it","Yes"],"affirm":"Certainty isn't the entry fee for moving forward; you can take steps while plenty stays unknown.","relearn":"The goal isn't to remove all uncertainty; it's to act steadily despite it.","persona":"any","source":"act despite it"},
  {"id":"ff-1106","cat":"not-all-sorted","type":"branch","hook":"Relatives keep asking 'so what's the final plan?' and it's winding you up.","options":[{"text":"Say honestly you're exploring, and let it go","consequence":"You stay grounded, not borrowing their urgency.","outcome":"grounded","best":true},{"text":"Invent a fake plan to shut them up","consequence":"A fake plan just adds pressure to keep up the act."}],"debrief":"Their anxious question isn't your verdict; 'I'm exploring' is a fine reply.","relearn":"Answer 'I'm exploring' honestly and let the pressure question go.","persona":"Aarti","source":"the relatives' question"},
  {"id":"ff-1107","cat":"not-all-sorted","type":"branch","hook":"Two paths interest you and you can't yet tell which fits better.","options":[{"text":"Try a small taste — a course or a chat with an insider","consequence":"You gather real information instead of guessing.","outcome":"informed","best":true},{"text":"Freeze until you're totally sure which is right","consequence":"Waiting for total certainty keeps you stuck guessing."}],"debrief":"You learn fit by sampling, not by thinking harder; a small real step beats endless deliberation.","relearn":"Try a small taste of a path to learn its fit, rather than freezing for certainty.","persona":"any","source":"a small taste"},
  {"id":"ff-1108","cat":"not-all-sorted","type":"branch","hook":"At 2am the 'I have no idea what I'm doing with my life' spiral hits hard.","options":[{"text":"Pause the decision, sleep, look at it steady tomorrow","consequence":"You avoid choosing from a panicked, tired state.","outcome":"steadied","best":true},{"text":"Make a big life decision right now to stop the panic","consequence":"A 2am panic is the worst state to choose a future from."}],"debrief":"Don't make a big call from a raw, spiralling state; steady first, decide later.","relearn":"Don't decide your future from a 2am panic; steady first, then choose.","persona":"any","source":"the 2am spiral"},
  {"id":"ff-1109","cat":"not-all-sorted","type":"branch","hook":"You feel pressure to lock a 10-year goal this week.","options":[{"text":"Set a flexible direction plus one concrete next step","consequence":"You get momentum without faking certainty.","outcome":"moving","best":true},{"text":"Force a rigid 10-year plan you don't believe","consequence":"A rigid plan you don't believe just cracks later."}],"debrief":"A direction you can revise plus one next step beats a rigid plan you don't trust.","relearn":"Set a flexible direction and one next step, not a forced rigid 10-year plan.","persona":"any","source":"flexible direction"},
  {"id":"ff-1110","cat":"not-all-sorted","type":"branch","hook":"A friend seems totally certain about their future, and it's making you doubt yourself.","options":[{"text":"Get curious about their path without measuring yourself by it","consequence":"You learn something and keep your footing.","outcome":"curious","best":true},{"text":"Decide you're behind and panic-copy their plan","consequence":"A copied plan rarely fits your own life."}],"debrief":"Their certainty is information about them, not a verdict on you; learn, don't measure.","relearn":"Be curious about a confident friend's path without measuring your worth by it.","persona":"any","source":"the certain friend"},
  {"id":"ff-1111","cat":"not-all-sorted","type":"branch","hook":"You skipped an opportunity because you 'don't have it all figured out first'.","options":[{"text":"Apply anyway — clarity often comes from doing","consequence":"You let action teach you, not waiting to feel ready.","outcome":"acting","best":true},{"text":"Wait until you feel fully sorted to try anything","consequence":"Waiting to feel fully sorted usually means never starting."}],"debrief":"You don't need clarity to begin; beginning is often what creates the clarity.","relearn":"Clarity often comes from doing; begin without being fully sorted.","persona":"Meena","source":"clarity from doing"},
  {"id":"ff-1112","cat":"not-all-sorted","type":"branch","hook":"You catch yourself thinking 'everyone my age is ahead of me'.","options":[{"text":"Question it — you're seeing highlights, not the full field","consequence":"You loosen a false 'everyone' that was never true.","outcome":"loosened","best":true},{"text":"Accept it as fact and feel hopeless about catching up","consequence":"Taking it as fact feeds a hopelessness you haven't earned."}],"debrief":"'Everyone is ahead' is an illusion built from edited surfaces; it's almost never literally true.","relearn":"Question 'everyone's ahead of me'; you're seeing highlights, not the full field.","persona":"any","source":"the false everyone"},
  {"id":"ff-1113","cat":"not-all-sorted","type":"branch","hook":"A campus counsellor slot is free, but you feel you should 'sort it yourself' first.","options":[{"text":"Book it — talking it through helps untangle uncertainty","consequence":"You borrow a clearer head to find your direction.","outcome":"supported","best":true},{"text":"Struggle alone until you've figured it all out","consequence":"Struggling alone just keeps the knot tight."}],"debrief":"Using a mentor or counsellor to think aloud is resourceful, not weak; you needn't solve it solo.","relearn":"Talking uncertainty through with a counsellor is smart, not a failure.","persona":"Rohan","source":"use the counsellor"},
  {"id":"ff-1114","cat":"not-all-sorted","type":"branch","hook":"You feel you must commit to one field this very semester.","options":[{"text":"Keep exploring a bit longer, sampling options deliberately","consequence":"You choose from knowledge instead of panic.","outcome":"exploring","best":true},{"text":"Slam every door but one, just to feel decided","consequence":"Closing every door early often locks in a poor fit."}],"debrief":"Committing early to escape discomfort isn't the same as a good choice; a little more exploring is fine.","relearn":"Keep exploring deliberately rather than committing early just to feel decided.","persona":"any","source":"premature commitment"},
  {"id":"ff-1115","cat":"not-all-sorted","type":"branch","hook":"You're frozen, refreshing job sites for hours without applying anywhere.","options":[{"text":"Pick one realistic thing and do it today, then stop","consequence":"You break the freeze with one finished action.","outcome":"unfrozen","best":true},{"text":"Keep scrolling until the 'perfect' option appears","consequence":"Waiting for a perfect option keeps you scrolling forever."}],"debrief":"Action, not more scrolling, melts the freeze; one small completed step is the way out.","relearn":"Break the freeze with one realistic action today, not waiting for the perfect option.","persona":"Deepak","source":"breaking the freeze"},
  {"id":"ff-1116","cat":"not-all-sorted","type":"branch","hook":"You assume you must have life sorted before you're 'allowed' to enjoy college.","options":[{"text":"Enjoy the present while figuring things out gradually","consequence":"You stop putting your life on hold for a plan.","outcome":"present","best":true},{"text":"Refuse to enjoy anything till the future is settled","consequence":"Postponing all joy till it's settled wastes the years you're in."}],"debrief":"You don't have to earn the present by first finishing the future; both can happen at once.","relearn":"Enjoy the present while figuring things out gradually; don't put life on hold.","persona":"Zoya","source":"not on hold"},
  {"id":"ff-1117","cat":"not-all-sorted","type":"role-play","hook":"A relative at a function asks, 'Beta, when will you finally settle into something?'","relearn":"You can name your stage warmly without defending a finished plan you don't have.","persona":"Aarti","source":"the function question","setup":"Reply warmly but honestly. Say:","yourLine":[{"text":"\"I'm exploring a few things right now, and I'm okay taking my time.\"","best":true},{"text":"Mumble a fake plan and feel small"}]},
  {"id":"ff-1118","cat":"not-all-sorted","type":"role-play","hook":"A batchmate brags about their locked-in five-year plan and waits for yours.","relearn":"Owning that you're still figuring it out is a confident answer, not a weak one.","persona":"any","source":"the brag","setup":"Hold your ground kindly. Say:","yourLine":[{"text":"\"That's great for you — I'm still figuring mine out, and that's fine.\"","best":true},{"text":"Pretend you have an identical plan"}]},
  {"id":"ff-1119","cat":"not-all-sorted","type":"role-play","hook":"A worried parent asks on call why you 'still don't know' what you'll do.","relearn":"You can reassure a worried parent honestly without promising false certainty.","persona":"any","source":"the parent call","setup":"Reassure without faking it. Say:","yourLine":[{"text":"\"I'm taking real steps to work it out — I just don't have the final answer yet.\"","best":true},{"text":"Promise a plan you've already abandoned"}]},
  {"id":"ff-1120","cat":"not-all-sorted","type":"role-play","hook":"A friend panics that they have no plan and asks if they're a failure for it.","relearn":"Normalising a friend's uncertainty helps more than feeding their panic.","persona":"any","source":"reassuring a friend","setup":"Steady your friend. Say:","yourLine":[{"text":"\"Not having it all sorted now is normal — honestly, almost no one does.\"","best":true},{"text":"Agree that they're hopelessly behind"}]},
  {"id":"ff-1121","cat":"not-all-sorted","type":"role-play","hook":"Your inner voice sneers, 'Everyone's sorted but you — you're the only mess.'","relearn":"You can answer the harsh inner voice with the steadier truth.","persona":"any","source":"the inner voice","setup":"Answer that voice. Say:","yourLine":[{"text":"\"That's not true — most people are figuring it out too, behind the confident face.\"","best":true},{"text":"Believe it and spiral"}]},
  {"id":"ff-1122","cat":"not-all-sorted","type":"role-play","hook":"A senior asks where you see yourself in ten years and you genuinely don't know.","relearn":"'I don't know yet' said plainly is an honest, acceptable answer to a big question.","persona":"any","source":"ten years out","setup":"Answer honestly. Say:","yourLine":[{"text":"\"Honestly, I don't know yet — I'm exploring before I commit to one direction.\"","best":true},{"text":"Bluff a polished ten-year vision"}]},
  {"id":"ff-1123","cat":"not-all-sorted","type":"role-play","hook":"You're about to skip an internship fair because you 'haven't decided your field'.","relearn":"You can give yourself permission to explore before you've decided.","persona":"Meena","source":"permission to explore","setup":"Coach yourself there. Say:","yourLine":[{"text":"\"I'll go and explore — I don't need a decided field to start looking around.\"","best":true},{"text":"Stay home until you're certain"}]},
  {"id":"ff-1124","cat":"not-all-sorted","type":"match","hook":"Match each uncertainty fear to the steadier truth that answers it.","relearn":"Each anxious 'I should already know' has a calmer, truer reply.","persona":"any","source":"fear to truth","pairs":[{"left":"\"I should have it all planned\"","right":"Small steps beat a master plan"},{"left":"\"A gap year ruins everything\"","right":"One year rarely changes a long career"},{"left":"\"Switching means I chose wrong\"","right":"Adjusting is learning a fit, used well"},{"left":"\"Everyone else is certain\"","right":"Most improvise behind a confident face"},{"left":"\"I'll never figure it out\"","right":"That's fear talking, not a forecast"}]},
  {"id":"ff-1125","cat":"not-all-sorted","type":"match","hook":"Match the healthy move under uncertainty to the stuck habit it replaces.","relearn":"Sampling, asking and small steps beat freezing, bluffing and panic-deciding.","persona":"any","source":"healthy vs stuck","pairs":[{"left":"Try a small taste of a path","right":"Freeze until you're totally sure"},{"left":"Ask a mentor to think aloud","right":"Struggle alone in silence"},{"left":"Set a flexible direction","right":"Force a rigid plan you doubt"},{"left":"Decide steady, after sleep","right":"Choose from a 2am panic"},{"left":"Take one next step today","right":"Scroll endlessly without acting"}]},
  {"id":"ff-1126","cat":"not-all-sorted","type":"match","hook":"Match each gentle truth about uncertainty to who it reassures.","relearn":"There's a steadying line for the late starter, the switcher, the explorer and the lost.","persona":"any","source":"truth to person","pairs":[{"left":"You're early, not late","right":"The one who feels behind"},{"left":"Changing course is learning","right":"The one who switched streams"},{"left":"Curiosity is a fine compass","right":"The one with no fixed plan"},{"left":"Feeling lost means between","right":"The one who feels lost"},{"left":"One step is enough today","right":"The one frozen by the whole map"}]},
  {"id":"ff-1127","cat":"not-all-sorted","type":"match","hook":"Match the unhelpful pressure line to the kinder reframe of it.","relearn":"Every harsh pressure line about being sorted has a kinder, truer version.","persona":"any","source":"pressure reframed","pairs":[{"left":"\"You must know by now\"","right":"There's no deadline to lock a direction"},{"left":"\"No dream means lost\"","right":"Growing interests count as much as a dream"},{"left":"\"Undecided means lazy\"","right":"Honest uncertainty is taking it seriously"},{"left":"\"Enjoy life once it's settled\"","right":"You can enjoy the present meanwhile"},{"left":"\"Your degree is wasted\"","right":"Skills travel into any field"}]},
  {"id":"ff-1128","cat":"not-all-sorted","type":"match","hook":"Match each next-step tool to the uncertainty moment it fits.","relearn":"Different stuck moments call for a small taste, a pause, a mentor or one step.","persona":"any","source":"tool to moment","pairs":[{"left":"Try a small taste","right":"Two paths, can't tell which fits"},{"left":"Pause and sleep on it","right":"A 2am spiral pushing a big call"},{"left":"Ask a mentor aloud","right":"Knot you can't untangle alone"},{"left":"Pick one next step","right":"Frozen, scrolling, doing nothing"},{"left":"Name your stage honestly","right":"Relatives pressing for a final plan"}]},
  {"id":"ff-1129","cat":"not-all-sorted","type":"match","hook":"Match the myth about timelines to the truth that loosens it.","relearn":"Each rigid timeline myth has a roomier truth behind it.","persona":"any","source":"timeline myths","pairs":[{"left":"\"Plan must be locked at 22\"","right":"Most are still figuring it out past 22"},{"left":"\"First job sets everything\"","right":"It's a starting point, not a sentence"},{"left":"\"One perfect path or regret\"","right":"Several good paths exist; adjust as you go"},{"left":"\"I'm running out of time\"","right":"You have decades; you're early"},{"left":"\"Successful people mapped it\"","right":"Most careers were full of swerves"}]},
  {"id":"ff-1130","cat":"not-all-sorted","type":"match","hook":"Match each worry to the small, doable action that answers it best.","relearn":"A vague worry shrinks when paired with one concrete, doable action.","persona":"any","source":"worry to action","pairs":[{"left":"\"I don't know any fields\"","right":"Chat with one person doing work you wonder about"},{"left":"\"I might choose wrong\"","right":"Take a short course as a low-stakes taste"},{"left":"\"I feel paralysed\"","right":"Write one next step and do only that"},{"left":"\"No one to ask\"","right":"Book a free campus counsellor slot"},{"left":"\"Everyone's ahead\"","right":"Step back from the comparison feed"}]},
  {"id":"ff-1131","cat":"not-all-sorted","type":"match","hook":"Match the confident-sounding claim to what's usually hidden behind it.","relearn":"Behind most 'I'm totally sorted' claims sits the same quiet uncertainty.","persona":"any","source":"behind the claim","pairs":[{"left":"\"I've got a five-year plan\"","right":"Half-bluff, revised every few months"},{"left":"\"I always knew my field\"","right":"A clean story told backwards"},{"left":"\"I'm not worried at all\"","right":"The same doubts, better hidden"},{"left":"\"It all fell into place\"","right":"Plenty of swerves left out of the telling"},{"left":"\"I never had doubts\"","right":"Doubts everyone has, just unspoken"}]},
  {"id":"ff-1132","cat":"not-all-sorted","type":"match","hook":"Match each 'should' about being sorted to the permission that frees you.","relearn":"Every harsh 'should' about your future has a gentler permission.","persona":"any","source":"should to permission","pairs":[{"left":"\"I should have a dream\"","right":"You're allowed to follow curiosity instead"},{"left":"\"I should be certain\"","right":"You're allowed to hold it loosely"},{"left":"\"I should rest only once sorted\"","right":"You're allowed to breathe meanwhile"},{"left":"\"I should match their pace\"","right":"You're allowed your own timeline"},{"left":"\"I should never change my mind\"","right":"You're allowed to update as you learn"}]},
  {"id":"ff-1133","cat":"not-all-sorted","type":"match","hook":"Match the panic thought to the calmer question that defuses it.","relearn":"A spiralling thought loses power when met with a calmer, honest question.","persona":"any","source":"thought to question","pairs":[{"left":"\"Everyone's ahead of me\"","right":"Ahead of what shared race, exactly?"},{"left":"\"I've wasted years\"","right":"What did those years actually teach me?"},{"left":"\"I must decide tonight\"","right":"Does this really have to be settled now?"},{"left":"\"I'm the only lost one\"","right":"Who around me is also just figuring it out?"},{"left":"\"There's no point starting\"","right":"What's one small step I could take anyway?"}]},
  {"id":"ff-1134","cat":"not-all-sorted","type":"match","hook":"Match each life stage to the truth that says uncertainty there is normal.","relearn":"Uncertainty looks different at each stage, and is normal at every one.","persona":"any","source":"stage to truth","pairs":[{"left":"Just started college","right":"You're meant to be exploring, not decided"},{"left":"Mid-degree doubt","right":"Rethinking a fit here is common, not failure"},{"left":"Final year, no clear job","right":"Many find direction after graduating, not before"},{"left":"First job, unsure","right":"It's a starting point you can pivot from"},{"left":"Considering a switch","right":"Pivots are a normal, legitimate route"}]},
  {"id":"ff-1135","cat":"not-all-sorted","type":"sort","hook":"Sort each thought: steadying truth, or false pressure?","items":[{"id":"a","text":"\"Small steps beat a master plan\""},{"id":"b","text":"\"I must have it all sorted now\""},{"id":"c","text":"\"Exploring is part of the process\""},{"id":"d","text":"\"Everyone else is already certain\""},{"id":"e","text":"\"Not knowing yet is workable\""},{"id":"f","text":"\"I'm failing against a timeline\""}],"bins":[{"id":"truth","label":"Steadying truth","valence":"pos"},{"id":"pressure","label":"False pressure","valence":"neg"}],"key":{"a":"truth","b":"pressure","c":"truth","d":"pressure","e":"truth","f":"pressure"},"relearn":"Small steps, exploring and 'not knowing is workable' are steadying truths; 'sorted now' and 'failing a timeline' are false pressure.","persona":"any","source":"truth vs pressure"},
  {"id":"ff-1136","cat":"not-all-sorted","type":"sort","hook":"Sort each response to feeling lost: healthy move, or stuck habit?","items":[{"id":"a","text":"Try a small taste of an option"},{"id":"b","text":"Freeze until you're fully certain"},{"id":"c","text":"Ask a mentor to think it through"},{"id":"d","text":"Panic-decide at 2am"},{"id":"e","text":"Take one concrete next step"},{"id":"f","text":"Fake a confident master plan"}],"bins":[{"id":"healthy","label":"Healthy move","valence":"pos"},{"id":"stuck","label":"Stuck habit","valence":"neg"}],"key":{"a":"healthy","b":"stuck","c":"healthy","d":"stuck","e":"healthy","f":"stuck"},"relearn":"Tasting options, asking a mentor and one next step are healthy; freezing, 2am panic-deciding and faking a plan keep you stuck.","persona":"any","source":"healthy vs stuck moves"},
  {"id":"ff-1137","cat":"not-all-sorted","type":"sort","hook":"Sort each statement: an honest answer, or a forced fake?","items":[{"id":"a","text":"\"I'm still exploring a few things\""},{"id":"b","text":"\"I've got it all mapped, definitely\""},{"id":"c","text":"\"I don't know yet, and that's okay\""},{"id":"d","text":"\"Everything's sorted, no doubts\""},{"id":"e","text":"\"I'm taking real steps to work it out\""},{"id":"f","text":"\"Final five-year plan, locked\""}],"bins":[{"id":"honest","label":"Honest answer","valence":"pos"},{"id":"fake","label":"Forced fake","valence":"neg"}],"key":{"a":"honest","b":"fake","c":"honest","d":"fake","e":"honest","f":"fake"},"relearn":"'Still exploring', 'don't know yet' and 'taking real steps' are honest; an all-mapped, no-doubts, locked plan is usually a forced fake.","persona":"any","source":"honest vs fake"},
  {"id":"ff-1138","cat":"not-all-sorted","type":"sort","hook":"Sort each move when two paths tempt you: gathers real info, or just guesses?","items":[{"id":"a","text":"Do a short internship in one"},{"id":"b","text":"Argue it endlessly in your head"},{"id":"c","text":"Talk to someone working in it"},{"id":"d","text":"Assume the worst about each"},{"id":"e","text":"Take a trial course"},{"id":"f","text":"Decide by what looks impressive"}],"bins":[{"id":"info","label":"Real information","valence":"pos"},{"id":"guess","label":"Just guessing","valence":"neg"}],"key":{"a":"info","b":"guess","c":"info","d":"guess","e":"info","f":"guess"},"relearn":"An internship, a chat with an insider and a trial course gather real info; head-arguing, worst-assuming and chasing impressive are just guessing.","persona":"any","source":"info vs guess"},
  {"id":"ff-1139","cat":"not-all-sorted","type":"sort","hook":"Sort each line: loosens the 'sorted now' pressure, or tightens it?","items":[{"id":"a","text":"\"You're early, not late\""},{"id":"b","text":"\"You're running out of time\""},{"id":"c","text":"\"You can hold a plan loosely\""},{"id":"d","text":"\"One wrong move and it's over\""},{"id":"e","text":"\"Changing your mind is growth\""},{"id":"f","text":"\"Everyone passed you already\""}],"bins":[{"id":"loosens","label":"Loosens it","valence":"pos"},{"id":"tightens","label":"Tightens it","valence":"neg"}],"key":{"a":"loosens","b":"tightens","c":"loosens","d":"tightens","e":"loosens","f":"tightens"},"relearn":"'You're early', 'hold it loosely' and 'changing is growth' loosen the pressure; 'running out of time', 'one wrong move' and 'everyone passed you' tighten it.","persona":"any","source":"loosens vs tightens"},
  {"id":"ff-1140","cat":"not-all-sorted","type":"sort","hook":"Sort each source of direction: reliable guidance, or noise to ignore?","items":[{"id":"a","text":"A mentor doing the actual work"},{"id":"b","text":"A viral 'get rich by 25' reel"},{"id":"c","text":"A campus careers service"},{"id":"d","text":"A 3am anxiety spiral's verdict"},{"id":"e","text":"Someone a few years into the field"},{"id":"f","text":"Strangers' comparison comments online"}],"bins":[{"id":"reliable","label":"Reliable guidance","valence":"pos"},{"id":"noise","label":"Noise to ignore","valence":"neg"}],"key":{"a":"reliable","b":"noise","c":"reliable","d":"noise","e":"reliable","f":"noise"},"relearn":"Mentors, a careers service and people in the field are reliable; viral reels, 3am spirals and strangers' comparison comments are noise.","persona":"any","source":"guidance vs noise"},
  {"id":"ff-1141","cat":"not-all-sorted","type":"sort","hook":"Sort each timeline belief: roomy and true, or rigid and false?","items":[{"id":"a","text":"\"Many find direction after graduating\""},{"id":"b","text":"\"A plan must be locked by 22\""},{"id":"c","text":"\"Pivots are a normal route\""},{"id":"d","text":"\"My first job decides my whole life\""},{"id":"e","text":"\"There's no fixed clock I'm failing\""},{"id":"f","text":"\"A gap year ruins my future\""}],"bins":[{"id":"true","label":"Roomy and true","valence":"pos"},{"id":"false","label":"Rigid and false","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"'Direction comes later', 'pivots are normal' and 'no fixed clock' are roomy truths; 'locked by 22' and 'first job decides all' are rigid and false.","persona":"any","source":"roomy vs rigid"},
  {"id":"ff-1142","cat":"not-all-sorted","type":"sort","hook":"Sort each thing to do with a panicked, uncertain feeling: steady it, or feed it?","items":[{"id":"a","text":"Sleep, then decide tomorrow"},{"id":"b","text":"Doom-scroll others' wins"},{"id":"c","text":"Take a slow breath and pause"},{"id":"d","text":"Make a huge call mid-panic"},{"id":"e","text":"Talk to someone you trust"},{"id":"f","text":"Replay 'I'm hopelessly behind'"}],"bins":[{"id":"steady","label":"Steadies it","valence":"pos"},{"id":"feed","label":"Feeds it","valence":"neg"}],"key":{"a":"steady","b":"feed","c":"steady","d":"feed","e":"steady","f":"feed"},"relearn":"Sleeping on it, a slow breath and talking to someone steady the panic; doom-scrolling, mid-panic decisions and replaying 'I'm behind' feed it.","persona":"any","source":"steady vs feed"},
  {"id":"ff-1143","cat":"not-all-sorted","type":"spot","hook":"Spot the two lines piling on false 'should be sorted' pressure (the red flags).","relearn":"'Too far behind' and 'one decision sets everything' are false pressure; the rest are true.","persona":"any","source":"catch the pressure","scene":[{"id":"a","text":"\"You're too far behind to catch up\"","trick":true},{"id":"b","text":"\"Small steps count more than a master plan\"","trick":false},{"id":"c","text":"\"This one decision sets your whole life\"","trick":true},{"id":"d","text":"\"No one really has it figured out\"","trick":false},{"id":"e","text":"\"Exploring is a normal part of it\"","trick":false}],"why":"'Too far behind' and 'this decision sets your whole life' are the false-pressure flags."},
  {"id":"ff-1144","cat":"not-all-sorted","type":"spot","hook":"Spot the two unhealthy responses to uncertainty among the healthy ones (the red flags).","relearn":"Freezing for certainty and panic-deciding at 2am are the red flags; the rest are healthy.","persona":"any","source":"catch the stuck move","scene":[{"id":"a","text":"Try a small taste of one option","trick":false},{"id":"b","text":"Freeze until you're totally certain","trick":true},{"id":"c","text":"Ask a mentor to think it through","trick":false},{"id":"d","text":"Make the big call at 2am to stop the panic","trick":true},{"id":"e","text":"Take one concrete next step today","trick":false}],"why":"Freezing for total certainty and deciding from a 2am panic are the unhealthy flags."},
  {"id":"ff-1145","cat":"not-all-sorted","type":"spot","hook":"Spot the two lines tying your worth or future to being sorted (the red flags).","relearn":"'Something's wrong with you' and 'your future is decided badly' are the false verdicts.","persona":"any","source":"catch the false verdict","scene":[{"id":"a","text":"\"Not knowing yet means something's wrong with you\"","trick":true},{"id":"b","text":"\"Curiosity is a fine compass for now\"","trick":false},{"id":"c","text":"\"You've more time than the panic suggests\"","trick":false},{"id":"d","text":"\"Undecided now means your future is decided badly\"","trick":true},{"id":"e","text":"\"Changing your mind is growth\"","trick":false}],"why":"'Something's wrong' and 'your future is decided badly' are the false verdicts."},
  {"id":"ff-1146","cat":"not-all-sorted","type":"spot","hook":"Spot the two replies to a panicking friend that make it worse (the red flags).","relearn":"'Hopelessly behind' and 'too late for you' are the harmful flags; the rest steady a friend.","persona":"any","source":"catch the harmful reply","scene":[{"id":"a","text":"\"Almost no one has it sorted at our age\"","trick":false},{"id":"b","text":"\"Yeah, you're hopelessly behind everyone\"","trick":true},{"id":"c","text":"\"One small step is a fine place to start\"","trick":false},{"id":"d","text":"\"It's basically too late for you now\"","trick":true},{"id":"e","text":"\"Want to think it through together?\"","trick":false}],"why":"'Hopelessly behind' and 'too late for you now' make the panic worse."},
  {"id":"ff-1147","cat":"not-all-sorted","type":"spot","hook":"Spot the two 'sources of direction' that are really just noise (the red flags).","relearn":"A viral 'rich by 25' reel and a 3am spiral are noise flags; mentors and insiders guide you.","persona":"any","source":"catch the noise","scene":[{"id":"a","text":"A mentor actually doing the work","trick":false},{"id":"b","text":"A viral 'get rich by 25' reel","trick":true},{"id":"c","text":"The campus careers service","trick":false},{"id":"d","text":"A 3am anxiety spiral's verdict on you","trick":true},{"id":"e","text":"Someone a few years into the field","trick":false}],"why":"The viral 'rich by 25' reel and the 3am spiral are noise to ignore."},
  {"id":"ff-1148","cat":"not-all-sorted","type":"spot","hook":"Spot the two timeline beliefs that are rigid and false (the red flags).","relearn":"'Locked by 22' and 'first job decides all' are the false flags; the rest are roomy truths.","persona":"any","source":"catch the rigid belief","scene":[{"id":"a","text":"\"Many find their direction after graduating\"","trick":false},{"id":"b","text":"\"Your plan must be fully locked by 22\"","trick":true},{"id":"c","text":"\"Pivots and second attempts are normal\"","trick":false},{"id":"d","text":"\"Your first job decides your entire life\"","trick":true},{"id":"e","text":"\"There's no fixed clock you're failing\"","trick":false}],"why":"'Locked by 22' and 'first job decides your entire life' are rigid and false."},
  {"id":"ff-1149","cat":"not-all-sorted","type":"spot","hook":"Spot the two ways of handling a 2am spiral that backfire (the red flags).","relearn":"Deciding mid-panic and doom-scrolling wins are the backfiring flags; the rest steady you.","persona":"any","source":"catch the backfire","scene":[{"id":"a","text":"Sleep and look at it steady tomorrow","trick":false},{"id":"b","text":"Lock a huge life decision right now","trick":true},{"id":"c","text":"Take a few slow breaths and pause","trick":false},{"id":"d","text":"Doom-scroll everyone else's wins","trick":true},{"id":"e","text":"Message someone you trust in the morning","trick":false}],"why":"Deciding a whole future mid-panic and doom-scrolling others' wins backfire."},
  {"id":"ff-1150","cat":"not-all-sorted","type":"spot","hook":"Spot the two 'confident' claims that are usually a bluff (the red flags).","relearn":"'Totally mapped, no doubts' and 'always knew, never wavered' are the bluff flags to catch.","persona":"any","source":"catch the bluff","scene":[{"id":"a","text":"\"I'm still figuring my direction out, honestly\"","trick":false},{"id":"b","text":"\"I've got ten years totally mapped, no doubts\"","trick":true},{"id":"c","text":"\"I'm taking real steps, but not fully sure yet\"","trick":false},{"id":"d","text":"\"I always knew exactly, never wavered once\"","trick":true},{"id":"e","text":"\"Some of it's clear, a lot still isn't\"","trick":false}],"why":"'Totally mapped, no doubts' and 'always knew, never wavered' are bluffs."},
  {"id":"ff-1170","cat":"tools-and-help","type":"match","hook":"Match each wobble to the tool that meets it.","persona":"any","source":"toolkit map","relearn":"Stuck wants a next step, a spike wants breathing space, big choices want a mentor, heaviness wants a helpline.","pairs":[{"left":"Stuck and spiralling","right":"The 'next step' tool"},{"left":"Anxiety spiking right now","right":"A breathing space"},{"left":"A big decision looming","right":"A mentor's view"},{"left":"Heavy, constant distress","right":"Tele-MANAS 14416"},{"left":"Need real direction","right":"A careers service"}]},
  {"id":"ff-1171","cat":"tools-and-help","type":"sort","hook":"Sort: healthy coping with career stress, or just dodging it?","persona":"any","source":"cope vs dodge","relearn":"Next steps, a mentor and a breather are coping; doomscrolling, all-nighters and bottling it are dodging.","items":[{"id":"a","text":"Breaking it into one next step"},{"id":"b","text":"Doomscrolling success reels"},{"id":"c","text":"Asking a mentor what they'd do"},{"id":"d","text":"Pulling anxious all-nighters"},{"id":"e","text":"Taking a real breathing space"},{"id":"f","text":"Bottling it up alone"}],"bins":[{"id":"cope","label":"Healthy coping","valence":"pos"},{"id":"dodge","label":"Just dodging","valence":"neg"}],"key":{"a":"cope","b":"dodge","c":"cope","d":"dodge","e":"cope","f":"dodge"}},
  {"id":"ff-1172","cat":"tools-and-help","type":"branch","hook":"You're frozen at your desk, mind racing about your whole future at once.","persona":"any","source":"shrink the problem","options":[{"text":"Shrink it to the one next step you can take today","consequence":"The panic loosens and you move.","outcome":"unstuck","best":true},{"text":"Try to solve your entire future tonight","consequence":"You can't solve a whole life in one night; shrinking it to today's one step is what unsticks you."}],"debrief":"The next-step tool shrinks an unsolvable 'whole future' into one doable thing now.","relearn":"When the future overwhelms you, shrink it to the one step you can take today."},
  {"id":"ff-1173","cat":"tools-and-help","type":"reflect","hook":"Lensy: reaching out for help isn't a last resort — it's how steady people navigate hard stretches. Land?","persona":"Rohan","source":"reaching out is normal","relearn":"Reaching out is a normal, smart way people navigate hard stretches, not a sign you've failed.","prompt":"What do you think?","options":["Yes","It's normal","Smart, not weak"],"affirm":"Reaching out shares the load; the people who do it aren't weaker — they're the ones who keep going."},
  {"id":"ff-1174","cat":"tools-and-help","type":"spot","hook":"Spot the two voices that will make tonight's anxiety worse, not better.","persona":"any","source":"who to trust at 3am","relearn":"A mentor and a real breather steady you; '3am you' and a 'get rich quick' reel just deepen the spiral.","scene":[{"id":"a","text":"A mentor who's done the work","trick":false},{"id":"b","text":"Your catastrophising 3am brain","trick":true},{"id":"c","text":"A slow breathing space","trick":false},{"id":"d","text":"A viral 'get rich quick' reel","trick":true},{"id":"e","text":"A trusted friend who listens","trick":false}],"why":"Your 3am brain and a hype reel aren't reliable guides; a mentor, a breather and a friend are."},
  {"id":"ff-1175","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If I just push through alone, I'll prove I'm strong.\"","persona":"any","source":"strength myth","relearn":"Strength isn't carrying heavy distress alone; reaching for support is the stronger, smarter move.","myth":{"un":"Pushing through heavy distress alone proves I'm strong.","re":"Strength is knowing when to reach out; carrying constant distress alone wears you down, not up.","why":"Support shares the load so you can keep going."}},
  {"id":"ff-1176","cat":"tools-and-help","type":"match","hook":"Match the need to where help actually lives (India).","persona":"any","source":"help routes","relearn":"Heavy distress goes to Tele-MANAS; danger, to 112; direction, to a mentor or careers service; a spike, to a breather.","pairs":[{"left":"Heavy distress, day or night","right":"Tele-MANAS 14416"},{"left":"Someone in danger right now","right":"Emergency 112"},{"left":"Which field actually fits","right":"A mentor or careers service"},{"left":"A panic spike right now","right":"A breathing space"},{"left":"Just need to be heard","right":"A trusted person"}]},
  {"id":"ff-1177","cat":"tools-and-help","type":"sort","hook":"Sort: reliable career guidance, or noise dressed up as advice?","persona":"any","source":"signal vs noise","relearn":"Mentors, a careers service and people doing the work are reliable; viral reels, hype gurus and rumours are noise.","items":[{"id":"a","text":"A mentor in the field"},{"id":"b","text":"A viral 'six-figure by 22' reel"},{"id":"c","text":"The campus careers service"},{"id":"d","text":"An anonymous hype 'guru'"},{"id":"e","text":"Someone actually doing the job"},{"id":"f","text":"Hostel-corridor rumours"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"noise","label":"Noise","valence":"neg"}],"key":{"a":"reliable","b":"noise","c":"reliable","d":"noise","e":"reliable","f":"noise"}},
  {"id":"ff-1178","cat":"tools-and-help","type":"branch","hook":"The dread has stopped being 'exam nerves' — it's heavy and constant now.","persona":"Mehta","source":"heavy distress routing","options":[{"text":"Reach a counsellor or Tele-MANAS 14416 for the weight underneath","consequence":"The distress gets met with real support, gently.","outcome":"supported","best":true},{"text":"Tell yourself it's nothing and keep going","consequence":"Heavy, constant dread is worth real support, not minimising."}],"debrief":"Constant, heavy distress isn't weakness to push past; it's a signal to reach for support.","relearn":"Heavy, constant dread is a signal to reach for support, not push through."},
  {"id":"ff-1179","cat":"tools-and-help","type":"role-play","hook":"A friend keeps saying 'just think positive' when you're clearly drowning in it.","persona":"any","source":"ask for what helps","relearn":"You can name what actually helps — being heard and pointed to real support — instead of toxic positivity.","setup":"Tell them what you need. Say:","yourLine":[{"text":"\"I don't need 'stay positive' — I need you to listen, and maybe help me find real support.\"","best":true},{"text":"Nod along and bottle it back up"}]},
  {"id":"ff-1180","cat":"tools-and-help","type":"reflect","hook":"Lensy: a 60-second breathing space won't fix your career — but it stops a spike running the show. Worth a try?","persona":"any","source":"the breather","relearn":"A breathing space steadies the spike so you can think; it buys clarity, it isn't the whole answer.","prompt":"What do you think?","options":["Yes","Steady first","Then think"],"affirm":"Steady the spike first, then choose: a calm minute makes the next step clearer than a panicked hour."},
  {"id":"ff-1181","cat":"tools-and-help","type":"match","hook":"Match the long-term habit to what it quietly does for future-anxiety.","persona":"any","source":"long-term habits","relearn":"Small regular steps keep anxiety workable, self-check-ins catch spirals early, and staying connected shares the load.","pairs":[{"left":"Regular small steps","right":"Keeps anxiety workable"},{"left":"A weekly self-check-in","right":"Catches spirals early"},{"left":"Staying connected","right":"Shares the load"},{"left":"A wind-down before sleep","right":"Quiets the 3am loop"},{"left":"One mentor you can text","right":"A reality check on call"}]},
  {"id":"ff-1182","cat":"tools-and-help","type":"sort","hook":"Sort: a message that genuinely helps, or one that just deepens the dread?","persona":"any","source":"helpful vs harmful messages","relearn":"'No one has it sorted' and 'small steps count' help; 'too far behind' and 'it's too late for you' only deepen dread.","items":[{"id":"a","text":"\"No one has it figured out\""},{"id":"b","text":"\"You're already too far behind\""},{"id":"c","text":"\"Small steps count\""},{"id":"d","text":"\"It's too late for you now\""},{"id":"e","text":"\"You don't have to do this alone\""},{"id":"f","text":"\"Everyone's lapped you\""}],"bins":[{"id":"helps","label":"Genuinely helps","valence":"pos"},{"id":"deepens","label":"Deepens the dread","valence":"neg"}],"key":{"a":"helps","b":"deepens","c":"helps","d":"deepens","e":"helps","f":"deepens"}},
  {"id":"ff-1183","cat":"tools-and-help","type":"branch","hook":"You want guidance but feel awkward asking a senior you barely know for ten minutes.","persona":"Deepak","source":"asking a mentor","options":[{"text":"Send a short, specific ask for ten minutes of their time","consequence":"Most people say yes to a clear, small request.","outcome":"connected","best":true},{"text":"Decide they'd never bother and stay stuck","consequence":"A clear, small ask is easy to say yes to; assuming a no keeps an open door shut."}],"debrief":"You don't need a network — a clear, small ask is how most mentor doors open.","relearn":"A short, specific ask opens most mentor doors, even with no network."},
  {"id":"ff-1184","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Helplines are only for people in a real crisis, not stressed students like me.\"","persona":"any","source":"who helplines are for","relearn":"Tele-MANAS is for anyone whose distress feels heavy — you don't have to be at rock bottom to call.","myth":{"un":"Helplines are only for 'real' crises, not ordinary stress.","re":"Tele-MANAS 14416 is for anyone carrying heavy distress; you don't have to hit rock bottom to reach out.","why":"Support early beats waiting until it's unbearable."}},
  {"id":"ff-1185","cat":"tools-and-help","type":"reflect","hook":"Lensy: name one tiny step you could take this week toward your future. Just one.","persona":"any","source":"one small step","relearn":"One small, concrete step this week beats a perfect plan you never start; momentum comes from starting.","prompt":"What's your one step?","options":["Message a mentor","Try one new thing","Update my CV","Just rest first"],"affirm":"That's a real step. You don't need the whole map — one thing this week is how the path starts moving."},
  {"id":"ff-1186","cat":"tools-and-help","type":"role-play","hook":"A friend is drowning in future-anxiety and says they feel completely alone in it.","persona":"any","source":"supporting a friend","relearn":"You can remind a friend no one has it sorted and offer to find real support together, not just cheer them up.","setup":"Meet them warmly. Say:","yourLine":[{"text":"\"You're not alone and no one's got it sorted — want to look for some real support together?\"","best":true},{"text":"\"You'll be fine, just relax.\""}]},
  {"id":"ff-1187","cat":"tools-and-help","type":"match","hook":"Match the unhelpful coping habit to the healthier swap.","persona":"any","source":"swaps that help","relearn":"Swap doomscrolling for a breather, all-nighters for one next step, and bottling up for talking to someone.","pairs":[{"left":"Doomscrolling at midnight","right":"A two-minute breather"},{"left":"Anxious all-nighters","right":"One next step, then sleep"},{"left":"Bottling it all up","right":"Telling one trusted person"},{"left":"Numbing with endless scrolling","right":"A short walk outside"},{"left":"Comparing on social feeds","right":"Texting your mentor instead"}]},
  {"id":"ff-1188","cat":"tools-and-help","type":"sort","hook":"Sort: a sign to just keep going, or a sign to reach for real support?","persona":"any","source":"when to escalate","relearn":"A nervous week or a tough day, keep going with your tools; weeks of heaviness or hopelessness, reach for support.","items":[{"id":"a","text":"Nervous before one interview"},{"id":"b","text":"Hopeless most days for weeks"},{"id":"c","text":"A tough day you bounced from"},{"id":"d","text":"Can't sleep or eat from dread"},{"id":"e","text":"Stressed but still functioning"},{"id":"f","text":"Feeling there's no point at all"}],"bins":[{"id":"keep","label":"Keep going (use tools)","valence":"pos"},{"id":"reach","label":"Reach for support","valence":"tell"}],"key":{"a":"keep","b":"reach","c":"keep","d":"reach","e":"keep","f":"reach"}},
  {"id":"ff-1189","cat":"tools-and-help","type":"branch","hook":"A reel promises 'quit and be a crorepati in a year' and you're tempted to gamble it all.","persona":"any","source":"viral advice","options":[{"text":"Check it against a mentor doing the actual work","consequence":"Real experience deflates the hype; you decide clear-eyed.","outcome":"grounded","best":true},{"text":"Make a life-sized bet on a stranger's reel","consequence":"A viral reel isn't guidance; check with someone doing the work first."}],"debrief":"Reliable guidance comes from people doing the work, not viral reels.","relearn":"Check viral 'get rich' advice against someone doing the work first."},
  {"id":"ff-1190","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A counsellor will just tell me which career to pick — or judge me for struggling.\"","persona":"any","source":"what a counsellor does","relearn":"A campus counsellor helps you steady and think it through, without judging you or handing you one 'right' answer.","myth":{"un":"A counsellor hands you a career and judges you for struggling.","re":"A counsellor helps you steady and think clearly, without judgement; they walk with you, not decide for you.","why":"Their job is support, not a verdict on you."}},
  {"id":"ff-1191","cat":"tools-and-help","type":"reflect","hook":"Lensy: which 'find your feet' tool will you keep in your pocket?","persona":"any","source":"carry a tool","relearn":"A next-step tool, a breathing space and one person you can reach are the tools that keep future-anxiety workable.","prompt":"Pick one to carry.","options":["The next-step tool","A breathing space","A mentor I can reach","A trusted friend"],"affirm":"Keep that one close. The future feels less like a threat when you know you've got a tool for the wobble."},
  {"id":"ff-1192","cat":"tools-and-help","type":"spot","hook":"Spot the two replies that quietly shame someone for asking for help.","persona":"any","source":"shaming the ask","relearn":"'Reaching out is smart' is the right reflex; 'sort yourself out' and 'others have it worse' shame the asker.","scene":[{"id":"a","text":"\"That took courage — let's find support\"","trick":false},{"id":"b","text":"\"Just sort yourself out\"","trick":true},{"id":"c","text":"\"You're not alone in this\"","trick":false},{"id":"d","text":"\"Others have it way worse than you\"","trick":true},{"id":"e","text":"\"It's smart to ask for help\"","trick":false}],"why":"'Sort yourself out' and 'others have it worse' shame the ask; the others make reaching out feel safe."},
  {"id":"ff-1193","cat":"tools-and-help","type":"match","hook":"Match the tool to the exact moment you'd reach for it.","persona":"any","source":"right tool, right moment","relearn":"Use the next-step tool when stuck, a breather when shaking, a mentor when unsure, and a helpline when it's heavy.","pairs":[{"left":"Mind's gone blank with overwhelm","right":"Write the one next step"},{"left":"Heart racing before a result","right":"Slow your breathing"},{"left":"Genuinely unsure of the path","right":"Ask a mentor"},{"left":"Dread that won't lift for weeks","right":"Call Tele-MANAS 14416"},{"left":"Just need to not be alone","right":"Text a trusted friend"}]},
  {"id":"ff-1194","cat":"tools-and-help","type":"branch","hook":"Family says counselling is 'for mad people' and you're carrying real weight quietly.","persona":"Aarti","source":"stigma vs support","options":[{"text":"Reach support privately; your wellbeing isn't up for a vote","consequence":"You get help without winning an argument first.","outcome":"supported","best":true},{"text":"Stay silent to avoid the stigma talk","consequence":"Stigma is wrong, not your distress; you can reach support privately."}],"debrief":"Reaching for support is smart even when those around you misunderstand it.","relearn":"Stigma is wrong, not your distress; you can reach support privately, no permission needed."},
  {"id":"ff-1195","cat":"tools-and-help","type":"sort","hook":"Sort: a small habit that keeps anxiety workable, or one that quietly winds it up?","persona":"any","source":"habits that wind up or down","relearn":"Check-ins, breathers and small steps wind anxiety down; comparison scrolling, all-nighters and isolating wind it up.","items":[{"id":"a","text":"A weekly self-check-in"},{"id":"b","text":"Late-night comparison scrolling"},{"id":"c","text":"One small step most days"},{"id":"d","text":"Skipping sleep to grind"},{"id":"e","text":"Naming feelings to a friend"},{"id":"f","text":"Going quiet and isolating"}],"bins":[{"id":"down","label":"Winds it down","valence":"pos"},{"id":"up","label":"Winds it up","valence":"neg"}],"key":{"a":"down","b":"up","c":"down","d":"up","e":"down","f":"up"}},
  {"id":"ff-1196","cat":"tools-and-help","type":"role-play","hook":"You finally decide to reach out to the campus counsellor but freeze on what to say.","persona":"Rohan","source":"first words to a counsellor","relearn":"You don't need the perfect words; naming that you're struggling and want support is more than enough to start.","setup":"Keep it simple. Say:","yourLine":[{"text":"\"I've been really stressed about my future and I'd like some support — can we talk?\"","best":true},{"text":"Cancel because you can't word it perfectly"}]},
  {"id":"ff-1197","cat":"tools-and-help","type":"reflect","hook":"Lensy: support isn't a sign something's wrong with you — it's how people carry hard stretches. Sit with that?","persona":"any","source":"support is normal","relearn":"Leaning on support is an ordinary part of navigating a hard stretch, not proof that something is wrong with you.","prompt":"What do you think?","options":["Yes","It's just normal","Carries the load"],"affirm":"Everyone leans on something to get through hard stretches; reaching out means you're carrying it wisely."},
  {"id":"ff-1198","cat":"tools-and-help","type":"match","hook":"Match each '3am thought' to the steadier reframe a tool offers.","persona":"any","source":"3am reframes","relearn":"Shrink 'figure out everything' to one step, swap 'too late' for 'small steps count', and meet 'alone' with support.","pairs":[{"left":"\"I must figure out everything now\"","right":"Pick one next step"},{"left":"\"It's all too late\"","right":"Small steps still count"},{"left":"\"I'm completely alone\"","right":"Reach one person"},{"left":"\"I can't breathe through this\"","right":"Slow it down a minute"},{"left":"\"No one would help me\"","right":"A clear ask usually lands"}]},
  {"id":"ff-1199","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Talking to a mentor means admitting I can't figure it out myself.\"","persona":"Deepak","source":"mentors aren't a confession","relearn":"Using a mentor is how resourceful people move faster, not an admission of failure — everyone uses guides.","myth":{"un":"Asking a mentor admits I can't figure things out myself.","re":"Asking a mentor is how resourceful people move faster; borrowing someone's experience is smart, not failure.","why":"No one builds a path entirely alone."}},
  {"id":"ff-1200","cat":"tools-and-help","type":"branch","hook":"You're spiralling about everything at once and can't even start.","persona":"any","source":"breather then step","options":[{"text":"Breathe for a minute, then write just one next step","consequence":"Calmer, you can finally see one doable thing.","outcome":"unstuck","best":true},{"text":"Force yourself to plan it all while panicking","consequence":"Planning mid-panic rarely works; a breather first, then one step, gets you moving."}],"debrief":"Steady the spike, then shrink it to one step — the breather and next-step tool pair well.","relearn":"When spiralling, breathe to steady the spike first, then write one next step."},
  {"id":"ff-1201","cat":"tools-and-help","type":"spot","hook":"Spot the two 'tools' that only look helpful but actually feed the anxiety.","persona":"any","source":"fake tools","relearn":"A breather, a mentor and a next step genuinely help; endless researching and numbing-scrolling just feel productive.","scene":[{"id":"a","text":"A one-minute breathing space","trick":false},{"id":"b","text":"Researching 'best career' for hours","trick":true},{"id":"c","text":"Texting a mentor a clear question","trick":false},{"id":"d","text":"Scrolling to numb the dread","trick":true},{"id":"e","text":"Writing one small next step","trick":false}],"why":"Hours of 'research' and numbing-scroll feel productive but feed the spiral; the others actually steady you."},
  {"id":"ff-1202","cat":"tools-and-help","type":"match","hook":"Match what someone's struggling with to the kind of help that fits it.","persona":"any","source":"matching help to struggle","relearn":"Confusion wants a mentor, panic wants a breather, heaviness wants a helpline, and loneliness wants a person.","pairs":[{"left":"Totally confused about direction","right":"A mentor or careers service"},{"left":"Panicking right this second","right":"A breathing space"},{"left":"Heavy, can't-shift hopelessness","right":"Tele-MANAS 14416"},{"left":"Lonely and unheard","right":"A trusted person"},{"left":"Stuck on the very first move","right":"The next-step tool"}]},
  {"id":"ff-1203","cat":"tools-and-help","type":"reflect","hook":"Lensy: who is one person you could reach if the future ever felt too heavy to hold alone?","persona":"any","source":"name your person","relearn":"Knowing one person you'd reach — a friend, a mentor, or Tele-MANAS 14416 — means you never have to hold it alone.","prompt":"Picture one.","options":["A close friend","A mentor","Family I trust","Tele-MANAS 14416"],"affirm":"Hold that person in mind. Knowing who you'd reach is half of never carrying the heavy stuff alone."},
  {"id":"ff-1204","cat":"tools-and-help","type":"sort","hook":"Sort: a sturdy reason to keep going, or a fear dressed up as a fact?","persona":"any","source":"truths vs fears in the toolkit","relearn":"'No one's sorted' and 'support helps' are sturdy truths; 'too far behind' and 'asking is weak' are fears, not facts.","items":[{"id":"a","text":"\"No one has it figured out\""},{"id":"b","text":"\"I'm too far behind to recover\""},{"id":"c","text":"\"Asking for help shares the load\""},{"id":"d","text":"\"Needing support means I failed\""},{"id":"e","text":"\"Small steps genuinely count\""},{"id":"f","text":"\"It's too late for someone like me\""}],"bins":[{"id":"true","label":"Sturdy truth","valence":"pos"},{"id":"fear","label":"Fear, not fact","valence":"neg"}],"key":{"a":"true","b":"fear","c":"true","d":"fear","e":"true","f":"fear"}},
  {"id":"ff-1205","cat":"tools-and-help","type":"branch","hook":"You're new in the city for work, no campus, no safety net, and it's getting heavy.","persona":"Meena","source":"support without a network","options":[{"text":"Use a free route — Tele-MANAS 14416 — that needs no contacts","consequence":"Support reaches you even with no connections in the city.","outcome":"supported","best":true},{"text":"Assume help is only for people with networks","consequence":"Free routes need no network; support isn't only for the connected."}],"debrief":"You don't need contacts or a campus — free helplines are open to anyone.","relearn":"Free routes need no network; support isn't only for the well-connected."},
  {"id":"ff-1208","cat":"tools-and-help","type":"role-play","hook":"A senior offers, 'message me anytime if you're stuck' — and you almost don't.","persona":"any","source":"taking up the offer","relearn":"When someone genuinely offers help, taking them up on it with a clear, small ask is smart, not an imposition.","setup":"Take the offer. Say:","yourLine":[{"text":"\"Thanks — actually, could I ask you one thing about how you chose your path?\"","best":true},{"text":"Say 'I'm fine' and never follow up"}]},
  {"id":"ff-1206","cat":"tools-and-help","type":"match","hook":"Match the toolkit move to the future-anxiety problem it's built for.","persona":"any","source":"toolkit by problem","relearn":"Overwhelm needs shrinking, a spike needs slowing, drift needs a mentor, and heaviness needs a real helpline.","pairs":[{"left":"Everything feels too big","right":"Shrink it to one step"},{"left":"A sudden wave of panic","right":"Slow the breathing"},{"left":"Drifting with no direction","right":"Borrow a mentor's view"},{"left":"Weeks of heaviness","right":"Tele-MANAS 14416 or a counsellor"},{"left":"Caught in comparison","right":"Step off the feed"}]},
  {"id":"ff-1207","cat":"tools-and-help","type":"reflect","hook":"Lensy: the bravest thing isn't pretending you're fine — it's reaching out before it gets too heavy. Agree?","persona":"any","source":"reach out early","relearn":"Reaching out early, before distress gets unbearable, is braver and wiser than pretending you're fine.","prompt":"What do you think?","options":["Yes","Early is wise","Brave to ask"],"affirm":"Reaching out before things get too heavy is real courage — and it's far easier than carrying it all silently."},
  {"id":"ff-1260","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"If I don't crack a top college, I'm worthless.\"","myth":{"un":"If I don't crack a top college, I'm worthless.","re":"A college 'tier' is a status marker, not a measure of your worth.","why":"Your value was never a label on an admit card."},"relearn":"A college tier is a status marker, not a measure of your worth.","persona":"Deepak","source":"college tier myth"},
  {"id":"ff-1261","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"My package decides how much respect I deserve.\"","myth":{"un":"My package decides how much respect I deserve.","re":"Respect rests on your character and how you treat people, not a salary figure.","why":"A number on an offer letter measures pay, not the person."},"relearn":"Respect rests on character, not a salary figure.","persona":"any","source":"package myth"},
  {"id":"ff-1262","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"A bad result this year cancels everything good about me.\"","myth":{"un":"A bad result this year cancels everything good about me.","re":"One result is a snapshot of one test, not a verdict on who you are.","why":"Your kindness, effort and character don't show up on a mark sheet."},"relearn":"One result is a snapshot, not a verdict on who you are.","persona":"any","source":"result myth"},
  {"id":"ff-1263","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"Only a 'settled' job makes me someone my family can be proud of.\"","myth":{"un":"Only a 'settled' job makes me someone my family can be proud of.","re":"You are worthy as you are; pride built only on a job title is a fragile kind.","why":"Who you are outlasts any title you do or don't hold."},"relearn":"You are worthy as you are, not only when you hold a 'settled' title.","persona":"Aarti","source":"settled job myth"},
  {"id":"ff-1264","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"My rank is basically my identity now.\"","myth":{"un":"My rank is basically my identity now.","re":"A rank orders one exam on one day; it is not your identity.","why":"You existed as a whole person long before any rank list."},"relearn":"A rank orders one exam; it is not your identity.","persona":"any","source":"rank identity myth"},
  {"id":"ff-1265","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"Indian exam culture proves rank really is who you are.\"","myth":{"un":"Indian exam culture proves rank really is who you are.","re":"That old framing treats rank as a verdict on identity, and it can be unlearned.","why":"A long habit of measuring people by rank doesn't make the habit true."},"relearn":"Treating rank as a verdict on identity is a habit you can unlearn.","persona":"any","source":"culture myth"},
  {"id":"ff-1266","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"Worth has to be earned with each new achievement.\"","myth":{"un":"Worth has to be earned with each new achievement.","re":"Steady self-worth is unconditional; it doesn't rise with a win or fall with a loss.","why":"If worth rose and fell with results, no one would ever feel secure."},"relearn":"Self-worth is unconditional, not earned again with each achievement.","persona":"any","source":"earned worth myth"},
  {"id":"ff-1267","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"People will only value me if my CV impresses them.\"","myth":{"un":"People will only value me if my CV impresses them.","re":"The people who matter value how you treat them, not your CV.","why":"Connection is built on character, not on a list of achievements."},"relearn":"The people who matter value how you treat them, not your CV.","persona":"any","source":"impress myth"},
  {"id":"ff-1268","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"A topper is worth more as a human than an average student.\"","myth":{"un":"A topper is worth more as a human than an average student.","re":"Marks rank a test, never the worth of the human who sat it.","why":"Two people can share the same worth and very different scores."},"relearn":"Marks rank a test, never the worth of the human who sat it.","persona":"any","source":"topper myth"},
  {"id":"ff-1269","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"If my startup or career fails, I'm a failure as a person.\"","myth":{"un":"If my startup or career fails, I'm a failure as a person.","re":"An outcome can fall short without making you, the person, a failure.","why":"What you build is one thing you did, not the whole of who you are."},"relearn":"An outcome can fall short without making you a failure as a person.","persona":"any","source":"failure-person myth"},
  {"id":"ff-1270","cat":"worth-beyond-cv","type":"strike-rewrite","hook":"\"My worth drops every time someone out-earns me.\"","myth":{"un":"My worth drops every time someone out-earns me.","re":"Your worth is held steady; it doesn't shrink because someone earns more.","why":"Comparing salaries measures pay, not the value of a life."},"relearn":"Your worth is steady; it doesn't shrink when someone out-earns you.","persona":"Meena","source":"out-earned myth"},
  {"id":"ff-1271","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a steady source of worth, or a fragile scoreboard?","items":[{"id":"a","text":"The way you treat people"},{"id":"b","text":"Your latest CGPA"},{"id":"c","text":"Friendships you've kept"},{"id":"d","text":"Your placement package"},{"id":"e","text":"Living by your values"},{"id":"f","text":"Your competitive-exam rank"}],"bins":[{"id":"steady","label":"Steady worth","valence":"pos"},{"id":"score","label":"Fragile scoreboard","valence":"neg"}],"key":{"a":"steady","b":"score","c":"steady","d":"score","e":"steady","f":"score"},"relearn":"How you treat people, friendships and values are steady worth; CGPA, package and rank are a fragile scoreboard.","persona":"any","source":"steady vs scoreboard"},
  {"id":"ff-1272","cat":"worth-beyond-cv","type":"sort","hook":"Sort: outlasts any rank, or fades with the scoreboard?","items":[{"id":"a","text":"How loyal you are to friends"},{"id":"b","text":"A trophy in the cupboard"},{"id":"c","text":"The way you keep your word"},{"id":"d","text":"Last year's merit list spot"},{"id":"e","text":"Your honesty under pressure"},{"id":"f","text":"A college 'brand name'"}],"bins":[{"id":"lasts","label":"Outlasts rank","valence":"pos"},{"id":"fades","label":"Fades with the score","valence":"neg"}],"key":{"a":"lasts","b":"fades","c":"lasts","d":"fades","e":"lasts","f":"fades"},"relearn":"Loyalty, keeping your word and honesty outlast any rank; trophies, merit-list spots and brand names fade.","persona":"any","source":"outlasts rank"},
  {"id":"ff-1273","cat":"worth-beyond-cv","type":"sort","hook":"Sort: builds real worth, or just chases status?","items":[{"id":"a","text":"Being there when a friend struggles"},{"id":"b","text":"A flashy designation on LinkedIn"},{"id":"c","text":"Doing honest work you respect"},{"id":"d","text":"A title relatives can brag about"},{"id":"e","text":"Treating juniors with respect"},{"id":"f","text":"Out-ranking your batchmates"}],"bins":[{"id":"worth","label":"Real worth","valence":"pos"},{"id":"status","label":"Chasing status","valence":"neg"}],"key":{"a":"worth","b":"status","c":"worth","d":"status","e":"worth","f":"status"},"relearn":"Showing up for people, honest work and respect build real worth; flashy titles and out-ranking others chase status.","persona":"any","source":"worth vs status"},
  {"id":"ff-1274","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a true statement about your worth, or a fear talking?","items":[{"id":"a","text":"\"My worth doesn't move with my marks\""},{"id":"b","text":"\"I'm nothing without a top job\""},{"id":"c","text":"\"I matter beyond what I produce\""},{"id":"d","text":"\"A rejection means I'm not enough\""},{"id":"e","text":"\"Who I am isn't on a mark sheet\""},{"id":"f","text":"\"My value is my package\""}],"bins":[{"id":"true","label":"True about worth","valence":"pos"},{"id":"fear","label":"Just a fear","valence":"neg"}],"key":{"a":"true","b":"fear","c":"true","d":"fear","e":"true","f":"fear"},"relearn":"Worth that doesn't move with marks and mattering beyond output are true; 'nothing without a job' and 'value is my package' are fear.","persona":"any","source":"true vs fear"},
  {"id":"ff-1275","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a healthy way to hold a setback, or worth-as-CV talking?","items":[{"id":"a","text":"\"That result was rough; I'm still me\""},{"id":"b","text":"\"That result proves I'm worthless\""},{"id":"c","text":"\"I can be sad and still whole\""},{"id":"d","text":"\"One failure cancels all of me\""},{"id":"e","text":"\"My people still see who I am\""},{"id":"f","text":"\"Now no one should respect me\""}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"cv","label":"Worth-as-CV","valence":"neg"}],"key":{"a":"healthy","b":"cv","c":"healthy","d":"cv","e":"healthy","f":"cv"},"relearn":"'Still me', 'sad and whole' and 'my people see me' are healthy; 'worthless', 'cancels all of me' and 'no respect' are worth-as-CV.","persona":"any","source":"holding a setback"},
  {"id":"ff-1276","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a source of worth that's yours to keep, or one others control?","items":[{"id":"a","text":"Your values and how you live"},{"id":"b","text":"A recruiter's verdict on you"},{"id":"c","text":"The care you put into things"},{"id":"d","text":"How relatives rank your cousin"},{"id":"e","text":"The relationships you tend"},{"id":"f","text":"A leaderboard you didn't make"}],"bins":[{"id":"yours","label":"Yours to keep","valence":"pos"},{"id":"theirs","label":"Others control it","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"Your values, care and relationships are yours to keep; recruiters' verdicts and leaderboards are controlled by others.","persona":"any","source":"yours to keep"},
  {"id":"ff-1277","cat":"worth-beyond-cv","type":"sort","hook":"Sort: what a mark sheet can measure, or what it can't?","items":[{"id":"a","text":"How you answered on one day"},{"id":"b","text":"Whether you're kind"},{"id":"c","text":"Your score in one subject"},{"id":"d","text":"How you treat people who can't help you"},{"id":"e","text":"A rank against others that day"},{"id":"f","text":"Your character under pressure"}],"bins":[{"id":"can","label":"It can measure","valence":"neutral"},{"id":"cant","label":"It can't measure","valence":"pos"}],"key":{"a":"can","b":"cant","c":"can","d":"cant","e":"can","f":"cant"},"relearn":"A mark sheet measures one day's answers, a subject score and a rank; it can't measure kindness, how you treat people or character.","persona":"any","source":"what a sheet measures"},
  {"id":"ff-1278","cat":"worth-beyond-cv","type":"sort","hook":"Sort: makes a life feel rich, or just looks rich to others?","items":[{"id":"a","text":"People who'd show up for you at 2am"},{"id":"b","text":"A job title that sounds big"},{"id":"c","text":"Work that feels meaningful to you"},{"id":"d","text":"A car relatives will notice"},{"id":"e","text":"Days you're proud of how you acted"},{"id":"f","text":"A salary you can quote at parties"}],"bins":[{"id":"rich","label":"A rich life","valence":"pos"},{"id":"looks","label":"Just looks rich","valence":"neg"}],"key":{"a":"rich","b":"looks","c":"rich","d":"looks","e":"rich","f":"looks"},"relearn":"People who show up, meaningful work and days you're proud of make a rich life; big titles, cars and quotable salaries just look rich.","persona":"any","source":"rich vs looks rich"},
  {"id":"ff-1279","cat":"worth-beyond-cv","type":"sort","hook":"Sort: a kind thing to say to yourself after a setback, or worth-as-rank?","items":[{"id":"a","text":"\"I'm allowed to be more than this score\""},{"id":"b","text":"\"This score is the final word on me\""},{"id":"c","text":"\"I can learn from this and stay whole\""},{"id":"d","text":"\"I should be ashamed to exist now\""},{"id":"e","text":"\"My worth isn't up for marking\""},{"id":"f","text":"\"I'm only the rank beside my name\""}],"bins":[{"id":"kind","label":"Kind to yourself","valence":"pos"},{"id":"rank","label":"Worth-as-rank","valence":"neg"}],"key":{"a":"kind","b":"rank","c":"kind","d":"rank","e":"kind","f":"rank"},"relearn":"Self-talk that lets you be more than a score is kind; making a score the final word on you is worth-as-rank.","persona":"any","source":"kind self-talk"},
  {"id":"ff-1280","cat":"worth-beyond-cv","type":"sort","hook":"Sort: who you'd still be without your CV, or only a line on it?","items":[{"id":"a","text":"A good friend"},{"id":"b","text":"Your job title"},{"id":"c","text":"Someone's favourite person"},{"id":"d","text":"Your CGPA"},{"id":"e","text":"A person who keeps promises"},{"id":"f","text":"Your placement status"}],"bins":[{"id":"you","label":"Still you","valence":"pos"},{"id":"line","label":"Only a CV line","valence":"neg"}],"key":{"a":"you","b":"line","c":"you","d":"line","e":"you","f":"line"},"relearn":"A good friend, someone's favourite person and a promise-keeper are still you; job title, CGPA and placement status are only CV lines.","persona":"any","source":"without your CV"},
  {"id":"ff-1281","cat":"worth-beyond-cv","type":"sort","hook":"Sort: builds steady self-worth, or props up a fragile one?","items":[{"id":"a","text":"Knowing your own values"},{"id":"b","text":"Needing to beat everyone"},{"id":"c","text":"Self-respect that stays put"},{"id":"d","text":"Chasing constant approval"},{"id":"e","text":"Treating yourself with care"},{"id":"f","text":"Worth that lives on the scoreboard"}],"bins":[{"id":"steady","label":"Steady self-worth","valence":"pos"},{"id":"fragile","label":"Fragile self-worth","valence":"neg"}],"key":{"a":"steady","b":"fragile","c":"steady","d":"fragile","e":"steady","f":"fragile"},"relearn":"Knowing your values, steady self-respect and self-care build steady worth; needing to win, chasing approval and scoreboard-worth are fragile.","persona":"any","source":"steady self-worth"},
  {"id":"ff-1282","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two lines that treat a person's worth as their CV.","scene":[{"id":"a","text":"\"You're more than your marks to me\"","trick":false},{"id":"b","text":"\"Low package? You've basically wasted your life\"","trick":true},{"id":"c","text":"\"I'm proud of how hard you tried\"","trick":false},{"id":"d","text":"\"No big job, so nothing to respect here\"","trick":true},{"id":"e","text":"\"Your kindness is what I notice first\"","trick":false}],"why":"The caught lines tie a person's whole worth to a package or a job, which is the worth-as-CV trap.","relearn":"A package or job title is a status marker, not a measure of someone's worth.","persona":"any","source":"spot worth-as-cv"},
  {"id":"ff-1283","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two thoughts that make your worth ride on a result.","scene":[{"id":"a","text":"\"That result stung, and I'm still whole\"","trick":false},{"id":"b","text":"\"One bad day, so I'm worthless now\"","trick":true},{"id":"c","text":"\"I can learn from this and move\"","trick":false},{"id":"d","text":"\"This proves I never mattered\"","trick":true},{"id":"e","text":"\"My people love me the same today\"","trick":false}],"why":"The caught thoughts pin your entire worth to one result; worth is steady and doesn't move with a score.","relearn":"Your worth is steady; it doesn't rise with a good result or fall with a bad one.","persona":"any","source":"spot result-worth"},
  {"id":"ff-1284","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two pressures dressed up as 'what success means'.","scene":[{"id":"a","text":"Work that fits your values","trick":false},{"id":"b","text":"\"Only a high-status title counts as success\"","trick":true},{"id":"c","text":"A life you can actually live with","trick":false},{"id":"d","text":"\"If relatives aren't impressed, you've failed\"","trick":true},{"id":"e","text":"Doing work you can respect","trick":false}],"why":"The caught lines define success by status and others' approval, not by fit; that's the worth-as-CV pressure.","relearn":"Success can be a life that fits your values, not just a prestigious title others approve of.","persona":"Zoya","source":"spot success pressure"},
  {"id":"ff-1285","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two lines a relative might use to grade you as a person.","scene":[{"id":"a","text":"\"I'm glad you're finding your feet\"","trick":false},{"id":"b","text":"\"Your cousin's package makes you look small\"","trick":true},{"id":"c","text":"\"Tell me what you're enjoying these days\"","trick":false},{"id":"d","text":"\"No campus job means no respect from us\"","trick":true},{"id":"e","text":"\"However it goes, you're still ours\"","trick":false}],"why":"The caught lines grade you by a cousin's package and a campus job; that ranking isn't a verdict on you.","relearn":"A relative tying respect to your package or job is a status habit, not the truth about you.","persona":"Aarti","source":"spot grading lines"},
  {"id":"ff-1286","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two beliefs that turn a mark sheet into a verdict on you.","scene":[{"id":"a","text":"\"A mark sheet measures one test, not me\"","trick":false},{"id":"b","text":"\"My marks are the truth about my worth\"","trick":true},{"id":"c","text":"\"My character isn't on that page\"","trick":false},{"id":"d","text":"\"This rank is who I really am\"","trick":true},{"id":"e","text":"\"I'm a whole person off the page too\"","trick":false}],"why":"The caught beliefs make a mark sheet a verdict on identity; it measures one test on one day, not who you are.","relearn":"A mark sheet measures one test on one day, not your identity, character or potential.","persona":"Deepak","source":"spot mark-sheet verdict"},
  {"id":"ff-1287","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two lines that judge a friend by their CV.","scene":[{"id":"a","text":"\"You'd be a great person to work with\"","trick":false},{"id":"b","text":"\"You're a backbencher, so why would I rate you\"","trick":true},{"id":"c","text":"\"I trust how you handle things\"","trick":false},{"id":"d","text":"\"No fancy college tag means you're nobody\"","trick":true},{"id":"e","text":"\"Your honesty is rare, honestly\"","trick":false}],"why":"The caught lines rate a friend by marks and a college tag; worth rests on character, not labels.","relearn":"A 'backbencher' label or college tag is a status marker, not a measure of a friend's worth.","persona":"any","source":"spot judging a friend"},
  {"id":"ff-1288","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two messages that say worth must be earned with achievements.","scene":[{"id":"a","text":"\"You're worthy whether or not you win\"","trick":false},{"id":"b","text":"\"Earn your place or you don't deserve one\"","trick":true},{"id":"c","text":"\"Rest is allowed; you're enough as you are\"","trick":false},{"id":"d","text":"\"Stop achieving and you stop mattering\"","trick":true},{"id":"e","text":"\"Your worth isn't a thing you re-earn daily\"","trick":false}],"why":"The caught messages make worth conditional on output; steady self-worth is unconditional, not re-earned.","relearn":"Self-worth is unconditional; it isn't earned again with each new achievement.","persona":"any","source":"spot earned-worth"},
  {"id":"ff-1289","cat":"worth-beyond-cv","type":"spot","hook":"Spot the two thoughts comparing your worth to someone's highlight reel.","scene":[{"id":"a","text":"\"Glad for their offer; my path is mine\"","trick":false},{"id":"b","text":"\"Their package proves I'm less of a person\"","trick":true},{"id":"c","text":"\"I can admire their work and stay steady\"","trick":false},{"id":"d","text":"\"Everyone's ahead, so I must be worthless\"","trick":true},{"id":"e","text":"\"One feed isn't the whole story of anyone\"","trick":false}],"why":"The caught thoughts rank you against others' wins; a feed is a highlight reel, not a verdict.","relearn":"Measuring your worth against a highlight reel is the trap; worth isn't a ranking.","persona":"any","source":"spot reel-comparison"},
  {"id":"ff-1290","cat":"worth-beyond-cv","type":"branch","hook":"A relative compares your package to your cousin's at a family lunch.","options":[{"text":"Stay steady: \"We're on different paths; I'm okay with mine.\"","consequence":"You hold your worth without a fight, and the comparison loses its grip.","outcome":"steady","best":true},{"text":"Decide the comparison is right and that you're worth less","consequence":"Holding your worth as your own keeps a salary figure from grading you as a person."}],"debrief":"A package is a status marker, not a verdict on your worth.","relearn":"Your worth isn't graded by how your package compares.","persona":"Aarti","source":"family lunch comparison"},
  {"id":"ff-1291","cat":"worth-beyond-cv","type":"branch","hook":"You didn't get placed in the first round and feel like 'nobody' now.","options":[{"text":"Name the feeling, then remind yourself you're more than a placement","consequence":"The sting stays real but stops defining you, and you can think about next steps.","outcome":"whole","best":true},{"text":"Conclude the result means you're worthless","consequence":"Letting the result be information, not a verdict, keeps one round from deciding you."}],"debrief":"A placement round is one outcome, not a measure of your worth.","relearn":"Not getting placed in a round doesn't make you 'nobody'.","persona":"Deepak","source":"first-round placement"},
  {"id":"ff-1292","cat":"worth-beyond-cv","type":"branch","hook":"You're choosing between a prestigious title and work that actually fits you.","options":[{"text":"Weigh fit and values, not just what will impress people","consequence":"You pick a path you can live with, anchored in what matters to you.","outcome":"fit","best":true},{"text":"Take the title purely for the status it carries","consequence":"Choosing for fit, not just status, leads to a path you can live with."}],"debrief":"Fit matters more than status when a title is the only thing pulling you.","relearn":"Choose for fit and values, not a title that only impresses others.","persona":"any","source":"title vs fit"},
  {"id":"ff-1293","cat":"worth-beyond-cv","type":"branch","hook":"Your whole mood is swinging with each test score this term.","options":[{"text":"Anchor your worth in who you are, separate from the scoreboard","consequence":"Scores still matter, but your sense of self stops riding every high and low.","outcome":"anchored","best":true},{"text":"Keep letting each score decide how much you're worth","consequence":"Anchoring worth off the scoreboard gets you off an exhausting up-and-down."}],"debrief":"Steady worth doesn't rise with a good score or fall with a bad one.","relearn":"Anchor your worth in who you are, not in each test score.","persona":"any","source":"score mood swings"},
  {"id":"ff-1294","cat":"worth-beyond-cv","type":"branch","hook":"A friend just got a dream offer and you feel suddenly 'less than'.","options":[{"text":"Be genuinely glad for them and keep your own worth intact","consequence":"Celebrating them costs you nothing, and your worth doesn't shrink beside their win.","outcome":"glad","best":true},{"text":"Read their win as proof you're worth less","consequence":"Celebrating others' wins costs nothing; their offer is never a verdict on your worth."}],"debrief":"Someone else's win is not a measure of your value.","relearn":"A friend's offer doesn't make you 'less than'; your worth is yours.","persona":"any","source":"friend's dream offer"},
  {"id":"ff-1295","cat":"worth-beyond-cv","type":"branch","hook":"You're about to skip a hobby you love because it 'won't look good on a CV'.","options":[{"text":"Keep it because it's part of who you are, CV or not","consequence":"You hold onto something that's genuinely yours, not just resume fuel.","outcome":"yourself","best":true},{"text":"Drop it because only CV-worthy things count","consequence":"Keeping what's yours, CV or not, protects a part of you no resume can measure."}],"debrief":"Your life isn't only the parts that fit a CV.","relearn":"You're allowed to value parts of yourself that never reach a CV.","persona":"Zoya","source":"hobby vs cv"},
  {"id":"ff-1296","cat":"worth-beyond-cv","type":"branch","hook":"You catch yourself introducing people only by their college and package.","options":[{"text":"Notice it and start seeing people as people, not their stats","consequence":"You relate to who someone is, and quietly stop ranking yourself the same way.","outcome":"see-people","best":true},{"text":"Keep sorting everyone by their tier and salary","consequence":"Seeing people beyond their stats loosens the scoreboard you judge yourself by."}],"debrief":"When you stop ranking others by CV, you stop grading yourself.","relearn":"People, you included, are more than their college and package.","persona":"any","source":"introducing by stats"},
  {"id":"ff-1297","cat":"worth-beyond-cv","type":"branch","hook":"A relative says they'll be 'proud once you're settled in a big job'.","options":[{"text":"Gently say your worth holds now, not only once you're 'settled'","consequence":"You name your steady worth without rupture, even if they don't fully get it yet.","outcome":"named","best":true},{"text":"Accept that you only matter once the job arrives","consequence":"Naming your worth as steady now keeps it from waiting on a title to be real."}],"debrief":"Worth conditional on a job is fragile; yours holds steady regardless.","relearn":"Your worth holds now, not only once you're 'settled'.","persona":"Zoya","source":"proud once settled"},
  {"id":"ff-1298","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: a mark sheet can grade one test. It was never built to grade you.","prompt":"Sit with that for a second.","options":["I see it","One test, not me","Noted"],"affirm":"You are a whole person a mark sheet was never designed to measure.","relearn":"A mark sheet grades a test, not the person who sat it.","persona":"any","source":"reflect mark sheet"},
  {"id":"ff-1299","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: name one thing about you that no CV could ever capture.","prompt":"What comes up?","options":["My loyalty","How I listen","The way I show up"],"affirm":"That part of you is real worth, and no resume has a column for it.","relearn":"Your realest worth is the part no CV has a column for.","persona":"any","source":"reflect beyond cv"},
  {"id":"ff-1300","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: think of someone you love. Do you love their rank, or them?","prompt":"What's the honest answer?","options":["Them","Not their rank","Just them"],"affirm":"You love people for who they are, and that's exactly how worth works for you too.","relearn":"You love people for who they are, not their rank; the same is true of your worth.","persona":"any","source":"reflect who you love"},
  {"id":"ff-1301","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: your worth was here before your first exam and stays after your last.","prompt":"How does that land?","options":["Steadying","Before and after","I'll hold it"],"affirm":"Your worth doesn't start at an admit card or end at a result; it's just yours.","relearn":"Your worth exists before and after any exam, independent of results.","persona":"any","source":"reflect before and after"},
  {"id":"ff-1302","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: if a friend got your exact result, would you call them worthless?","prompt":"Would you?","options":["Never","Of course not","No way"],"affirm":"The kindness you'd give a friend is the kindness your own worth deserves too.","relearn":"You wouldn't call a friend worthless for a result; offer yourself that same truth.","persona":"any","source":"reflect friend's result"},
  {"id":"ff-1303","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: picture your worth as a floor, not an elevator that moves with scores.","prompt":"Can you feel the floor?","options":["Yes","Steady underfoot","It's there"],"affirm":"Your worth is a steady floor, not an elevator riding up and down with results.","relearn":"Worth is a steady floor, not an elevator that moves with each score.","persona":"any","source":"reflect floor not elevator"},
  {"id":"ff-1304","cat":"worth-beyond-cv","type":"reflect","hook":"Lensy: in ten years, which will you remember, your CGPA or who stood by you?","prompt":"What matters more, really?","options":["My people","Not the CGPA","Who stood by me"],"affirm":"The things that hold your worth are the ones that outlast any number on a transcript.","relearn":"What holds your worth outlasts any number on a transcript.","persona":"any","source":"reflect in ten years"},
  {"id":"ff-1305","cat":"worth-beyond-cv","type":"role-play","hook":"A friend calls themselves 'a failure' after a low semester result.","setup":"Separate the result from them. Say:","yourLine":[{"text":"\"A bad semester isn't a verdict on you, you're still the same good person to me.\"","best":true},{"text":"\"Yeah, that result really isn't a good look for you.\""}],"relearn":"Help a friend separate a result from who they are.","persona":"any","source":"friend calls self a failure"},
  {"id":"ff-1306","cat":"worth-beyond-cv","type":"role-play","hook":"A relative keeps measuring your pride-worthiness by your package.","setup":"Name your steady worth, gently. Say:","yourLine":[{"text":"\"I'm working hard, and my worth isn't just a salary number, I hope you can see me too.\"","best":true},{"text":"Quietly agree that your worth is whatever your package says"}],"relearn":"Keep your worth steady even when others tie pride to your package.","persona":"Aarti","source":"package pride"},
  {"id":"ff-1307","cat":"worth-beyond-cv","type":"role-play","hook":"A junior says they're 'nothing' because they didn't crack a top exam.","setup":"Offer them the steadier truth. Say:","yourLine":[{"text":"\"One exam can't decide who you are, there's so much more to you than a rank.\"","best":true},{"text":"\"Honestly, that exam probably does say where you stand.\""}],"relearn":"Remind someone an exam can't decide who they are.","persona":"any","source":"junior didn't crack exam"},
  {"id":"ff-1308","cat":"worth-beyond-cv","type":"role-play","hook":"Someone says they'll respect you more once you 'earn a big package'.","setup":"Hold your worth as already real. Say:","yourLine":[{"text":"\"My worth isn't something I have to earn with a package, it's steady either way.\"","best":true},{"text":"Accept that respect should wait until the package arrives"}],"relearn":"Your worth doesn't wait on a package to become real.","persona":"any","source":"respect once big package"},
  {"id":"ff-1309","cat":"worth-beyond-cv","type":"role-play","hook":"A friend is shrinking themselves to look small beside a high-achiever.","setup":"Put their worth back on steady ground. Say:","yourLine":[{"text":"\"Their win doesn't shrink you, your worth was never a competition with them.\"","best":true},{"text":"\"Yeah, next to them you do kind of look behind.\""}],"relearn":"Someone's worth isn't a competition with a high-achiever.","persona":"any","source":"shrinking beside achiever"},
  {"id":"ff-1310","cat":"worth-beyond-cv","type":"role-play","hook":"You're talking to yourself harshly after a rejection email.","setup":"Speak to yourself the way a kind friend would. Say:","yourLine":[{"text":"\"That stung, but a rejection is information, not a verdict on my worth.\"","best":true},{"text":"\"This just confirms I'm not good enough as a person.\""}],"relearn":"Talk to yourself after a rejection the way a kind friend would.","persona":"any","source":"self-talk after rejection"},
  {"id":"ff-1311","cat":"worth-beyond-cv","type":"role-play","hook":"A relative introduces you to guests only by your marks and college.","setup":"Add the part of you that isn't a stat. Say:","yourLine":[{"text":"\"There's more to me than my marks, I'd love to be known for who I am too.\"","best":true},{"text":"Let yourself be summed up entirely by your marks and college"}],"relearn":"You're more than the marks and college others introduce you by.","persona":"Deepak","source":"introduced by marks"},
  {"id":"ff-1312","cat":"worth-beyond-cv","type":"role-play","hook":"A friend says they'd be 'a better person' with a higher rank.","setup":"Untie character from rank for them. Say:","yourLine":[{"text":"\"A higher rank wouldn't make you a better person, you already are one.\"","best":true},{"text":"\"True, a better rank probably would make you better overall.\""}],"relearn":"A higher rank doesn't make someone a better person.","persona":"any","source":"better person with rank"},
  {"id":"ff-1313","cat":"worth-beyond-cv","type":"match","hook":"Match each worth-truth to the fear it answers.","pairs":[{"left":"You're far more than your achievements","right":"\"I'm only what I produce\""},{"left":"A mark sheet measures one test, not you","right":"\"This result is who I am\""},{"left":"Worth is steady, not earned each day","right":"\"I have to keep proving I matter\""},{"left":"Fit beats status when you choose","right":"\"I must impress everyone\""},{"left":"The people who matter value who you are","right":"\"They'll only love my CV\""}],"relearn":"Each fear has a steadier truth: you're more than a result, and your worth doesn't move with it.","persona":"any","source":"truth answers fear"},
  {"id":"ff-1314","cat":"worth-beyond-cv","type":"match","hook":"Match each marker to whether it's real worth or a status label.","pairs":[{"left":"How you treat people who can't help you","right":"Real worth, not a label"},{"left":"Your placement package","right":"A status marker only"},{"left":"Keeping your word when it's hard","right":"Real worth you carry"},{"left":"Your college's brand name","right":"A status tag, not worth"},{"left":"The care you bring to your work","right":"Worth that's genuinely yours"}],"relearn":"How you treat people, keeping your word and care are real worth; package and college brand are status markers.","persona":"any","source":"worth vs status markers"},
  {"id":"ff-1315","cat":"worth-beyond-cv","type":"match","hook":"Match each comparison to a steadier reframe.","pairs":[{"left":"\"Their offer means I'm behind\"","right":"Their timeline isn't my scoreboard"},{"left":"\"His package makes me less\"","right":"My worth isn't a salary contest"},{"left":"\"Everyone's ahead of me\"","right":"I'm comparing my behind-the-scenes to reels"},{"left":"\"I'll matter once I rank higher\"","right":"I already matter, off the rank list"},{"left":"\"Her win shrinks me\"","right":"Her win costs my worth nothing"}],"relearn":"Each comparison has a steadier reframe: others' timelines aren't your scoreboard, and you already matter.","persona":"any","source":"comparison to reframe"},
  {"id":"ff-1316","cat":"worth-beyond-cv","type":"match","hook":"Match each part of you to where it really shows up.","pairs":[{"left":"Your kindness","right":"In how you treat people"},{"left":"Your character","right":"In what you do when it's hard"},{"left":"Your CGPA","right":"On one transcript, one term"},{"left":"Your loyalty","right":"In who you stand by"},{"left":"Your package","right":"On an offer letter only"}],"relearn":"Kindness, character and loyalty show up in how you live; CGPA and package live only on paper.","persona":"any","source":"where worth shows up"},
  {"id":"ff-1317","cat":"worth-beyond-cv","type":"match","hook":"Match each setback line to the kinder, worth-steady version.","pairs":[{"left":"\"I failed, so I'm a failure\"","right":"\"I had a setback; I'm still me\""},{"left":"\"This rank defines me\"","right":"\"This rank is one data point\""},{"left":"\"No one should respect me now\"","right":"\"My people see me the same\""},{"left":"\"I've wasted my whole life\"","right":"\"This is a redirect, not the end\""},{"left":"\"I'm worthless after this\"","right":"\"My worth didn't move with it\""}],"relearn":"Each harsh setback line has a kinder version: a setback is a redirect, and your worth didn't move with it.","persona":"any","source":"setback to kinder line"},
  {"id":"ff-1318","cat":"worth-beyond-cv","type":"match","hook":"Match each source of worth to why it stays steady.","pairs":[{"left":"Your values","right":"They're yours whatever others rank"},{"left":"Your relationships","right":"They outlast any scoreboard"},{"left":"The way you live","right":"No result can edit it"},{"left":"Your self-respect","right":"It isn't up for marking"},{"left":"Your character","right":"It holds when grades don't"}],"relearn":"Values, relationships, how you live, self-respect and character stay steady because no result can mark them.","persona":"any","source":"why worth stays steady"},
  {"id":"ff-1319","cat":"worth-beyond-cv","type":"match","hook":"Match each well-meaning relative's line to what it really measures.","pairs":[{"left":"\"What's your package now?\"","right":"A salary, not your worth"},{"left":"\"Which college, beta?\"","right":"A brand tag, not who you are"},{"left":"\"Settled yet?\"","right":"A timeline, not your value"},{"left":"\"How's your rank?\"","right":"One test, not your identity"},{"left":"\"Are you happy, though?\"","right":"Something that actually matters"}],"relearn":"Package, college, 'settled' and rank measure status; whether you're happy is what actually matters.","persona":"any","source":"relative lines measure"},
  {"id":"ff-1350","cat":"your-path","type":"branch","hook":"You graduate next year with no clear plan and the worry is loud.","options":[{"text":"List three things you actually enjoy and explore one this week","consequence":"You give the worry a direction to move in.","outcome":"directed","best":true},{"text":"Wait for a single perfect career to appear in your head","consequence":"Exploring one real interest beats waiting for a perfect answer to just arrive."}],"debrief":"You find a path by exploring one real interest at a time, not by thinking harder.","relearn":"Explore one thing you enjoy this week; a path reveals itself in motion.","persona":"any","source":"explore one"},
  {"id":"ff-1351","cat":"your-path","type":"strike-rewrite","hook":"\"My branch in college locks in what I'm allowed to become.\"","myth":{"un":"My branch locks in what I'm allowed to become.","re":"Your branch is a starting point, not a cage; many people end up in fields unrelated to their degree.","why":"Skills and interests carry across fields."},"relearn":"Your degree branch is a starting point, not a cage on your future.","persona":"any","source":"branch isn't a cage"},
  {"id":"ff-1352","cat":"your-path","type":"sort","hook":"Sort: a values-based reason to choose, or a status-based one?","items":[{"id":"a","text":"\"This work genuinely interests me\""},{"id":"b","text":"\"My cousins will be impressed\""},{"id":"c","text":"\"I'd grow skills I care about\""},{"id":"d","text":"\"It sounds prestigious at weddings\""},{"id":"e","text":"\"It fits how I want to live\""},{"id":"f","text":"\"Everyone says it's the safe choice\""}],"bins":[{"id":"values","label":"Values-based","valence":"pos"},{"id":"status","label":"Status-based","valence":"uhoh"}],"key":{"a":"values","b":"status","c":"values","d":"status","e":"values","f":"status"},"relearn":"Interest, growth and fit are values-based reasons; impressing relatives or prestige are status-based.","persona":"any","source":"values vs status reasons"},
  {"id":"ff-1353","cat":"your-path","type":"branch","hook":"Family expects engineering; you keep getting pulled toward design.","options":[{"text":"Try a real design project before deciding","consequence":"You test the pull with evidence, not just a hunch.","outcome":"tested","best":true},{"text":"Bury the interest and assume it's a phase","consequence":"Testing the pull with a real project beats burying it; you deserve to know if it fits."}],"debrief":"You can quietly test a real interest before you choose; no rebellion required.","relearn":"Test a pulling interest with a small real project before you write it off.","persona":"Zoya","source":"test the pull"},
  {"id":"ff-1353a","cat":"your-path","type":"reflect","hook":"Lensy: the path that fits you can look nothing like the one you pictured at sixteen. That's allowed?","prompt":"What do you think?","options":["Yes","It can change","That's allowed"],"affirm":"Your sixteen-year-old plan was a guess with less information; updating it is growth, not failure.","relearn":"The path that fits you can differ from the one you once pictured.","persona":"any","source":"plans can change"},
  {"id":"ff-1355","cat":"your-path","type":"match","hook":"Match each small next step to the door it can open.","pairs":[{"left":"Emailing one alum to ask about their work","right":"A first honest look inside a field"},{"left":"Finishing one free online course","right":"A skill you can point to"},{"left":"Doing one weekend volunteer shift","right":"Experience without a big commitment"},{"left":"Attending one campus talk","right":"A name and a next conversation"},{"left":"Writing a one-page plan for the month","right":"A worry turned into actions"}],"relearn":"Each small, concrete step opens a real door; you don't need the whole map to take one.","persona":"Deepak","source":"steps and doors"},
  {"id":"ff-1356","cat":"your-path","type":"branch","hook":"A relative says your only 'real' option is a government job.","options":[{"text":"Hear them, then keep exploring the options that actually fit you","consequence":"You respect the love without adopting the limit.","outcome":"grounded","best":true},{"text":"Decide their one option is the only path and stop looking","consequence":"Hearing them while still exploring beats shrinking to one option."}],"debrief":"Family advice often comes from care and a narrow map; honour the care, widen the map.","relearn":"You can respect family's worry without accepting their single 'only' path.","persona":"Aarti","source":"only one option"},
  {"id":"ff-1357","cat":"your-path","type":"sort","hook":"Sort: a sign a path fits you, or a sign it's a misfit?","items":[{"id":"a","text":"You lose track of time doing it"},{"id":"b","text":"You dread it every single morning"},{"id":"c","text":"You're curious to learn more"},{"id":"d","text":"You only stay for others' approval"},{"id":"e","text":"It lines up with what you value"},{"id":"f","text":"It clashes with how you want to live"}],"bins":[{"id":"fit","label":"Fits you","valence":"pos"},{"id":"misfit","label":"A misfit","valence":"neg"}],"key":{"a":"fit","b":"misfit","c":"fit","d":"misfit","e":"fit","f":"misfit"},"relearn":"Losing track of time, curiosity and value-alignment signal fit; daily dread and approval-only signal misfit.","persona":"any","source":"fit signals"},
  {"id":"ff-1358","cat":"your-path","type":"branch","hook":"Everyone's racing to campus placements; you want a startup instead.","options":[{"text":"Define what success means to you, then choose by that","consequence":"You pick from your own values, not the herd's.","outcome":"aligned","best":true},{"text":"Follow the placement crowd just to not stand out","consequence":"Choosing by your own definition of success beats following the crowd to avoid standing out."}],"debrief":"The crowd's path fits many and not all; fit, not popularity, is the test.","relearn":"Choose by your own definition of success, not what the crowd is racing toward.","persona":"any","source":"not the herd"},
  {"id":"ff-1359","cat":"your-path","type":"strike-rewrite","hook":"\"If I don't choose right now, every door will close.\"","myth":{"un":"If I don't choose right now, every door closes.","re":"Most paths have on-ramps at many ages; pivots and second starts are normal, not closed doors.","why":"People change fields throughout working life."},"relearn":"Doors don't all close at once; pivots and later starts are normal routes.","persona":"any","source":"doors stay open"},
  {"id":"ff-1360","cat":"your-path","type":"reflect","hook":"Lensy: one small step you take this week counts more than a perfect plan you never start. Pick the step?","prompt":"What do you think?","options":["Yes","I'll pick one","Small beats perfect"],"affirm":"A single real step moves you; a perfect unstarted plan moves nothing. Small and started wins.","relearn":"One small step you actually take beats a perfect plan you never start.","persona":"any","source":"step beats plan"},
  {"id":"ff-1362","cat":"your-path","type":"sort","hook":"Sort: a step that builds your path, or one that just performs for others?","items":[{"id":"a","text":"Learning a skill you'll actually use"},{"id":"b","text":"Padding your CV with empty titles"},{"id":"c","text":"Talking to people doing the work"},{"id":"d","text":"Posting wins you didn't really earn"},{"id":"e","text":"Trying a small real project"},{"id":"f","text":"Chasing likes on a 'journey' post"}],"bins":[{"id":"builds","label":"Builds the path","valence":"pos"},{"id":"performs","label":"Just performs","valence":"uhoh"}],"key":{"a":"builds","b":"performs","c":"builds","d":"performs","e":"builds","f":"performs"},"relearn":"Real skills, real conversations and small projects build a path; padding and performing for likes don't.","persona":"any","source":"build vs perform"},
  {"id":"ff-1363","cat":"your-path","type":"branch","hook":"You're tempted to copy a friend's exact plan; it looks sorted.","options":[{"text":"Borrow their method, not destination; aim it at your interests","consequence":"You learn from them without losing yourself.","outcome":"yours","best":true},{"text":"Copy their plan wholesale and hope it fits","consequence":"Borrowing their method, aimed at your interests, beats copying a plan built for someone else."}],"debrief":"A friend's plan fits their values, not yours; take the method, keep your direction.","relearn":"Borrow a friend's method, not their destination; aim it at your interests.","persona":"any","source":"method not destination"},
  {"id":"ff-1364","cat":"your-path","type":"strike-rewrite","hook":"\"A values-based path means doing whatever feels good in the moment.\"","myth":{"un":"A values-based path means chasing whatever feels good right now.","re":"It means choosing by what you care about over time, which often asks for steady effort, not just comfort.","why":"Values are about direction, not momentary ease."},"relearn":"A values-based path follows what you care about over time, not just momentary comfort.","persona":"any","source":"values not whims"},
  {"id":"ff-1365","cat":"your-path","type":"reflect","hook":"Lensy: you don't owe anyone a five-year plan to be allowed to start. Begin where you are?","prompt":"What do you think?","options":["Yes","Begin here","No plan owed"],"affirm":"You can start with one interest and one step; the five-year plan is optional, not a permission slip.","relearn":"You can begin where you are; you don't owe anyone a five-year plan first.","persona":"any","source":"begin where you are"},
  {"id":"ff-1366","cat":"your-path","type":"branch","hook":"You're choosing a stream, paralysed by 'what if it's wrong'.","options":[{"text":"Pick the best fit now; you can adjust as you learn","consequence":"You move with a choice you can revise.","outcome":"moving","best":true},{"text":"Refuse to choose until you're certain it's the one right answer","consequence":"Choosing the best current fit and adjusting beats waiting for a certainty no one gets."}],"debrief":"There's rarely one right answer; a good-enough choice you refine beats endless 'what if'.","relearn":"Pick the best current fit and adjust; you don't need certainty to choose.","persona":"any","source":"choose and adjust"},
  {"id":"ff-1367","cat":"your-path","type":"match","hook":"Match each value to a next step that honours it.","pairs":[{"left":"You care about helping people","right":"Shadow someone in care or teaching work"},{"left":"You care about building things","right":"Make one small project end to end"},{"left":"You care about independence","right":"Take on one paid freelance task"},{"left":"You care about ideas","right":"Join a club or group in that field"},{"left":"You care about your roots","right":"Talk to someone solving a problem near home"}],"relearn":"A values-based step starts from what you care about and turns it into one concrete action.","persona":"Meena","source":"value to step"},
  {"id":"ff-1368","cat":"your-path","type":"branch","hook":"You have no contacts in your field, unlike richer classmates.","options":[{"text":"Build skills publicly; message people whose work you admire","consequence":"You create a network instead of inheriting one.","outcome":"resourceful","best":true},{"text":"Decide it's hopeless without family connections","consequence":"Building skills openly and reaching out creates a network; that beats giving up."}],"debrief":"No network is a disadvantage, not a verdict; open skills and outreach still open doors.","relearn":"Without contacts, build skills openly and reach out; you can create a network.","persona":"Deepak","source":"make your own network"},
  {"id":"ff-1369","cat":"your-path","type":"sort","hook":"Sort: a healthy way to choose a direction, or an anxious one?","items":[{"id":"a","text":"Steadying first, then deciding"},{"id":"b","text":"Picking in a 3am panic"},{"id":"c","text":"Weighing fit and interest"},{"id":"d","text":"Choosing only to silence relatives"},{"id":"e","text":"Trying things to gather information"},{"id":"f","text":"Freezing and letting it decide itself"}],"bins":[{"id":"healthy","label":"Healthy way","valence":"pos"},{"id":"anxious","label":"Anxious way","valence":"neg"}],"key":{"a":"healthy","b":"anxious","c":"healthy","d":"anxious","e":"healthy","f":"anxious"},"relearn":"Steadying first, weighing fit and trying things are healthy; panic-picking, appeasing and freezing are anxious.","persona":"any","source":"how to choose"},
  {"id":"ff-1370","cat":"your-path","type":"branch","hook":"You want to switch from the 'safe' degree your parents chose.","options":[{"text":"Make a calm case with a small plan, after steadying yourself","consequence":"You raise it from steadiness, not a fight.","outcome":"steady","best":true},{"text":"Spring the switch in the heat of an argument","consequence":"A calm case with a small plan beats springing it mid-argument when no one can hear you."}],"debrief":"Big changes land better from a steady place with a small plan, not a clash.","relearn":"Raise a direction change calmly, with a small plan, once you've steadied.","persona":"Zoya","source":"raise it steady"},
  {"id":"ff-1371","cat":"your-path","type":"reflect","hook":"Lensy: 'fit' is a better compass than 'impressive'. Which would you rather follow?","prompt":"What do you think?","options":["Fit","Impressive","Fit, honestly"],"affirm":"Whatever you picked, notice this: a path that fits you is one you can sustain long after the applause fades.","relearn":"Fit is a better long-term compass than impressive.","persona":"any","source":"fit over impressive"},
  {"id":"ff-1373","cat":"your-path","type":"strike-rewrite","hook":"\"Taking a non-traditional path means I've thrown my degree away.\"","myth":{"un":"A non-traditional path means I threw my degree away.","re":"Skills, discipline and knowledge from a degree travel with you, whatever direction you take next.","why":"What you learned doesn't vanish when you pivot."},"relearn":"A non-traditional path doesn't waste your degree; its skills travel with you.","persona":"any","source":"degree travels"},
  {"id":"ff-1374","cat":"your-path","type":"reflect","hook":"Lensy: there isn't one right life waiting to be guessed; there are many that could fit you. Lighter?","prompt":"What do you think?","options":["Yes","Many fit","Less pressure"],"affirm":"Believing there's one secret 'right life' makes every choice terrifying; many good lives could fit you.","relearn":"There isn't one secret right life to guess; many lives could genuinely fit you.","persona":"any","source":"many right lives"},
  {"id":"ff-1375","cat":"your-path","type":"branch","hook":"You've drifted for months, scrolling instead of taking a step.","options":[{"text":"Set one tiny action for tomorrow and tell someone","consequence":"You add a small structure and a witness.","outcome":"started","best":true},{"text":"Wait for motivation to strike before doing anything","consequence":"One tiny action you've told someone about beats waiting for motivation; it follows action."}],"debrief":"Motivation usually follows action; one tiny committed step breaks the drift.","relearn":"Set one tiny action and tell someone; motivation follows the step, not the wait.","persona":"any","source":"break the drift"},
  {"id":"ff-1376","cat":"your-path","type":"sort","hook":"Sort: a question that helps you find your direction, or one that traps you?","items":[{"id":"a","text":"\"What did I enjoy learning lately?\""},{"id":"b","text":"\"Why am I behind everyone?\""},{"id":"c","text":"\"What small thing could I try next?\""},{"id":"d","text":"\"Why can't I have it all figured out?\""},{"id":"e","text":"\"Whose work do I admire and why?\""},{"id":"f","text":"\"What if every choice is a mistake?\""}],"bins":[{"id":"helps","label":"Helps you find it","valence":"pos"},{"id":"traps","label":"Traps you","valence":"neg"}],"key":{"a":"helps","b":"traps","c":"helps","d":"traps","e":"helps","f":"traps"},"relearn":"Curious, forward questions help you find direction; comparison and 'all figured out' questions just trap you.","persona":"any","source":"better questions"},
  {"id":"ff-1377","cat":"your-path","type":"branch","hook":"You want to test an interest but fear wasting time if it's not 'the one'.","options":[{"text":"Treat the trial as information either way","consequence":"You can't lose; a misfit is also useful data.","outcome":"informed","best":true},{"text":"Skip trying anything you're not already sure about","consequence":"Treating a trial as information beats skipping it; a 'not for me' is useful too."}],"debrief":"A trial that ends in 'not for me' isn't wasted; it narrows the map.","relearn":"Trying an interest teaches you either way; a 'no' is useful data, not wasted time.","persona":"any","source":"trial is data"},
  {"id":"ff-1378","cat":"your-path","type":"reflect","hook":"Lensy: agency is taking the future from a thing that happens to you to a thing you nudge. Nudge it?","prompt":"What do you think?","options":["Yes","I'll nudge it","Take agency"],"affirm":"You can't control the whole future, but each small choice nudges it; that nudge is your agency.","relearn":"Agency is nudging your future with small choices, not controlling all of it.","persona":"any","source":"nudge the future"},
  {"id":"ff-1379","cat":"your-path","type":"branch","hook":"A viral reel insists you must 'find your one true passion' or fail.","options":[{"text":"Drop the one-passion myth; build from interest and skill","consequence":"You free yourself from a false rule.","outcome":"free","best":true},{"text":"Panic that you have no single burning passion","consequence":"Building from interest and growing skill beats panicking over a passion most never find."}],"debrief":"The 'one true passion' idea paralyses; interest plus growing skill is the real engine.","relearn":"You don't need one true passion; build from interest and growing skill.","persona":"any","source":"passion myth"},
  {"id":"ff-1380","cat":"your-path","type":"match","hook":"Match each future-anxiety to the one concrete step that answers it.","pairs":[{"left":"\"I don't know what I'm good at\"","right":"List three things people thank you for"},{"left":"\"I have no experience\"","right":"Do one small project this month"},{"left":"\"I know no one in the field\"","right":"Message one person you admire"},{"left":"\"I can't decide\"","right":"Try the smallest version of each"},{"left":"\"I feel completely stuck\"","right":"Talk it through with a mentor"}],"relearn":"Every vague future-fear has one concrete next step that makes it doable.","persona":"any","source":"fear to step"},
  {"id":"ff-1381","cat":"your-path","type":"strike-rewrite","hook":"\"Asking what fits me is selfish when my family sacrificed so much.\"","myth":{"un":"Choosing what fits me is selfish after my family's sacrifice.","re":"Honouring their sacrifice and choosing a path you can sustain aren't opposites; a path you'll burn out of helps no one.","why":"A sustainable path serves you and them."},"relearn":"Choosing a path that fits you isn't selfish; a sustainable path honours their sacrifice too.","persona":"Deepak","source":"fit isn't selfish"},
  {"id":"ff-1383","cat":"your-path","type":"sort","hook":"Sort: a thought that holds your own path, or one that surrenders it?","items":[{"id":"a","text":"\"I can choose what fits me\""},{"id":"b","text":"\"I must do what they expect\""},{"id":"c","text":"\"My direction can be mine\""},{"id":"d","text":"\"It's not my place to decide\""},{"id":"e","text":"\"I get a say in my life\""},{"id":"f","text":"\"Everyone else knows better than me\""}],"bins":[{"id":"holds","label":"Holds your path","valence":"pos"},{"id":"surrenders","label":"Surrenders it","valence":"neg"}],"key":{"a":"holds","b":"surrenders","c":"holds","d":"surrenders","e":"holds","f":"surrenders"},"relearn":"'I can choose', 'mine' and 'I get a say' hold your path; 'must', 'not my place' and 'everyone knows better' surrender it.","persona":"any","source":"hold your path"},
  {"id":"ff-1384","cat":"your-path","type":"branch","hook":"You want to freelance but feel you need permission first.","options":[{"text":"Start one small paid task; let results make the case","consequence":"You build proof instead of waiting for approval.","outcome":"proven","best":true},{"text":"Wait until everyone agrees it's a good idea","consequence":"Starting one small task and showing results beats waiting for permission."}],"debrief":"You rarely need universal approval to start; one finished task speaks louder than a debate.","relearn":"Start one small task; results make a better case than waiting for permission.","persona":"Meena","source":"results not permission"},
  {"id":"ff-1385","cat":"your-path","type":"reflect","hook":"Lensy: the next step doesn't have to be the right step forever, just the next honest one. Take it?","prompt":"What do you think?","options":["Yes","Just the next one","I can take it"],"affirm":"You don't have to get the whole path right; you just have to take the next honest step and keep adjusting.","relearn":"The next step only has to be the next honest one, not right forever.","persona":"any","source":"next honest step"},
  {"id":"ff-1386","cat":"your-path","type":"branch","hook":"You're between a stable job and a riskier path you want.","options":[{"text":"Test the wanted path on the side before you leap","consequence":"You gather real evidence with a safety net.","outcome":"tested","best":true},{"text":"Quit on impulse or bury the want completely","consequence":"Testing it on the side beats both impulsive quitting and burying what you want."}],"debrief":"You needn't choose blindly; testing the riskier path alongside the stable one gives evidence.","relearn":"Test a wanted path on the side first; gather evidence before you leap.","persona":"any","source":"test before leap"},
  {"id":"ff-1388","cat":"your-path","type":"sort","hook":"Sort: a real reason a path fits, or just a pressure dressed as a reason?","items":[{"id":"a","text":"\"The work itself pulls me in\""},{"id":"b","text":"\"People will stop asking questions\""},{"id":"c","text":"\"I'd keep learning here\""},{"id":"d","text":"\"It's what's expected of me\""},{"id":"e","text":"\"It suits the life I want\""},{"id":"f","text":"\"Everyone my age is doing it\""}],"bins":[{"id":"real","label":"A real reason","valence":"pos"},{"id":"pressure","label":"Pressure in disguise","valence":"uhoh"}],"key":{"a":"real","b":"pressure","c":"real","d":"pressure","e":"real","f":"pressure"},"relearn":"Genuine pull, learning and life-fit are real reasons; silencing questions, expectation and 'everyone' are pressure.","persona":"any","source":"reason vs pressure"},
  {"id":"ff-1389","cat":"your-path","type":"branch","hook":"You found a direction; now you fear telling your parents.","options":[{"text":"Share it with one small proof of how you'll make it work","consequence":"You meet their worry with a plan, not just a wish.","outcome":"grounded","best":true},{"text":"Announce it with no plan and brace for the fight","consequence":"A small concrete plan beats a plan-less announcement that invites a fight."}],"debrief":"Parents often fear the unknown; a small plan turns your direction into a path they can see.","relearn":"Share a new direction with one small proof of how you'll make it work.","persona":"Aarti","source":"share with a plan"},
  {"id":"ff-1390","cat":"your-path","type":"match","hook":"Match the agency move to what it quietly builds.","pairs":[{"left":"Choosing one step over a perfect plan","right":"Momentum"},{"left":"Naming what you actually value","right":"A real compass"},{"left":"Saying a gentle no to a misfit","right":"Room for a yes that fits"},{"left":"Asking someone how they got in","right":"A map you didn't have"},{"left":"Reviewing what worked each week","right":"A path that self-corrects"}],"relearn":"Small agency moves each build something real: momentum, a compass, room, a map, a path that corrects itself.","persona":"any","source":"agency builds"},
  {"id":"ff-1391","cat":"your-path","type":"branch","hook":"You fear choosing your own path means losing family's love.","options":[{"text":"Hold the path gently and keep showing up at home","consequence":"You don't trade connection for direction.","outcome":"both","best":true},{"text":"Assume you must pick either your path or their love","consequence":"Holding your path while staying connected beats believing you must choose one."}],"debrief":"Your direction and staying close usually aren't opposites; you can hold both, gently.","relearn":"You can hold your own path and stay connected; it rarely has to be either-or.","persona":"Zoya","source":"path and love"},
  {"id":"ff-1394","cat":"your-path","type":"reflect","hook":"Lensy: your path is allowed to be quieter than the loudest one in the room. Keep yours?","prompt":"What do you think?","options":["Yes","Keep mine","Quiet is fine"],"affirm":"The loudest path isn't the best one for everyone; a quieter path that fits you is fully valid.","relearn":"Your path can be quieter than the loudest one and still be the right one for you.","persona":"any","source":"quieter path"},
  {"id":"ff-1396","cat":"your-path","type":"sort","hook":"Sort: a path-choosing habit that serves you, or one that quietly drains you?","items":[{"id":"a","text":"Checking choices against your values"},{"id":"b","text":"Outsourcing every decision to others"},{"id":"c","text":"Reviewing and adjusting as you learn"},{"id":"d","text":"Choosing only to avoid disapproval"},{"id":"e","text":"Taking small, reversible steps"},{"id":"f","text":"Waiting for certainty before any move"}],"bins":[{"id":"serves","label":"Serves you","valence":"pos"},{"id":"drains","label":"Quietly drains you","valence":"neg"}],"key":{"a":"serves","b":"drains","c":"serves","d":"drains","e":"serves","f":"drains"},"relearn":"Checking values, adjusting and small reversible steps serve you; outsourcing, appeasing and waiting drain you.","persona":"any","source":"habits that serve"},
  {"id":"ff-1397","cat":"your-path","type":"branch","hook":"A senior offers to mentor you, but you feel unworthy of their time.","options":[{"text":"Accept, come prepared with two clear questions","consequence":"You honour their time and your own growth.","outcome":"open","best":true},{"text":"Decline so you don't 'bother' them","consequence":"Accepting with clear questions beats declining out of feeling unworthy; mentors offer to help."}],"debrief":"Feeling unworthy of guidance is common and usually false; a prepared 'yes' serves you both.","relearn":"Accept mentorship with prepared questions; you're not a bother for being guided.","persona":"Rohan","source":"accept the mentor"},
  {"id":"ff-1398","cat":"your-path","type":"reflect","hook":"Lensy: finding your feet isn't one big leap; it's a hundred small steps you can start today. Start one?","prompt":"What do you think?","options":["Yes","Start one","Step by step"],"affirm":"You find your feet by walking, not by leaping; a hundred small steps, beginning with the one you take today.","relearn":"Finding your feet is many small steps, not one leap; you can start one today.","persona":"any","source":"steps not leaps"},
  {"id":"ff-1399","cat":"your-path","type":"branch","hook":"You compare your messy path to a friend's neat one.","options":[{"text":"Stay on your own path; take your own next small step","consequence":"You stop measuring your road by someone else's.","outcome":"yours","best":true},{"text":"Abandon your path to chase a copy of theirs","consequence":"Your own next step beats abandoning your path to copy one built for a different life."}],"debrief":"A neat-looking path isn't more valid than a messy one; yours just needs your next step.","relearn":"Stay on your own path and take your own next step; don't copy someone else's road.","persona":"any","source":"your road"},
  {"id":"ff-1404","cat":"your-path","type":"sort","hook":"Sort: a step that's genuinely values-based, or one that's just chasing approval?","items":[{"id":"a","text":"Learning a craft you find meaningful"},{"id":"b","text":"Picking a field to impress neighbours"},{"id":"c","text":"Building toward how you want to live"},{"id":"d","text":"Chasing a title for the photo"},{"id":"e","text":"Choosing work that uses your strengths"},{"id":"f","text":"Doing it so people stop judging you"}],"bins":[{"id":"values","label":"Values-based","valence":"pos"},{"id":"approval","label":"Approval-chasing","valence":"uhoh"}],"key":{"a":"values","b":"approval","c":"values","d":"approval","e":"values","f":"approval"},"relearn":"Meaning, life-fit and your strengths are values-based; titles and dodging judgment chase approval.","persona":"any","source":"values vs approval"},
  {"id":"ff-1406","cat":"your-path","type":"reflect","hook":"Lensy: pick one truth to carry about your path.","prompt":"Pick one.","options":["Many paths can fit me","One small step is enough","Fit beats impressive","My direction can be mine"],"affirm":"Hold that one close; it turns the open future from a threat into something you can actually walk into.","relearn":"Many paths can fit; one small step is enough; fit beats impressive; your direction can be yours.","persona":"any","source":"carry forward"},
  {"id":"ff-1407","cat":"your-path","type":"strike-rewrite","hook":"\"A gap year or a detour means I've fallen permanently behind.\"","myth":{"un":"A gap year or detour means I've fallen permanently behind.","re":"Detours often add skills, clarity and stories that a straight line never would; 'behind' assumes one fixed track.","why":"There is no single track everyone is racing on."},"relearn":"A gap or detour isn't falling behind; it often adds clarity a straight line can't.","persona":"any","source":"detours add"},
  {"id":"ff-1412","cat":"your-path","type":"sort","hook":"Sort: a starting point that builds a path, or a dead end that stalls one?","items":[{"id":"a","text":"\"Let me try one small thing\""},{"id":"b","text":"\"There's no point in trying\""},{"id":"c","text":"\"I can learn this as I go\""},{"id":"d","text":"\"I must know it all first\""},{"id":"e","text":"\"One step today is enough\""},{"id":"f","text":"\"It's hopeless without a plan\""}],"bins":[{"id":"start","label":"A starting point","valence":"pos"},{"id":"deadend","label":"A dead end","valence":"neg"}],"key":{"a":"start","b":"deadend","c":"start","d":"deadend","e":"start","f":"deadend"},"relearn":"'Try one small thing', 'learn as I go' and 'one step is enough' start a path; 'no point' and 'must know it all' stall it.","persona":"any","source":"start vs dead end"},
  {"id":"ff-1413","cat":"your-path","type":"branch","hook":"You're choosing between fast money now and a slower path you'd love.","options":[{"text":"Weigh both against the life you actually want","consequence":"You decide by your values, not just the bigger number.","outcome":"aligned","best":true},{"text":"Auto-pick the bigger number and ignore the fit","consequence":"Weighing both against the life you want beats auto-picking the bigger number."}],"debrief":"Money matters and isn't the only factor; weigh both against the life you want.","relearn":"Weigh money and fit against the life you want, not just the bigger number.","persona":"any","source":"money and fit"},
  {"id":"ff-1415","cat":"your-path","type":"reflect","hook":"Lensy: you're allowed to choose a path now and revise it later. Both can be true. Choose anyway?","prompt":"What do you think?","options":["Yes","Choose and revise","Both true"],"affirm":"Choosing now and revising later aren't a contradiction; that's just how a real, living path works.","relearn":"You can choose a path now and revise it later; both are allowed and normal.","persona":"any","source":"choose and revise"},
  {"id":"ff-1417","cat":"your-path","type":"branch","hook":"You finally chose a direction and now doubt floods in.","options":[{"text":"Treat doubt as normal and commit to a trial period","consequence":"You give the choice a fair chance to prove itself.","outcome":"committed","best":true},{"text":"Read the doubt as proof you chose wrong and quit","consequence":"Giving the choice a fair trial beats reading normal doubt as proof you chose wrong."}],"debrief":"Doubt after deciding is normal, not a verdict; a trial period lets the choice show its real fit.","relearn":"Doubt after choosing is normal; give the choice a fair trial before judging it.","persona":"any","source":"doubt is normal"},
  {"id":"ff-1418","cat":"your-path","type":"match","hook":"Match each 'I'm stuck' feeling to a small move that loosens it.","pairs":[{"left":"\"Too many options\"","right":"Cut the list to your top two"},{"left":"\"No information\"","right":"Find one person who's done it"},{"left":"\"No time\"","right":"Block fifteen minutes today"},{"left":"\"Scared to start\"","right":"Pick the easiest possible first action"},{"left":"\"It's all on me\"","right":"Ask one trusted person to think with you"}],"relearn":"Every flavour of stuck has a small loosening move; you needn't solve it all at once.","persona":"any","source":"loosen the stuck"},
  {"id":"ff-1420","cat":"your-path","type":"spot","hook":"Spot the two lines that hand your path to someone else's idea of success.","scene":[{"id":"a","text":"\"I'll choose what genuinely fits me\"","trick":false},{"id":"b","text":"\"I'll just do whatever impresses relatives\"","trick":true},{"id":"c","text":"\"I get a real say in my own direction\"","trick":false},{"id":"d","text":"\"It's not my place to want my own path\"","trick":true},{"id":"e","text":"\"My next step can start from my values\"","trick":false}],"why":"'Whatever impresses relatives' and 'not my place' hand your direction to others; the rest hold it.","relearn":"Chasing approval or denying your say surrenders your path; values-based choosing holds it.","persona":"any","source":"surrender vs hold"},
  {"id":"ff-1421","cat":"your-path","type":"spot","hook":"Spot the two lines that mistake 'impressive' for 'right for me'.","scene":[{"id":"a","text":"\"I'll pick it because it sounds prestigious\"","trick":true},{"id":"b","text":"\"I'll pick what suits how I want to live\"","trick":false},{"id":"c","text":"\"I'll choose it to look successful online\"","trick":true},{"id":"d","text":"\"I'll choose work I'd find meaningful\"","trick":false},{"id":"e","text":"\"I'll weigh fit, not just the status\"","trick":false}],"why":"'Sounds prestigious' and 'look successful online' chase status, not fit; the rest choose what suits you.","relearn":"Choosing for prestige or online image mistakes impressive for fit; fit is the better test.","persona":"any","source":"impressive vs fit"},
  {"id":"ff-1422","cat":"your-path","type":"spot","hook":"Spot the two lines that turn a setback into a verdict on your path.","scene":[{"id":"a","text":"\"This step flopped, so I'll adjust it\"","trick":false},{"id":"b","text":"\"One miss means my whole direction is wrong\"","trick":true},{"id":"c","text":"\"That's feedback on the move, not on me\"","trick":false},{"id":"d","text":"\"I clearly have no business trying at all\"","trick":true},{"id":"e","text":"\"I'll keep the path and fix the step\"","trick":false}],"why":"'My whole direction is wrong' and 'no business trying' make a verdict of a setback; the rest treat it as feedback.","relearn":"Turning a setback into a verdict is the trap; it's feedback on the step.","persona":"any","source":"setback vs verdict"},
  {"id":"ff-1423","cat":"your-path","type":"spot","hook":"Spot the two lines that wait for a perfect map instead of taking a step.","scene":[{"id":"a","text":"\"I'll take one small step this week\"","trick":false},{"id":"b","text":"\"I won't move until I see the whole plan\"","trick":true},{"id":"c","text":"\"I can learn the rest as I go\"","trick":false},{"id":"d","text":"\"There's no point starting without certainty\"","trick":true},{"id":"e","text":"\"The next stair is enough to climb\"","trick":false}],"why":"'Until I see the whole plan' and 'no point without certainty' freeze you; the rest start with a step.","relearn":"Waiting for a perfect map is the trap; one next step is enough to start.","persona":"any","source":"map vs step"},
  {"id":"ff-1424","cat":"your-path","type":"spot","hook":"Spot the two lines that are pressure dressed up as a 'real' reason to choose.","scene":[{"id":"a","text":"\"The work itself genuinely pulls me in\"","trick":false},{"id":"b","text":"\"Everyone my age is doing it\"","trick":true},{"id":"c","text":"\"I'd keep growing in this\"","trick":false},{"id":"d","text":"\"People will finally stop questioning me\"","trick":true},{"id":"e","text":"\"It fits the life I actually want\"","trick":false}],"why":"'Everyone my age is doing it' and 'stop questioning me' are pressure, not fit; the rest are real reasons.","relearn":"'Everyone's doing it' and 'to silence questions' are pressure in disguise, not real reasons.","persona":"any","source":"pressure vs reason"},
  {"id":"ff-1425","cat":"your-path","type":"spot","hook":"Spot the two lines where future-anxiety is talking, not your real path.","scene":[{"id":"a","text":"\"I can try one thing and learn from it\"","trick":false},{"id":"b","text":"\"If I don't pick now, every door slams shut\"","trick":true},{"id":"c","text":"\"Pivots and second starts are normal\"","trick":false},{"id":"d","text":"\"I'm hopelessly, permanently behind\"","trick":true},{"id":"e","text":"\"My direction can grow as I do\"","trick":false}],"why":"'Every door slams shut' and 'permanently behind' are anxiety talking; the rest are the steadier view.","relearn":"'Doors slam shut' and 'permanently behind' are anxiety, not truth; pivots are normal.","persona":"any","source":"anxiety vs truth"},
  {"id":"ff-1426","cat":"your-path","type":"spot","hook":"Spot the two lines that copy another's path instead of building your own.","scene":[{"id":"a","text":"\"I'll take my own next step toward what fits\"","trick":false},{"id":"b","text":"\"I'll just clone my friend's exact plan\"","trick":true},{"id":"c","text":"\"I'll borrow their method, keep my direction\"","trick":false},{"id":"d","text":"\"I'll drop my path to copy theirs wholesale\"","trick":true},{"id":"e","text":"\"My messy path is still mine to walk\"","trick":false}],"why":"'Clone the exact plan' and 'copy theirs wholesale' abandon your path; the rest keep your direction.","relearn":"Cloning a friend's whole plan abandons your path; borrow methods, keep yours.","persona":"any","source":"copy vs build"},
  {"id":"ff-1427","cat":"your-path","type":"spot","hook":"Spot the two lines that treat exploring as failing instead of finding out.","scene":[{"id":"a","text":"\"Trying things is how I learn what fits\"","trick":false},{"id":"b","text":"\"Not knowing yet means I've already failed\"","trick":true},{"id":"c","text":"\"A 'no' from a trial is useful information\"","trick":false},{"id":"d","text":"\"Changing direction proves I wasted everything\"","trick":true},{"id":"e","text":"\"Exploring is part of choosing well\"","trick":false}],"why":"'Not knowing means I failed' and 'changing wasted everything' shame exploring; the rest honour it.","relearn":"Treating exploration as failure is the trap; trying and pivoting find a fit.","persona":"any","source":"explore vs fail"},
  {"id":"ff-1428","cat":"your-path","type":"strike-rewrite","hook":"\"My path has to look impressive to others, or it doesn't count.\"","myth":{"un":"My path has to look impressive to others, or it doesn't count.","re":"A path counts when it fits you and you can sustain it; an audience's approval is not the measure.","why":"You're the one who has to live it, not them."},"relearn":"A path counts when it fits and you can sustain it, not when it impresses an audience.","persona":"any","source":"counts if it fits"},
  {"id":"ff-1429","cat":"your-path","type":"role-play","hook":"A relative asks 'so what's the plan?' and you have a direction but no neat title yet.","setup":"Answer with calm honesty. Say:","yourLine":[{"text":"\"I'm building toward work I care about, one step at a time, and I'm okay with that.\"","best":true},{"text":"Mumble an apology and pretend you have it all mapped"}],"relearn":"You can name your direction calmly without faking a finished, titled master plan.","persona":"any","source":"the plan question"},
  {"id":"ff-1430","cat":"your-path","type":"role-play","hook":"A friend insists you copy their 'guaranteed' path because yours looks uncertain.","setup":"Hold your direction warmly. Say:","yourLine":[{"text":"\"I'm glad it fits you. Mine's different, and I want to give my own path a real try.\"","best":true},{"text":"Agree to abandon your path just to end the conversation"}],"relearn":"You can appreciate a friend's path and still hold your own different direction.","persona":"any","source":"hold your direction"},
  {"id":"ff-1431","cat":"your-path","type":"role-play","hook":"Your parents want a 'safe settled job'; you want to explore a different field first.","setup":"Bridge care and your path. Say:","yourLine":[{"text":"\"I hear the worry. Let me test this field for a few months with a real plan, then we decide.\"","best":true},{"text":"Snap that they never understand and shut the talk down"}],"relearn":"You can honour a parent's worry and still ask for room to test your own direction.","persona":"Aarti","source":"bridge with parents"},
  {"id":"ff-1432","cat":"your-path","type":"role-play","hook":"You want to ask a busy professional to spare ten minutes about their field.","setup":"Make a clear, easy ask. Say:","yourLine":[{"text":"\"I admire your work and I'm exploring this field. Could I ask you two quick questions sometime?\"","best":true},{"text":"Assume you're not worth their time and never reach out"}],"relearn":"A short, specific, respectful ask makes it easy for someone to give you ten minutes.","persona":"Deepak","source":"the clear ask"},
  {"id":"ff-1433","cat":"your-path","type":"role-play","hook":"A friend keeps apologising for not having a 'real plan' yet at twenty.","setup":"Take the pressure off them. Say:","yourLine":[{"text":"\"Nobody's fully sorted at twenty. Pick one thing you're curious about and just try it.\"","best":true},{"text":"\"Yeah, you really should have it figured out by now.\""}],"relearn":"You can free a friend from the 'real plan' pressure and point them to one curious step.","persona":"any","source":"free a friend"},
  {"id":"ff-1434","cat":"your-path","type":"role-play","hook":"A mentor asks what you actually want, and you're tempted to give the 'expected' answer.","setup":"Answer honestly instead. Say:","yourLine":[{"text":"\"Honestly, I'm still exploring, but I'm drawn to work that lets me build and help. Can we start there?\"","best":true},{"text":"Recite the safe expected answer you don't really mean"}],"relearn":"Honest, exploring answers to a mentor get you better guidance than reciting the expected one.","persona":"Rohan","source":"honest with a mentor"},
  {"id":"ff-1435","cat":"your-path","type":"role-play","hook":"A cousin brags that their single fixed path is the only 'serious' one.","setup":"Hold your ground kindly. Say:","yourLine":[{"text":"\"That's great for you. There's more than one serious path, and I'm building the one that fits me.\"","best":true},{"text":"Quietly agree that your direction must be less serious"}],"relearn":"You can affirm someone's path while holding that more than one serious path exists, including yours.","persona":"any","source":"more than one serious path"},
];

